// --- 2. BASIC DSP CLASSES (Oscillator, Filter, Envelope) ---

class PolyBLEP {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
  }

  get(t, dt) {
    if (dt < 1e-9) return 0.0;
    if (t < dt) {
      t /= dt;
      return t + t - t * t - 1.0;
    } else if (t > 1.0 - dt) {
      t = (t - 1.0) / dt;
      return t * t + t + t + 1.0;
    }
    return 0.0;
  }
}

class SVF {
  constructor() {
    this.low = 0.0;
    this.band = 0.0;
    this.high = 0.0;
    this.notch = 0.0;
  }

  reset() {
    this.low = 0.0;
    this.band = 0.0;
    this.high = 0.0;
    this.notch = 0.0;
  }

  process(input, cutoff, res, sampleRate, type, peakGain = 1.0) {
    // Safe Cutoff range: 20Hz to Nyquist (approx)
    const safeCutoff = Math.max(20, Math.min(cutoff, sampleRate * 0.45));

    // Chamberlin SVF tuning
    let f = 2.0 * Math.sin(Math.PI * safeCutoff / sampleRate);
    const q = 1.0 / (res + 0.5);

    this.low += f * this.band;
    this.high = input - this.low - q * this.band;
    this.band += f * this.high;
    this.notch = this.high + this.low;

    // 0=Low, 1=High, 2=Band, 3=Notch, 4=Peak, 5=LowShelf, 6=HighShelf
    switch((type|0)) {
        case 0: return this.low;
        case 1: return this.high;
        case 2: return this.band;
        case 3: return this.notch;
        case 4: return this.low + this.high + (this.band * peakGain);
        case 5: return (this.low * peakGain) + this.high + this.band;
        case 6: return this.low + (this.high * peakGain) + this.band;
        default: return this.low;
    }
  }
}

class ResonatorBank {
    constructor() {
        this.f1 = new SVF();
        this.f2 = new SVF();
        this.f3 = new SVF();
        this.currentSweep = -1; // Force update on first run
    }

    reset() {
        this.f1.reset();
        this.f2.reset();
        this.f3.reset();
        this.currentSweep = -1;
    }

    // Interpolate resonator params with pitch scaling (Key Tracking)
    process(input, sweep, pitchHz, sampleRate) {
        // Sweep 0-1 maps through 5 resonator states

        const pos = Math.max(0, Math.min(1, sweep)) * 4.0;
        const idx = Math.floor(pos);
        const frac = pos - idx;

        const nextIdx = Math.min(idx + 1, 4);

        const p1 = RESONANCES[idx];
        const p2 = RESONANCES[nextIdx];

        // Key Tracking / Scaling Logic
        // Reference frequency for formants/body is usually around 200Hz (Male/Alto range)
        // We scale centers up slightly as pitch rises to preserve brightness
        // Scale Factor: 10-15% of pitch ratio
        const pitchScale = 1.0 + 0.15 * Math.log2(Math.max(50, pitchHz) / 200);

        // Linear interpolation of freq * Scale
        const f1_freq = (p1.f1 + (p2.f1 - p1.f1) * frac) * pitchScale;
        const f2_freq = (p1.f2 + (p2.f2 - p1.f2) * frac) * pitchScale;
        const f3_freq = (p1.f3 + (p2.f3 - p1.f3) * frac) * pitchScale;

        // Gains
        const g1 = p1.g1 + (p2.g1 - p1.g1) * frac;
        const g2 = p1.g2 + (p2.g2 - p1.g2) * frac;
        const g3 = p1.g3 + (p2.g3 - p1.g3) * frac;

        // Bandpass processing with moderate Q (Resonance ~ 4-8)
        const res = 4.0; 

        // SVF Type 2 = Bandpass
        const out1 = this.f1.process(input, f1_freq, res, sampleRate, 2); 
        const out2 = this.f2.process(input, f2_freq, res, sampleRate, 2);
        const out3 = this.f3.process(input, f3_freq, res, sampleRate, 2);

        return (out1 * g1) + (out2 * g2) + (out3 * g3);
    }
}

class Envelope {
  constructor() {
    this.stage = 'idle'; 
    this.value = 0.0;
    this.velocity = 0.0;
  }

  trigger(velocity = 1.0) {
    this.stage = 'attack';
    this.velocity = velocity;
  }

  release() {
    if (this.stage !== 'idle') {
        this.stage = 'release';
    }
  }

  reset() {
      this.stage = 'idle';
      this.value = 0.0;
  }

  process(config, dt) {
    const att = (config.attack !== undefined) ? config.attack : 0.01;
    const dec = (config.decay !== undefined) ? config.decay : 0.1;
    const sus = (config.sustain !== undefined) ? config.sustain : 1.0;
    const rel = (config.release !== undefined) ? config.release : 0.1;

    switch (this.stage) {
      case 'idle':
        this.value = 0.0;
        return 0.0;

      case 'attack':
        const attRate = 1.0 / (Math.max(0.001, att));
        this.value += attRate * dt;
        if (this.value >= 1.0) {
          this.value = 1.0;
          this.stage = 'decay';
        }
        return this.value * this.velocity;

      case 'decay':
        const decRate = 1.0 / (Math.max(0.001, dec));
        this.value += (sus - this.value) * (decRate * dt * 5.0); 
        return this.value * this.velocity;

      case 'sustain':
        this.value = sus;
        return this.value * this.velocity;

      case 'release':
        const relRate = 1.0 / (Math.max(0.001, rel));
        this.value -= this.value * (relRate * dt * 5.0);
        if (this.value < 0.001) {
          this.value = 0.0;
          this.stage = 'idle';
        }
        return this.value * this.velocity;

      default:
        return 0.0;
    }
  }
}

class Oscillator {
  constructor(sampleRate) {
    this.phase = 0.0; 
    this.blep = new PolyBLEP(sampleRate);
    this.sampleRate = sampleRate;
  }

  reset() {
      // Free-running oscillators
  }

  process(freq, type, dt) {
    if (!Number.isFinite(freq) || freq <= 0 || freq > 24000) return 0.0;

    this.phase += dt * freq;
    while (this.phase >= 1.0) this.phase -= 1.0;

    let sample = 0.0;

    switch (type) {
      case 'sine':
        // High-performance LUT lookup
        {
            const index = this.phase * WAVETABLE_SIZE;
            const i = Math.floor(index);
            const f = index - i;
            // Linear Interpolation from pre-computed table
            sample = SINE_TABLE[i] + f * (SINE_TABLE[i + 1] - SINE_TABLE[i]);
        }
        break;
      case 'glottal':
        {
            const index = this.phase * WAVETABLE_SIZE;
            const i = Math.floor(index);
            const f = index - i;
            // Lookup from new Glottal table
            sample = GLOTTAL_TABLE[i] + f * (GLOTTAL_TABLE[i + 1] - GLOTTAL_TABLE[i]);
        }
        break;
      case 'triangle':
        {
            let t = -1.0 + (2.0 * this.phase);
            sample = 2.0 * (Math.abs(t) - 0.5);
        }
        break;
      case 'sawtooth':
        // PolyBLEP Saw is efficient and sounds good
        sample = (2.0 * this.phase) - 1.0;
        sample -= this.blep.get(this.phase, dt * freq);
        break;
      case 'square':
        // PolyBLEP Square
        sample = this.phase < 0.5 ? 1.0 : -1.0;
        sample += this.blep.get(this.phase, dt * freq);
        let phase2 = (this.phase + 0.5) % 1.0;
        sample -= this.blep.get(phase2, dt * freq);
        break;
      case 'noise':
        // White Noise
        sample = (Math.random() * 2.0) - 1.0;
        break;
    }

    return sample;
  }
}

// --- 3. VOICE LOGIC (Signal Path) ---

class Voice {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.active = false;
    this.id = '';
    this.type = 'normal'; // Preset selection
    this.mode = 'gate';   // Playback behavior: 'gate', 'trigger', 'latch'
    this.panPos = 0; 

    this.baseFreq = 440;
    this.targetFreq = 440;
    this.startTime = 0; 
    this.releaseTime = 0; 
    this.activeTime = 0.0; // Seconds active, for LFO delay

    this.oscs = [
        new Oscillator(sampleRate),
        new Oscillator(sampleRate),
        new Oscillator(sampleRate)
    ];

    this.filters = [ new SVF(), new SVF(), new SVF() ];
    this.resonator = new ResonatorBank();
    this.noiseFilter = new SVF(); // Dedicated Noise Filter

    this.envs = [ new Envelope(), new Envelope(), new Envelope() ];
    this.lfoPhases = [0.0, 0.0, 0.0];
    this.lfoRandoms = [0.0, 0.0, 0.0]; // Hold values for S&H (Noise LFO)
    this.envVals = new Float32Array(3);
    this.lfoVals = new Float32Array(3);
  }

  // Allow dynamic updates to sample rate when oversampling changes
  updateSampleRate(newRate) {
      if (this.sampleRate === newRate) return;
      this.sampleRate = newRate;
      this.oscs.forEach(osc => { osc.sampleRate = newRate; osc.blep.sampleRate = newRate; });
  }

  trigger(id, freq, type, mode) {
    this.id = id;
    this.type = type || 'normal';
    this.mode = mode || 'gate';
    this.baseFreq = freq;
    this.targetFreq = freq;
    this.active = true;
    this.startTime = currentTime; 
    this.releaseTime = 0; 
    this.activeTime = 0.0;

    this.envs.forEach(env => {
        // Soft reset to avoid clicks on retrigger
        env.trigger();
    });

    this.filters.forEach(f => f.reset());
    this.resonator.reset();
    this.noiseFilter.reset();
    this.lfoPhases.fill(0.0);
    // Initialize randoms
    this.lfoRandoms[0] = (Math.random() * 2.0) - 1.0;
    this.lfoRandoms[1] = (Math.random() * 2.0) - 1.0;
    this.lfoRandoms[2] = (Math.random() * 2.0) - 1.0;
  }

  release() {
    this.releaseTime = currentTime;
    this.envs.forEach(env => env.release());
  }

  hardStop() {
      this.active = false;
      this.envs.forEach(env => env.reset());
      this.filters.forEach(f => f.reset());
      this.resonator.reset();
      this.noiseFilter.reset();
  }

  getLevel() {
    return Math.max(this.envs[0].value, this.envs[1].value, this.envs[2].value);
  }

  // Helper to map string types to integer for optimized loop
  getFilterTypeId(type) {
      if (type === 'highpass') return 1;
      if (type === 'bandpass') return 2;
      if (type === 'notch') return 3;
      if (type === 'peak') return 4;
      if (type === 'lowshelf') return 5;
      if (type === 'highshelf') return 6;
      return 0; // lowpass
  }

  // Optimized block processing
  renderBlock(preset, dt, bufL, bufR, len, panSpeed, panDepth, startPanPhase, globalBend) {
    if (!this.active) return;

    // --- FREQ GLIDE ---
    const diff = this.targetFreq - this.baseFreq;
    if (Math.abs(diff) > 0.001) {
        const glideParam = preset.portamento !== undefined ? preset.portamento : 0;
        let coef = 0.005; // Fallback

        if (glideParam <= 0.01) {
            coef = 1.0; // Instant
        } else {
            const timeConst = glideParam * 0.5; // Up to 0.5s glide
            coef = 1.0 - Math.exp(- (len * dt) / timeConst);
        }

        this.baseFreq += diff * coef;
    } else {
      this.baseFreq = this.targetFreq;
    }

    // --- CACHED CONFIGS ---
    const osc1 = preset.osc1 || DUMMY_OSC_CONFIG;
    const osc2 = preset.osc2 || DUMMY_OSC_CONFIG;
    const osc3 = preset.osc3 || DUMMY_OSC_CONFIG;
    const matrix = preset.modMatrix || [];
    const spreadAmount = preset.spread || 0;
    const voiceGain = preset.gain || 0.5;

    // New Params (Renamed)
    const resonatorMix = preset.resonatorMix || 0;
    const resonatorSweep = preset.resonatorSweep || 0;
    const noiseGain = preset.noiseGain || 0;
    const noiseCutoff = preset.noiseCutoff || 4000;

    const hasMatrix = matrix.length > 0;

    // Filter Type Integers
    const fType1 = this.getFilterTypeId(osc1.filterType);
    const fType2 = this.getFilterTypeId(osc2.filterType);
    const fType3 = this.getFilterTypeId(osc3.filterType);

    // --- CHECK FOR SERIAL FILTER MODE (e.g. BRASS) ---
    // If Osc 1 is GLOTTAL, we switch to Serial Filtering topology
    // This allows constructing complex timbres like brass body resonances
    const isSerialMode = osc1.waveform === 'glottal';

    let anyEnvActive = false;
    let panPhase = startPanPhase;

    // Pre-calculate LFO rates to avoid dictionary lookup in tight loop
    const lfoRate1 = osc1.lfoRate || 0;
    const lfoRate2 = osc2.lfoRate || 0;
    const lfoRate3 = osc3.lfoRate || 0;

    // Pre-calculate LFO types
    const lfoType1 = osc1.lfoWaveform || 'sine';
    const lfoType2 = osc2.lfoWaveform || 'sine';
    const lfoType3 = osc3.lfoWaveform || 'sine';

    // OPTIMIZATION: Pre-calculate static frequencies if no modulation
    // Apply globalBend to the base frequency here
    let osc1StaticFreq = 0, osc2StaticFreq = 0, osc3StaticFreq = 0;
    let osc1ModPitch = false, osc2ModPitch = false, osc3ModPitch = false;

    // Check for pitch mod in Matrix or LFO
    if (osc1.enabled) {
        if (osc1.lfoTarget === 'pitch') osc1ModPitch = true;
        if (hasMatrix && matrix.some(r => r.enabled && r.target === 'osc1_pitch')) osc1ModPitch = true;

        if (!osc1ModPitch) {
            const cents = osc1.coarseDetune + osc1.fineDetune;
            osc1StaticFreq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
        }
    }

    if (osc2.enabled && !isSerialMode) {
        if (osc2.lfoTarget === 'pitch') osc2ModPitch = true;
        if (hasMatrix && matrix.some(r => r.enabled && r.target === 'osc2_pitch')) osc2ModPitch = true;

        if (!osc2ModPitch) {
            const cents = osc2.coarseDetune + osc2.fineDetune;
            osc2StaticFreq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
        }
    }

    if (osc3.enabled && !isSerialMode) {
        if (osc3.lfoTarget === 'pitch') osc3ModPitch = true;
        if (hasMatrix && matrix.some(r => r.enabled && r.target === 'osc3_pitch')) osc3ModPitch = true;

        if (!osc3ModPitch) {
            const cents = osc3.coarseDetune + osc3.fineDetune;
            osc3StaticFreq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
        }
    }

    // --- LFO DELAY CALCULATION ---
    // Linear fade-in of LFO depth based on activeTime
    this.activeTime += (len * dt);

    // 0.001 to prevent divide by zero
    const lfoFade1 = osc1.lfoDelay ? Math.min(1.0, this.activeTime / Math.max(0.01, osc1.lfoDelay)) : 1.0;
    const lfoFade2 = osc2.lfoDelay ? Math.min(1.0, this.activeTime / Math.max(0.01, osc2.lfoDelay)) : 1.0;
    const lfoFade3 = osc3.lfoDelay ? Math.min(1.0, this.activeTime / Math.max(0.01, osc3.lfoDelay)) : 1.0;

    for (let s = 0; s < len; s++) {
        // --- 1. MODULATORS ---
        anyEnvActive = false;

        // Unrolled Envelope & LFO processing
        // OSC 1
        const env1 = this.envs[0].process(osc1, dt);
        this.envVals[0] = env1;
        if (this.envs[0].stage !== 'idle') anyEnvActive = true;

        this.lfoPhases[0] += lfoRate1 * dt;
        if (this.lfoPhases[0] >= 1.0) {
            this.lfoPhases[0] -= 1.0;
            this.lfoRandoms[0] = (Math.random() * 2.0) - 1.0; // New random value on cycle reset
        }
        let lfoVal1 = 0;
        switch(lfoType1) {
            case 'sine': lfoVal1 = Math.sin(TWO_PI * this.lfoPhases[0]); break;
            case 'triangle': { const p = this.lfoPhases[0]; if(p < 0.25) lfoVal1 = 4 * p; else if(p < 0.75) lfoVal1 = 2 - 4 * p; else lfoVal1 = 4 * p - 4; break; }
            case 'square': lfoVal1 = this.lfoPhases[0] < 0.5 ? 1.0 : -1.0; break;
            case 'sawtooth': lfoVal1 = (2.0 * this.lfoPhases[0]) - 1.0; break;
            case 'noise': lfoVal1 = this.lfoRandoms[0]; break;
            default: lfoVal1 = Math.sin(TWO_PI * this.lfoPhases[0]);
        }
        this.lfoVals[0] = lfoVal1 * lfoFade1;

        // OSC 2
        const env2 = this.envs[1].process(osc2, dt);
        this.envVals[1] = env2;
        if (this.envs[1].stage !== 'idle') anyEnvActive = true;

        this.lfoPhases[1] += lfoRate2 * dt;
        if (this.lfoPhases[1] >= 1.0) {
            this.lfoPhases[1] -= 1.0;
            this.lfoRandoms[1] = (Math.random() * 2.0) - 1.0;
        }
        let lfoVal2 = 0;
        switch(lfoType2) {
            case 'sine': lfoVal2 = Math.sin(TWO_PI * this.lfoPhases[1]); break;
            case 'triangle': { const p = this.lfoPhases[1]; if(p < 0.25) lfoVal2 = 4 * p; else if(p < 0.75) lfoVal2 = 2 - 4 * p; else lfoVal2 = 4 * p - 4; break; }
            case 'square': lfoVal2 = this.lfoPhases[1] < 0.5 ? 1.0 : -1.0; break;
            case 'sawtooth': lfoVal2 = (2.0 * this.lfoPhases[1]) - 1.0; break;
            case 'noise': lfoVal2 = this.lfoRandoms[1]; break;
            default: lfoVal2 = Math.sin(TWO_PI * this.lfoPhases[1]);
        }
        this.lfoVals[1] = lfoVal2 * lfoFade2;

        // OSC 3
        const env3 = this.envs[2].process(osc3, dt);
        this.envVals[2] = env3;
        if (this.envs[2].stage !== 'idle') anyEnvActive = true;

        this.lfoPhases[2] += lfoRate3 * dt;
        if (this.lfoPhases[2] >= 1.0) {
            this.lfoPhases[2] -= 1.0;
            this.lfoRandoms[2] = (Math.random() * 2.0) - 1.0;
        }
        let lfoVal3 = 0;
        switch(lfoType3) {
            case 'sine': lfoVal3 = Math.sin(TWO_PI * this.lfoPhases[2]); break;
            case 'triangle': { const p = this.lfoPhases[2]; if(p < 0.25) lfoVal3 = 4 * p; else if(p < 0.75) lfoVal3 = 2 - 4 * p; else lfoVal3 = 4 * p - 4; break; }
            case 'square': lfoVal3 = this.lfoPhases[2] < 0.5 ? 1.0 : -1.0; break;
            case 'sawtooth': lfoVal3 = (2.0 * this.lfoPhases[2]) - 1.0; break;
            case 'noise': lfoVal3 = this.lfoRandoms[2]; break;
            default: lfoVal3 = Math.sin(TWO_PI * this.lfoPhases[2]);
        }
        this.lfoVals[2] = lfoVal3 * lfoFade3;

        if (!anyEnvActive && s === len - 1) {
            this.active = false;
        }

        // --- 2. MOD MATRIX ---
        let modP1=0, modC1=0, modG1=0, modR1=0;
        let modP2=0, modC2=0, modG2=0, modR2=0;
        let modP3=0, modC3=0, modG3=0, modR3=0;

        if (hasMatrix) {
            for(let m = 0; m < matrix.length; m++) {
                const row = matrix[m];
                if (!row.enabled) continue;

                let srcVal = 0;
                // Hardcoded source lookup for speed
                if (row.source === 'env1') srcVal = this.envVals[0];
                else if (row.source === 'env2') srcVal = this.envVals[1];
                else if (row.source === 'env3') srcVal = this.envVals[2];
                else if (row.source === 'lfo1') srcVal = this.lfoVals[0];
                else if (row.source === 'lfo2') srcVal = this.lfoVals[1];
                else if (row.source === 'lfo3') srcVal = this.lfoVals[2];

                const amt = srcVal * row.amount;

                // Hardcoded target lookup
                switch(row.target) {
                    case 'osc1_pitch': modP1 += amt; break;
                    case 'osc1_cutoff': modC1 += amt; break;
                    case 'osc1_gain': modG1 += amt; break;
                    case 'osc1_res': modR1 += amt; break;
                    case 'osc2_pitch': modP2 += amt; break;
                    case 'osc2_cutoff': modC2 += amt; break;
                    case 'osc2_gain': modG2 += amt; break;
                    case 'osc2_res': modR2 += amt; break;
                    case 'osc3_pitch': modP3 += amt; break;
                    case 'osc3_cutoff': modC3 += amt; break;
                    case 'osc3_gain': modG3 += amt; break;
                    case 'osc3_res': modR3 += amt; break;
                }
            }
        }

        // --- 3. VOICE GENERATION ---
        let voiceMix = 0.0;

        // --- OSC 1 (MASTER CARRIER FOR SERIAL/BRASS) ---
        if (osc1.enabled && this.envVals[0] > 0.0001) {
            let hardPitch = 0, hardFilter = 0, hardAmp = 1.0;
            const d = osc1.lfoDepth || 0;
            const v = this.lfoVals[0];
            if (osc1.lfoTarget === 'pitch') hardPitch = v * d;
            else if (osc1.lfoTarget === 'filter') hardFilter = v * d * 20;
            else if (osc1.lfoTarget === 'tremolo') hardAmp = 1.0 - (v * d * 0.005);

            let freq;
            if (osc1ModPitch) {
                const cents = osc1.coarseDetune + osc1.fineDetune + hardPitch + (modP1 * 1200);
                freq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
            } else {
                freq = osc1StaticFreq;
            }

            let sig = this.oscs[0].process(freq, osc1.waveform, dt);

            // SPECTRAL TILT (Acoustic Physics)
            // Open up the lowpass filter as the envelope gets louder (simulates sharper glottal closure/brightness)
            // Dynamic Range: ~2000Hz brightness added at peak velocity
            const tiltMod = isSerialMode ? (this.envVals[0] * 2000) : 0;

            const cut1 = osc1.filterCutoff + hardFilter + (modC1 * 5000) + tiltMod;
            const res1 = Math.max(0, osc1.filterResonance + (modR1 * 10));

            // F1: Standard Filter (Lowpass usually for Source)
            sig = this.filters[0].process(sig, cut1, res1, this.sampleRate, fType1);

            if (isSerialMode) {
                // Serial Chain: F1 -> F2 -> F3 -> Mix
                // Osc 2 is F2. Use osc2.gain as Peak Gain.
                // Map 0-1 gain to 0-8 boost for powerful resonance
                const gain2 = osc2.gain * 8.0;
                const cut2 = osc2.filterCutoff + (modC2 * 5000);
                const res2 = Math.max(0, osc2.filterResonance + (modR2 * 10));
                sig = this.filters[1].process(sig, cut2, res2, this.sampleRate, fType2, gain2); 

                // Osc 3 is F3. Use osc3.gain as Peak Gain.
                const gain3 = osc3.gain * 8.0;
                const cut3 = osc3.filterCutoff + (modC3 * 5000);
                const res3 = Math.max(0, osc3.filterResonance + (modR3 * 10));
                sig = this.filters[2].process(sig, cut3, res3, this.sampleRate, fType3, gain3); 

                // For serial mode, we rely on Osc 1 Gain & Env for the master output
                voiceMix += sig * osc1.gain * this.envVals[0] * hardAmp * Math.max(0, 1.0 + modG1);

                // --- NOISE LAYER (AIR/BREATH) ---
                // Additive noise layer processed by Highpass Filter
                // REVISED: Scale by env^2 to tighten noise envelope (focus on onset/transient)
                if (noiseGain > 0.001) {
                    let noise = (Math.random() * 2.0) - 1.0;
                    // Filter: Highpass (Type 1), Resonance 0.5 (Neutral)
                    noise = this.noiseFilter.process(noise, noiseCutoff, 0.5, this.sampleRate, 1);

                    // Tightened Envelope: Square the envelope value to make noise decay faster than tone
                    const tightEnv = this.envVals[0] * this.envVals[0];
                    voiceMix += noise * noiseGain * tightEnv * hardAmp * 0.5;
                }

            } else {
                // Standard Parallel Mode
                voiceMix += sig * osc1.gain * this.envVals[0] * hardAmp * Math.max(0, 1.0 + modG1);
            }
        }

        if (!isSerialMode) {
            // --- OSC 2 (Standard Mode) ---
            if (osc2.enabled && this.envVals[1] > 0.0001) {
                let hardPitch = 0, hardFilter = 0, hardAmp = 1.0;
                const d = osc2.lfoDepth || 0;
                const v = this.lfoVals[1];
                if (osc2.lfoTarget === 'pitch') hardPitch = v * d;
                else if (osc2.lfoTarget === 'filter') hardFilter = v * d * 20;
                else if (osc2.lfoTarget === 'tremolo') hardAmp = 1.0 - (v * d * 0.005);

                let freq;
                if (osc2ModPitch) {
                    const cents = osc2.coarseDetune + osc2.fineDetune + hardPitch + (modP2 * 1200);
                    freq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
                } else {
                    freq = osc2StaticFreq;
                }

                let sig = this.oscs[1].process(freq, osc2.waveform, dt);
                const cut = osc2.filterCutoff + hardFilter + (modC2 * 5000);
                const res = Math.max(0, osc2.filterResonance + (modR2 * 10));
                sig = this.filters[1].process(sig, cut, res, this.sampleRate, fType2);

                voiceMix += sig * osc2.gain * this.envVals[1] * hardAmp * Math.max(0, 1.0 + modG2);
            }

            // --- OSC 3 (Standard Mode) ---
            if (osc3.enabled && this.envVals[2] > 0.0001) {
                let hardPitch = 0, hardFilter = 0, hardAmp = 1.0;
                const d = osc3.lfoDepth || 0;
                const v = this.lfoVals[2];
                if (osc3.lfoTarget === 'pitch') hardPitch = v * d;
                else if (osc3.lfoTarget === 'filter') hardFilter = v * d * 20;
                else if (osc3.lfoTarget === 'tremolo') hardAmp = 1.0 - (v * d * 0.005);

                let freq;
                if (osc3ModPitch) {
                    const cents = osc3.coarseDetune + osc3.fineDetune + hardPitch + (modP3 * 1200);
                    freq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
                } else {
                    freq = osc3StaticFreq;
                }

                let sig = this.oscs[2].process(freq, osc3.waveform, dt);
                const cut = osc3.filterCutoff + hardFilter + (modC3 * 5000);
                const res = Math.max(0, osc3.filterResonance + (modR3 * 10));
                sig = this.filters[2].process(sig, cut, res, this.sampleRate, fType3);

                voiceMix += sig * osc3.gain * this.envVals[2] * hardAmp * Math.max(0, 1.0 + modG3);
            }
        }

        // --- 4. RESONATOR BANK (Parallel Bandpass Bank - Legacy or Extra Color) ---
        if (resonatorMix > 0.01) {
            // Updated to pass current pitch Frequency for Key Tracking
            // Using baseFreq adjusted by global bend (Osc1 Logic) as reference
            let trackingFreq = osc1StaticFreq; 
            if (osc1ModPitch) trackingFreq = this.baseFreq; // Simple fallback if heavily modulated

            const resSig = this.resonator.process(voiceMix, resonatorSweep, trackingFreq, this.sampleRate);
            // Mix Dry/Wet based on resonatorMix
            voiceMix = (voiceMix * (1.0 - resonatorMix)) + (resSig * resonatorMix * 1.5);
        }

        // --- 5. PANNING & OUTPUT ---
        panPhase += dt * panSpeed;
        if (panPhase > 1.0) panPhase -= 1.0;

        const autoPan = Math.sin(panPhase * TWO_PI) * panDepth;
        let p = this.panPos * spreadAmount;
        p += autoPan;
        p = Math.max(-1.0, Math.min(1.0, p));

        // Equal power pan approx
        const gainL = 0.5 * (1.0 - p);
        const gainR = 0.5 * (1.0 + p);

        bufL[s] += voiceMix * gainL * voiceGain;
        bufR[s] += voiceMix * gainR * voiceGain;
    }
  }
}

registerProcessor('synth-processor', PrismaProcessor);
`;

import { SynthPreset, AppSettings, ReverbType, PresetState, PlayMode, PlaybackMode } from '../types';
import { store } from './Store';
import { DEFAULT_PRESET, REVERB_DEFAULTS } from '../constants';
import { AUDIO_PROCESSOR_CODE } from './AudioProcessorCode';

// --- Typed Messages for Worklet ---
interface WorkletMessageBase {
    type: string;
    time?: number; // Optional timing for scheduling
}

interface UpdatePresetMessage extends WorkletMessageBase {
    type: 'update_preset';
    mode: string;
    data: any; // Normalized preset
}

interface ConfigMessage extends WorkletMessageBase {
    type: 'config';
    polyphony?: number;
    strumDuration?: number;
    enableOversampling?: boolean;
    globalBend?: number;
    wavetableSize?: number;
    interpolationType?: 'linear' | 'cubic';
}

interface NoteOnMessage extends WorkletMessageBase {
    type: 'note_on';
    id: string;
    freq: number;
    voiceType: string;
    mode: PlaybackMode;
}

interface NoteOffMessage extends WorkletMessageBase {
    type: 'note_off';
    id: string;
}

interface GlideMessage extends WorkletMessageBase {
    type: 'glide';
    id: string;
    freq: number;
}

interface StopAllMessage extends WorkletMessageBase {
    type: 'stop_all';
}

interface StopGroupMessage extends WorkletMessageBase {
    type: 'stop_group';
    prefix: string;
}

type AudioWorkletMessage = UpdatePresetMessage | ConfigMessage | NoteOnMessage | NoteOffMessage | GlideMessage | StopAllMessage | StopGroupMessage;

class AudioEngine {
  private ctx: AudioContext | null = null;
  private workletNode: AudioWorkletNode | null = null;
  private initPromise: Promise<void> | null = null;

  // Message Queue for pre-init commands
  private messageQueue: AudioWorkletMessage[] = [];

  // FX Chain
  private limiter: DynamicsCompressorNode | null = null;
  private masterFilter: BiquadFilterNode | null = null; // New Tone Control
  private dryGain: GainNode | null = null;
  private reverbNode: ConvolverNode | null = null;
  private reverbGain: GainNode | null = null;
  private delayNode: DelayNode | null = null;
  private delayFeedbackGain: GainNode | null = null;
  private delayOutputGain: GainNode | null = null;

  // Final Output Stage
  private finalMasterGain: GainNode | null = null;

  private currentMasterVol: number = 0.8;
  private globalSpatialScale: number = 1.0;
  private globalBrightness: number = 1.0; // 0.0 to 1.0

  // Cache active presets for FX updates
  private activePresets: PresetState;

  private voiceStealListeners: Set<(id: string) => void> = new Set();

  constructor() {
    // Initialize Presets safely
    const rawPresets = store.getSnapshot().presets;
    this.activePresets = {
        normal: this.ensurePresetSafety(rawPresets.normal),
        latch: this.ensurePresetSafety(rawPresets.latch),
        strum: this.ensurePresetSafety(rawPresets.strum),
        brass: this.ensurePresetSafety(rawPresets.brass),
        arpeggio: this.ensurePresetSafety(rawPresets.arpeggio)
    };

    // Auto-init to pre-load audio resources immediately
    this.init().catch(e => console.warn("Auto-init postponed (will retry on gesture)", e));

    store.subscribe(() => {
        const newPresets = store.getSnapshot().presets;
        this.updatePresets(newPresets);
    });
  }

  public onVoiceSteal(callback: (id: string) => void) {
      this.voiceStealListeners.add(callback);
      return () => { this.voiceStealListeners.delete(callback); };
  }

  private isMobile() {
      return /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
  }

  private ensurePresetSafety(p: any): SynthPreset {
     if (!p) return DEFAULT_PRESET;

     const validReverbTypes: ReverbType[] = ['room', 'hall', 'cathedral', 'plate', 'shimmer'];
     let rType: ReverbType = 'hall';

     if (p.reverbType && validReverbTypes.includes(p.reverbType)) {
         rType = p.reverbType as ReverbType;
     }

     const safe: SynthPreset = {
         ...DEFAULT_PRESET,
         ...p,
         osc1: { ...DEFAULT_PRESET.osc1, ...(p.osc1 || {}) },
         osc2: { ...DEFAULT_PRESET.osc2, ...(p.osc2 || {}) },
         osc3: { ...DEFAULT_PRESET.osc3, ...(p.osc3 || {}) },
         modMatrix: p.modMatrix || [],
         reverbType: rType,
         aspirationGain: p.aspirationGain !== undefined ? p.aspirationGain : 0,
         aspirationCutoff: p.aspirationCutoff !== undefined ? p.aspirationCutoff : 4000
     };

     const defaults = REVERB_DEFAULTS[rType];
     if (safe.reverbSize === undefined) safe.reverbSize = defaults.size;
     if (safe.reverbDamping === undefined) safe.reverbDamping = defaults.damping;
     if (safe.reverbDiffusion === undefined) safe.reverbDiffusion = defaults.diffusion;

     return safe;
  }

  private postMessage(msg: AudioWorkletMessage) {
      if (this.workletNode) {
          this.workletNode.port.postMessage(msg);
      } else {
          this.messageQueue.push(msg);
          // If we are queuing messages but not initializing, trigger init
          if (!this.initPromise && !this.ctx) {
              this.init();
          }
      }
  }

  public updateSettings(settings: AppSettings) {
      this.postMessage({ 
          type: 'config', 
          polyphony: settings.polyphony,
          strumDuration: settings.strumDuration,
          enableOversampling: settings.enableOversampling,
          wavetableSize: settings.wavetableSize,
          interpolationType: settings.interpolationType
      });
  }

  public updatePresets(newPresets: PresetState) {
      const modes: PlayMode[] = ['normal', 'latch', 'strum', 'brass', 'arpeggio'];
      let recomputeReverb = false;

      const oldMaster = this.activePresets.normal;
      const newMaster = newPresets.normal;

      if (
          oldMaster.reverbType !== newMaster.reverbType ||
          oldMaster.reverbSize !== newMaster.reverbSize ||
          oldMaster.reverbDamping !== newMaster.reverbDamping ||
          oldMaster.reverbDiffusion !== newMaster.reverbDiffusion
      ) {
          recomputeReverb = true;
      }

      this.activePresets = {
          normal: this.ensurePresetSafety(newPresets.normal),
          latch: this.ensurePresetSafety(newPresets.latch),
          strum: this.ensurePresetSafety(newPresets.strum),
          brass: this.ensurePresetSafety(newPresets.brass),
          arpeggio: this.ensurePresetSafety(newPresets.arpeggio)
      };

      if (recomputeReverb && this.ctx) {
          this.updateReverbBuffer();
      }
      this.updateFX();

      // If worklet isn't ready, these will be queued by postMessage
      modes.forEach(mode => {
          this.postMessage({ 
              type: 'update_preset', 
              mode: mode, 
              data: this.activePresets[mode] 
          });
      });
  }

  // New Method: Register a dynamic preset (like a chord patch) with the audio engine
  public registerPreset(id: string, preset: SynthPreset) {
      this.postMessage({
          type: 'update_preset', 
          mode: id,
          data: this.ensurePresetSafety(preset)
      });
  }

  public async resume() {
      if (!this.ctx) {
          await this.init(); 
      }
      if (this.ctx && (this.ctx.state === 'suspended' || (this.ctx.state as string) === 'interrupted')) {
          try {
            await this.ctx.resume();
          } catch (e) {
            // Harmless warning if called before gesture
            // console.warn("Context resume pending gesture");
          }
      }
  }

  public async init() {
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
        if (!this.ctx) {
            const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
            const settings = store.getSnapshot().settings;
            const latencyHint = settings.audioLatencyHint || 'playback';

            this.ctx = new AudioContextClass({
                latencyHint: latencyHint,
            });

            this.ctx.onstatechange = () => {
                if (this.ctx && (this.ctx.state === 'suspended' || (this.ctx.state as string) === 'interrupted')) {
                    // Try to auto-resume if allowed
                    this.ctx.resume().catch(() => {}); 
                }
            };

            try {
                // Use Blob URL to load worklet code reliably
                const blob = new Blob([AUDIO_PROCESSOR_CODE], { type: 'application/javascript' });
                const url = URL.createObjectURL(blob);

                await this.ctx.audioWorklet.addModule(url);
                URL.revokeObjectURL(url);

                this.workletNode = new AudioWorkletNode(this.ctx, 'synth-processor', {
                    numberOfInputs: 0,
                    numberOfOutputs: 1,
                    outputChannelCount: [2]
                });

                // Set up message handler for voice stealing events
                this.workletNode.port.onmessage = (e) => {
                    if (e.data.type === 'voice_stolen') {
                        this.voiceStealListeners.forEach(cb => cb(e.data.id));
                    }
                };

                // Initialize state from store
                (['normal', 'latch', 'strum', 'brass', 'arpeggio'] as PlayMode[]).forEach(mode => {
                    this.workletNode!.port.postMessage({ 
                        type: 'update_preset', 
                        mode: mode, 
                        data: this.activePresets[mode] 
                    });
                });

                const currentSettings = store.getSnapshot().settings;
                this.workletNode!.port.postMessage({ 
                    type: 'config', 
                    polyphony: currentSettings.polyphony,
                    strumDuration: currentSettings.strumDuration,
                    enableOversampling: currentSettings.enableOversampling,
                    wavetableSize: currentSettings.wavetableSize,
                    interpolationType: currentSettings.interpolationType
                });

                this.setupFX();

                if (this.workletNode && this.dryGain && this.reverbGain && this.delayOutputGain) {
                     this.workletNode.connect(this.dryGain);
                     this.workletNode.connect(this.reverbGain);
                     this.workletNode.connect(this.delayOutputGain);
                }

                // Flush Queue
                if (this.messageQueue.length > 0) {
                    this.messageQueue.forEach(msg => this.workletNode!.port.postMessage(msg));
                    this.messageQueue = [];
                }

                console.log("Audio Engine Initialized (Suspended)");

            } catch (e) {
                console.error("Failed to load AudioWorklet", e);
                this.initPromise = null; 
                return;
            }
        }

        // We do NOT auto-resume here anymore to allow constructor init without gesture
    })();

    return this.initPromise;
  }

  private setupFX() {
    if (!this.ctx) return;

    try {
        this.dryGain?.disconnect();
        this.reverbNode?.disconnect();
        this.reverbGain?.disconnect();
        this.delayNode?.disconnect();
        this.delayFeedbackGain?.disconnect();
        this.delayOutputGain?.disconnect();
        this.limiter?.disconnect();
        this.masterFilter?.disconnect();
        this.finalMasterGain?.disconnect();
    } catch(e) { /* ignore */ }

    // Master Filter (Tone Control)
    this.masterFilter = this.ctx.createBiquadFilter();
    this.masterFilter.type = 'lowpass';
    this.masterFilter.frequency.value = 20000;
    this.masterFilter.Q.value = 0.5;

    this.limiter = this.ctx.createDynamicsCompressor();
    this.limiter.threshold.value = -8.0; 
    this.limiter.ratio.value = 10.0;
    this.limiter.attack.value = 0.005;

    // Final Master Gain (Global Volume)
    this.finalMasterGain = this.ctx.createGain();
    this.finalMasterGain.gain.value = this.currentMasterVol;

    // Filter -> Limiter -> FinalGain -> Destination
    this.masterFilter.connect(this.limiter);
    this.limiter.connect(this.finalMasterGain);
    this.finalMasterGain.connect(this.ctx.destination);

    this.dryGain = this.ctx.createGain();
    this.dryGain.connect(this.masterFilter);

    this.reverbNode = this.ctx.createConvolver();
    this.updateReverbBuffer();

    this.reverbGain = this.ctx.createGain();
    this.reverbGain.connect(this.reverbNode);
    this.reverbNode.connect(this.masterFilter);

    this.delayNode = this.ctx.createDelay(5.0);
    this.delayFeedbackGain = this.ctx.createGain();
    this.delayOutputGain = this.ctx.createGain();

    this.delayOutputGain.connect(this.delayNode);
    this.delayNode.connect(this.masterFilter); 
    this.delayNode.connect(this.delayFeedbackGain);
    this.delayFeedbackGain.connect(this.delayNode);

    // Reconnect Worklet if it exists
    if (this.workletNode) {
        this.workletNode.disconnect();
        this.workletNode.connect(this.dryGain);
        this.workletNode.connect(this.reverbGain);
        this.workletNode.connect(this.delayOutputGain);
    }

    this.updateFX();
  }

  private updateReverbBuffer() {
      if (!this.reverbNode || !this.ctx) return;

      const master = this.activePresets.normal;
      const type = master.reverbType || 'hall';

      const duration = master.reverbSize ?? REVERB_DEFAULTS[type].size;
      const damping = master.reverbDamping ?? REVERB_DEFAULTS[type].damping;
      const diffusion = master.reverbDiffusion ?? REVERB_DEFAULTS[type].diffusion;

      let brightness = 1.0 - damping; 

      let preDelay = 0.0;
      let decay = 2.0;
      let density = 0.5;

      switch(type) {
          case 'room': decay = 3.0; density = 0.8; break;
          case 'hall': decay = 2.0; density = 0.6; preDelay = 0.02; break;
          case 'cathedral': decay = 1.5; density = 0.4; preDelay = 0.04; break;
          case 'plate': decay = 4.0; density = 1.0; break;
          case 'shimmer': decay = 0.8; density = 0.2; break;
          default: decay = 2.0; density = 0.5;
      }

      this.reverbNode.buffer = this.createImpulseResponse(duration, decay, brightness, density, preDelay, diffusion);
  }

  private updateFX() {
      if (!this.ctx) return;
      const now = this.ctx.currentTime;
      const ramp = 0.1;

      const master = this.activePresets.normal;

      const scaledReverbMix = Math.min(1.0, master.reverbMix * this.globalSpatialScale);
      const scaledDelayMix = Math.min(1.0, master.delayMix * this.globalSpatialScale);

      if (this.reverbGain) this.reverbGain.gain.setTargetAtTime(scaledReverbMix, now, ramp);
      if (this.delayOutputGain) this.delayOutputGain.gain.setTargetAtTime(scaledDelayMix, now, ramp);

      const scaledFeedback = Math.min(0.95, master.delayFeedback * Math.sqrt(this.globalSpatialScale));
      if (this.delayFeedbackGain) this.delayFeedbackGain.gain.setTargetAtTime(scaledFeedback, now, ramp);

      if (this.delayNode) this.delayNode.delayTime.setTargetAtTime(master.delayTime, now, ramp);

      if (this.limiter) {
          const thresh = master.compressorThreshold ?? -20.0;
          const ratio = master.compressorRatio ?? 12;
          const release = master.compressorRelease ?? 0.25;

          this.limiter.threshold.setTargetAtTime(thresh, now, ramp);
          this.limiter.ratio.setTargetAtTime(ratio, now, ramp);
          this.limiter.release.setTargetAtTime(release, now, ramp);
      }

      if (this.masterFilter) {
          // Logarithmic mapping for brightness: 0..1 -> 100Hz .. 20000Hz
          const minFreq = 100;
          const maxFreq = 20000;
          const freq = minFreq * Math.pow(maxFreq/minFreq, this.globalBrightness);
          this.masterFilter.frequency.setTargetAtTime(freq, now, ramp);
      }

      if (this.finalMasterGain) {
          this.finalMasterGain.gain.setTargetAtTime(this.currentMasterVol, now, ramp);
      }

      if (this.dryGain) {
          const dryLevel = Math.max(0.5, 1.0 - (scaledReverbMix * 0.4));
          // Normalized dry level logic, volume now handled by finalMasterGain
          this.dryGain.gain.setTargetAtTime(dryLevel, now, ramp);
      }
  }

  private createImpulseResponse(duration: number, baseDecayCurve: number, brightness: number, density: number, preDelay: number, diffusion: number): AudioBuffer {
    if (!this.ctx) throw new Error("No Context");
    const sampleRate = this.ctx.sampleRate;
    const length = Math.floor(sampleRate * duration);
    const impulse = this.ctx.createBuffer(2, length, sampleRate);
    const left = impulse.getChannelData(0);
    const right = impulse.getChannelData(1);

    const startSample = Math.floor(preDelay * sampleRate);
    let lpL = 0, lpR = 0;
    const baseSmoothing = 0.01 + (1.0 - brightness) * 0.985; 
    const decayCurve = baseDecayCurve + (1.0 - brightness) * 4.0;

    for (let i = startSample; i < length; i++) {
        let nL = (Math.random() * 2 - 1);
        let nR = (Math.random() * 2 - 1);
        const progress = (i - startSample) / (length - startSample);
        const currentSmoothing = baseSmoothing * (0.8 + 0.2 * progress);

        lpL += (nL - lpL) * (1.0 - currentSmoothing);
        lpR += (nR - lpR) * (1.0 - currentSmoothing);

        const env = Math.pow(1 - progress, decayCurve);
        const diffMask = (Math.random() < (0.05 + 0.95 * diffusion)) ? 1 : 0;
        const diffGain = diffMask > 0 ? 1.0 / Math.sqrt(0.05 + 0.95 * diffusion) : 0;

        left[i] = lpL * env * diffMask * diffGain;
        right[i] = lpR * env * diffMask * diffGain;
    }

    const erDuration = Math.floor(0.08 * sampleRate);
    const erCount = Math.floor(8 + density * 12); 

    for (let k = 0; k < erCount; k++) {
        const delay = startSample + Math.floor(Math.random() * erDuration);
        if (delay < length) {
            const erAmp = (1.0 - (k / erCount)) * 0.8; 
            const pan = Math.random() * 2 - 1; 
            const gainL = erAmp * (0.5 - 0.5 * pan);
            const gainR = erAmp * (0.5 + 0.5 * pan);
            left[delay] += (Math.random() * 2 - 1) * gainL;
            right[delay] += (Math.random() * 2 - 1) * gainR;
        }
    }

    let maxVal = 0;
    for (let i = 0; i < length; i++) {
        if (Math.abs(left[i]) > maxVal) maxVal = Math.abs(left[i]);
        if (Math.abs(right[i]) > maxVal) maxVal = Math.abs(right[i]);
    }
    const scale = 0.5 / Math.max(0.001, maxVal); 
    for (let i = 0; i < length; i++) {
        left[i] *= scale;
        right[i] *= scale;
    }

    return impulse;
  }

  public setPolyphony(count: number) {
      this.postMessage({ type: 'config', polyphony: count });
  }

  public setStrumDuration(duration: number) {
      this.postMessage({ type: 'config', strumDuration: duration });
  }

  public setMasterVolume(val: number) {
    this.currentMasterVol = val;
    this.updateFX();
  }

  public setGlobalSpatialScale(val: number) {
      this.globalSpatialScale = val;
      this.updateFX();
  }

  public setGlobalBrightness(val: number) {
      this.globalBrightness = val;
      this.updateFX();
  }

  // New method for global pitch bend
  public setGlobalBend(semitones: number) {
      const ratio = Math.pow(2, semitones / 12.0);
      this.postMessage({ type: 'config', globalBend: ratio });
  }

  public getContext(): AudioContext | null {
      return this.ctx;
  }

  // Allow connecting the master output to an external destination (e.g. MediaStreamDestination for recording)
  public connectToRecordingDestination(destination: AudioNode) {
      if (this.finalMasterGain) {
          // Connect in parallel to the recording destination
          this.finalMasterGain.connect(destination);
      }
  }

  // Updated startVoice to accept optional start time for Lookahead Scheduling
  public startVoice(id: string, ratio: number, baseFrequency: number, presetSlot: string = 'normal', playbackMode: PlaybackMode = 'gate', time?: number) {
    // Ensure context is running (resume if suspended)
    this.resume();

    const freq = baseFrequency * ratio;
    this.postMessage({ 
        type: 'note_on', 
        id: id, 
        freq: freq,
        voiceType: presetSlot,
        mode: playbackMode,
        time: time // Pass time if provided
    });
  }

  public stopVoice(id: string, time?: number) {
    this.postMessage({ 
        type: 'note_off', 
        id: id,
        time: time
    });
  }

  public glideVoice(id: string, newRatio: number, baseFrequency: number) {
    const freq = baseFrequency * newRatio;
    this.postMessage({ 
        type: 'glide', 
        id: id, 
        freq: freq 
    });
  }

  public stopAll() {
    this.postMessage({ type: 'stop_all' });
    // Resetting FX is safe to do immediately even if audio isn't running
    if (this.ctx) this.setupFX();
  }

  public stopGroup(prefix: string) {
      this.postMessage({ type: 'stop_group', prefix: prefix });
  }
}

export const audioEngine = new AudioEngine();
export default AudioEngine;

import { ArpeggioStep, ArpConfig } from '../types';
import { audioEngine } from './AudioEngine';
import { midiService } from './MidiService';
import { store } from './Store';

type OnStepCallback = (stepIndex: number) => void;
type OnNoteCallback = (nodeId: string, active: boolean) => void;

class ArpeggiatorService {
    private isRunning: boolean = false;
    private currentStepIndex: number = 0;

    // Lookahead Scheduler State
    private nextNoteTime: number = 0;
    private timerId: number | null = null;

    // The "source" steps from the recording
    private baseSteps: ArpeggioStep[] = [];
    private currentConfig: ArpConfig | null = null;

    // The "effective" steps after processing Direction and Octave Range
    private playbackQueue: { nodeId: string, ratio: number, originalIndex: number, muted?: boolean }[] = [];

    private onStepCallback: OnStepCallback | null = null;
    private onNoteCallback: OnNoteCallback | null = null; 

    // Track active visual nodes to ensure they are cleared on stop
    private activeVisualNodeIds: Set<string> = new Set();

    // Schedule ahead time (seconds)
    private readonly scheduleAheadTime = 0.1; // 100ms
    // Check interval (ms)
    private readonly lookaheadInterval = 25; // 25ms

    public start(steps: ArpeggioStep[], config: ArpConfig, bpm: number, onStep?: OnStepCallback, onNote?: OnNoteCallback) {
        this.stop();
        if (steps.length === 0) return;

        this.baseSteps = steps;
        this.currentConfig = config;
        this.onStepCallback = onStep || null;
        this.onNoteCallback = onNote || null;
        this.isRunning = true;
        this.currentStepIndex = 0;
        this.activeVisualNodeIds.clear();

        const ctx = audioEngine.getContext();
        if (ctx) {
            this.nextNoteTime = ctx.currentTime + 0.05; // Start slightly in future
            this.recalculateQueue();
            this.schedulerLoop();
        } else {
            // Fallback retry if context not ready
            audioEngine.init().then(() => {
                const ctx = audioEngine.getContext();
                if (ctx) {
                    this.nextNoteTime = ctx.currentTime + 0.05;
                    this.recalculateQueue();
                    this.schedulerLoop();
                }
            });
        }
    }

    public stop() {
        this.isRunning = false;
        if (this.timerId) {
            window.clearTimeout(this.timerId);
            this.timerId = null;
        }

        // Stop any currently sounding notes immediately belonging to Arpeggiator
        // Use prefix 'arp-' to target voices generated by this service
        audioEngine.stopGroup('arp-'); 

        // Explicitly clear any active visual feedback
        if (this.onNoteCallback) {
            this.activeVisualNodeIds.forEach(id => {
                this.onNoteCallback!(id, false);
            });
        }
        this.activeVisualNodeIds.clear();

        this.currentStepIndex = 0;
    }

    public updateBpm(newBpm: number) {
        // Scheduler picks up new BPM on next cycle automatically from store (accessed in advanceNoteTime)
    }

    private schedulerLoop() {
        if (!this.isRunning) return;

        const ctx = audioEngine.getContext();
        if (!ctx) return;

        const currentTime = ctx.currentTime;

        // Schedule notes falling within the lookahead window
        while (this.nextNoteTime < currentTime + this.scheduleAheadTime) {
            this.scheduleNote(this.nextNoteTime);
            this.advanceNoteTime();
        }

        this.timerId = window.setTimeout(() => this.schedulerLoop(), this.lookaheadInterval);
    }

    private advanceNoteTime() {
        const state = store.getSnapshot();
        const bpm = state.settings.arpBpm || 120;
        const config = this.currentConfig;
        if (!config) return;

        const beatMs = 60000 / bpm; 
        let div = 0.5; // default 1/8

        switch(config.division) {
            case '1/1': div = 4.0; break;
            case '1/2': div = 2.0; break;
            case '1/4': div = 1.0; break;
            case '1/8': div = 0.5; break;
            case '1/16': div = 0.25; break;
            case '1/32': div = 0.125; break;
            case '1/4T': div = 1.0 * (2/3); break;
            case '1/8T': div = 0.5 * (2/3); break;
            case '1/16T': div = 0.25 * (2/3); break;
        }

        let stepDurationSeconds = (beatMs * div) / 1000;

        // Swing Logic
        if (config.swing > 0) {
            const isEvenStep = (this.currentStepIndex % 2) === 0;
            const swingAmount = (config.swing / 100) * 0.33; 
            if (isEvenStep) stepDurationSeconds *= (1.0 + swingAmount); 
            else stepDurationSeconds *= (1.0 - swingAmount);
        }

        // Humanize Logic
        if (config.humanize && config.humanize > 0) {
            const jitterSeconds = (Math.random() - 0.5) * (config.humanize / 1000);
            stepDurationSeconds += jitterSeconds;
        }

        this.nextNoteTime += Math.max(0.01, stepDurationSeconds);
        this.currentStepIndex++;
    }

    private scheduleNote(time: number) {
        if (!this.playbackQueue.length || !this.currentConfig) return;

        const config = this.currentConfig;
        const patternLength = Math.max(1, config.length || 8);
        const effectiveLoopLength = Math.min(this.playbackQueue.length, patternLength);

        const wrappedIndex = this.currentStepIndex % effectiveLoopLength;
        const step = this.playbackQueue[wrappedIndex];

        const probability = (config.probability !== undefined) ? config.probability : 1.0;
        const shouldPlay = !step.muted && Math.random() < probability;

        if (shouldPlay) {
            const voiceId = `arp-${step.nodeId}-${Date.now()}-${Math.random()}`;
            const state = store.getSnapshot();

            // Calculate Gate Duration
            const beatMs = 60000 / (state.settings.arpBpm || 120);
            // Re-derive division scale for gate calculation
            let divBase = 0.5;
             switch(config.division) {
                case '1/1': divBase = 4.0; break;
                case '1/2': divBase = 2.0; break;
                case '1/4': divBase = 1.0; break;
                case '1/8': divBase = 0.5; break;
                case '1/16': divBase = 0.25; break;
                case '1/32': divBase = 0.125; break;
                case '1/4T': divBase = 1.0 * (2/3); break;
                case '1/8T': divBase = 0.5 * (2/3); break;
                case '1/16T': divBase = 0.25 * (2/3); break;
            }
            const durationSec = (beatMs * divBase / 1000) * Math.min(1.0, Math.max(0.1, config.gate));
            const stopTime = time + durationSec;

            // Trigger Audio with precise time
            audioEngine.startVoice(voiceId, step.ratio, state.settings.baseFrequency, 'arpeggio', 'gate', time);

            // Schedule Stop
            audioEngine.stopVoice(voiceId, stopTime);

            const ctx = audioEngine.getContext();
            const delayMs = Math.max(0, (time - (ctx?.currentTime || 0)) * 1000);

            // Schedule Visuals and MIDI (Best Effort)
            // Visuals are synced to occur roughly when the sound starts
            setTimeout(() => {
                if (!this.isRunning) return;

                // Visual ON
                this.activeVisualNodeIds.add(step.nodeId);
                if (this.onNoteCallback) this.onNoteCallback(step.nodeId, true);

                // MIDI ON
                if (state.settings.midiEnabled) {
                    midiService.noteOn(voiceId, step.ratio, state.settings.baseFrequency, state.settings.midiPitchBendRange);
                }

                // Schedule OFF
                setTimeout(() => {
                    if (!this.isRunning) return;

                    if (this.onNoteCallback) this.onNoteCallback(step.nodeId, false);
                    this.activeVisualNodeIds.delete(step.nodeId);

                    if (state.settings.midiEnabled) midiService.noteOff(voiceId);
                }, durationSec * 1000);

            }, delayMs);
        }

        // Step Callback (Visual Playhead)
        const visualDelay = Math.max(0, (time - (audioEngine.getContext()?.currentTime || 0)) * 1000);
        setTimeout(() => {
            if (this.isRunning && this.onStepCallback) {
                this.onStepCallback(step.originalIndex);
            }
        }, visualDelay);
    }

    private recalculateQueue() {
        if (!this.currentConfig) return;
        const config = this.currentConfig;

        let pool = this.baseSteps.map((s, i) => ({ ...s, originalIndex: i }));
        let final: { nodeId: string, ratio: number, originalIndex: number, muted?: boolean }[] = [];

        // 1. Octave Expansion
        const octaves = Math.max(1, Math.min(4, config.octaves));
        let expandedPool = [];
        for (let oct = 0; oct < octaves; oct++) {
            const mult = Math.pow(2, oct);
            for (const step of pool) {
                expandedPool.push({
                    nodeId: step.nodeId, 
                    ratio: step.ratio * mult,
                    originalIndex: step.originalIndex,
                    sortRatio: step.ratio * mult,
                    muted: step.muted
                });
            }
        }

        // 2. Direction
        switch (config.direction) {
            case 'up':
                expandedPool.sort((a, b) => a.sortRatio - b.sortRatio);
                final = expandedPool;
                break;
            case 'down':
                expandedPool.sort((a, b) => b.sortRatio - a.sortRatio);
                final = expandedPool;
                break;
            case 'updown':
                {
                    const up = [...expandedPool].sort((a, b) => a.sortRatio - b.sortRatio);
                    const down = [...expandedPool].sort((a, b) => b.sortRatio - a.sortRatio);
                    final = [...up, ...down];
                }
                break;
            case 'random':
                // Shuffle
                for (let i = expandedPool.length - 1; i > 0; i--) {
                    const j = Math.floor(Math.random() * (i + 1));
                    [expandedPool[i], expandedPool[j]] = [expandedPool[j], expandedPool[i]];
                }
                final = expandedPool;
                break;
            case 'order':
            default:
                final = expandedPool; 
                break;
        }

        this.playbackQueue = final;
    }
}

export const arpeggiatorService = new ArpeggiatorService();

import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import RecordingControls from './components/RecordingControls';
import { audioEngine } from './services/AudioEngine';
import { midiService } from './services/MidiService';
import { useStore } from './services/Store';
import { AppSettings, XYPos, UISize, SynthPreset } from './types';
import { PIXELS_PER_MM, SCROLLBAR_WIDTH } from './constants';
import { arpeggiatorService } from './services/ArpeggiatorService';
import { useAppLayout } from './hooks/useAppLayout';
import { useArpeggiatorLogic } from './hooks/useArpeggiatorLogic';

const App: React.FC = () => {
  const { settings, presets, updateSettings, setPreset } = useStore();

  const [masterVolume, setMasterVolume] = useState(0.8);
  const [spatialScale, setSpatialScale] = useState(1.0); 
  const [brightness, setBrightness] = useState(1.0); // Tone control
  const [viewZoom, setViewZoom] = useState(1.0);

  const [activeChordIds, setActiveChordIds] = useState<string[]>([]);
  const [draggingId, setDraggingId] = useState<string | null>(null);

  // Latch Modes: 0=Off, 1=Drone, 2=Strings, 3=Plucked, 4=Voice (Brass)
  const [latchMode, setLatchMode] = useState<0 | 1 | 2 | 3 | 4>(2);

  // Track sustain ON/OFF preference per instrument mode
  const [sustainStates, setSustainStates] = useState<{ [key: number]: boolean }>({ 1: true, 2: true, 3: false, 4: false });

  // Track which modes currently have active voices sustained
  const [activeSustainedModes, setActiveSustainedModes] = useState<number[]>([]);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);
  const [isSequencerOpen, setIsSequencerOpen] = useState(false);

  const diamondRef = useRef<TonalityDiamondHandle>(null);

  // Use custom hooks
  const { autoScaleFactor, isShortScreen } = useAppLayout(settings, updateSettings);
  const effectiveScale = autoScaleFactor * (settings.uiScale || 1.0);

  const {
      recordingArpId,
      setRecordingArpId,
      currentArpStep,
      recordingFlash,
      handleArpToggle,
      handleArpRecordNote,
      handleArpPatternUpdate,
      handleArpBpmChange,
      handleArpRowConfigChange,
      handlePlayAll,
      handleStopAll,
      stopArpAndRecording
  } = useArpeggiatorLogic(settings, updateSettings, diamondRef);

  // --- AUDIO ENGINE SYNC ---
  useEffect(() => {
      audioEngine.updatePresets(presets);
  }, [presets]);

  useEffect(() => {
      audioEngine.updateSettings(settings);
  }, [settings]);

  // --- MIDI INPUT SYNC (SUSTAIN & BEND) ---
  useEffect(() => {
      // Subscribe to external MIDI sustain events
      const unsubscribeSustain = midiService.onSustain((isActive) => {
          setSustainStates(prev => ({ ...prev, [latchMode]: isActive }));
          updateSettings(prev => ({ ...prev, isSustainEnabled: isActive }));
      });

      // Subscribe to external MIDI Pitch Bend (Global)
      const unsubscribeBend = midiService.onGlobalBend((semitones) => {
          audioEngine.setGlobalBend(semitones);
      });

      return () => {
          unsubscribeSustain();
          unsubscribeBend();
      };
  }, [latchMode, updateSettings]);

  useEffect(() => {
    const warmup = (e: Event) => {
        audioEngine.resume().then(() => {});
        if (settings.midiEnabled) midiService.init(); 

        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };

    window.addEventListener('pointerdown', warmup);
    window.addEventListener('keydown', warmup);
    window.addEventListener('touchstart', warmup);
    window.addEventListener('touchend', warmup);
    window.addEventListener('click', warmup);

    return () => {
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };
  }, [settings.midiEnabled]);

  useEffect(() => {
      document.documentElement.style.setProperty('--ui-scale', effectiveScale.toString());
  }, [effectiveScale]);

  useEffect(() => {
    audioEngine.setMasterVolume(masterVolume);
  }, [masterVolume]);

  useEffect(() => {
    audioEngine.setGlobalSpatialScale(spatialScale);
  }, [spatialScale]);

  useEffect(() => {
    audioEngine.setGlobalBrightness(brightness);
  }, [brightness]);

  const handleLimitInteraction = (limit: number) => {
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      updateSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = () => {
    audioEngine.stopAll(); 
    stopArpAndRecording();
    midiService.panic();
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]); 
    setIsSettingsOpen(false);
    setIsSynthOpen(false);
  };

  const handleOff = () => {
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]);
    stopArpAndRecording(); // Ensures arpeggiator stops immediately
  };

  const switchInstrument = (newMode: 0 | 1 | 2 | 3 | 4) => {
      setSustainStates(prev => ({ ...prev, [latchMode]: settings.isSustainEnabled }));
      setLatchMode(newMode);
      let nextSustainState = sustainStates[newMode] ?? false;
      updateSettings(prev => ({ ...prev, isSustainEnabled: nextSustainState }));
  };

  const handleDroneSelect = () => switchInstrument(1);
  const handleStringSelect = () => switchInstrument(2);
  const handlePluckedSelect = () => switchInstrument(3);
  const handleVoiceSelect = () => switchInstrument(4);

  const handleSustainToggle = () => {
      const willEnable = !settings.isSustainEnabled;
      setSustainStates(prev => ({ ...prev, [latchMode]: willEnable }));
      updateSettings(prev => ({ ...prev, isSustainEnabled: willEnable }));
      if (settings.midiEnabled) {
          midiService.sendSustain(willEnable);
      }
  };

  const handleBendToggle = () => {
      updateSettings(prev => ({ ...prev, isPitchBendEnabled: !prev.isPitchBendEnabled }));
  };

  const handleSustainStatusChange = (modes: number[]) => {
      setActiveSustainedModes(modes);
  };

  const handleClearSustain = (mode: number) => {
      diamondRef.current?.clearLatches(mode);
  };

  const handleCenter = () => diamondRef.current?.centerView();
  const handleIncreaseDepth = () => diamondRef.current?.increaseDepth();
  const handleDecreaseDepth = () => diamondRef.current?.decreaseDepth();

  const handleAddChord = () => {
      if (diamondRef.current) {
          const latchedData = diamondRef.current.getLatchedNodes();
          if (latchedData.length === 0) return;

          let slotIndex = settings.savedChords.findIndex(c => c.nodes.length === 0);
          if (slotIndex === -1) slotIndex = settings.savedChords.findIndex(c => !c.visible);

          if (slotIndex !== -1) {
              const newChords = [...settings.savedChords];
              const uniqueTimestamp = Date.now();
              const soundConfigs: Partial<Record<import('./types').PlayMode, SynthPreset>> = {};
              const usedModes = new Set<import('./types').PlayMode>();

              const simplifiedNodes = latchedData.map(({ node, mode }) => {
                  let modeStr: import('./types').PlayMode = 'normal';
                  if (mode === 1) modeStr = 'latch';
                  else if (mode === 2) modeStr = 'normal';
                  else if (mode === 3) modeStr = 'strum';
                  else if (mode === 4) modeStr = 'brass'; 
                  usedModes.add(modeStr);

                  return { id: node.id, n: node.n, d: node.d, voiceMode: modeStr };
              });

              usedModes.forEach(m => {
                  soundConfigs[m] = JSON.parse(JSON.stringify(presets[m]));
                  if (soundConfigs[m]) {
                      soundConfigs[m]!.id = `chord-${newChords[slotIndex].id}-${m}-${uniqueTimestamp}`;
                  }
              });

              newChords[slotIndex] = {
                  ...newChords[slotIndex],
                  nodes: simplifiedNodes,
                  visible: true,
                  position: { x: 0, y: 0 },
                  soundConfigs: soundConfigs,
                  soundConfig: undefined 
              };
              updateSettings(prev => ({ ...prev, savedChords: newChords }));
          }
      }
  };

  const toggleChord = (id: string) => {
      if (settings.isSustainEnabled) {
          setActiveChordIds(prev => prev.includes(id) ? prev.filter(c => c !== id) : [...prev, id]);
      } else {
          setActiveChordIds(prev => prev.includes(id) ? [] : [id]);
      }
  };

  const handleRemoveChord = (id: string) => {
      const newChords = settings.savedChords.map(c => {
          if (c.id === id) {
              return { ...c, nodes: [], visible: false, soundConfig: undefined, soundConfigs: undefined };
          }
          return c;
      });
      updateSettings(prev => ({ ...prev, savedChords: newChords }));

      if (activeChordIds.includes(id)) {
          setActiveChordIds(prev => prev.filter(cid => cid !== id));
      }
  };

  const handleUiPositionUpdate = (key: keyof AppSettings['uiPositions'], pos: XYPos) => {
      updateSettings(prev => ({ ...prev, uiPositions: { ...prev.uiPositions, [key]: pos } }));
  };

  const handleUiSizeUpdate = (key: keyof AppSettings['uiSizes'], size: UISize) => {
      updateSettings(prev => ({ ...prev, uiSizes: { ...prev.uiSizes, [key]: size } }));
  };

  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          if (e.key === 'Escape' && (isSettingsOpen || isSynthOpen)) {
              setIsSettingsOpen(false); setIsSynthOpen(false); return;
          }
          const target = e.target as HTMLElement;
          if (target.tagName === 'INPUT' || target.tagName === 'SELECT' || target.tagName === 'TEXTAREA') return;
          if (!settings.enableKeyboardShortcuts) return;

          const key = e.key.toLowerCase();
          const map = settings.keyMappings;

          if ([map.latch, map.volumeUp, map.volumeDown, map.spatialScaleUp, map.spatialScaleDown].map(k => k.toLowerCase()).includes(key)) e.preventDefault();

          if (key === map.latch.toLowerCase()) { if (latchMode === 1) handleStringSelect(); else handleDroneSelect(); }
          else if (key === map.modeDrone.toLowerCase()) handleDroneSelect();
          else if (key === map.modeStrings.toLowerCase()) handleStringSelect();
          else if (key === map.modePlucked.toLowerCase()) handlePluckedSelect();
          else if (key === map.modeBrass.toLowerCase()) handleVoiceSelect(); 
          else if (key === map.sustain.toLowerCase()) handleSustainToggle();
          else if (key === map.bend.toLowerCase()) handleBendToggle();
          else if (key === map.panic.toLowerCase()) handlePanic();
          else if (key === map.center.toLowerCase()) handleCenter();
          else if (key === map.settings.toLowerCase()) { setIsSettingsOpen(prev => !prev); if(isSynthOpen) setIsSettingsOpen(false); }
          else if (key === map.synth.toLowerCase()) { setIsSynthOpen(prev => !prev); if(isSettingsOpen) setIsSettingsOpen(false); }
          else if (key === map.off.toLowerCase()) handleOff();
          else if (key === map.addChord.toLowerCase()) handleAddChord();
          else if (key === map.increaseDepth.toLowerCase()) handleIncreaseDepth();
          else if (key === map.decreaseDepth.toLowerCase()) handleDecreaseDepth();
          else if (key === map.volumeUp.toLowerCase()) setMasterVolume(v => Math.min(1.0, v + 0.05));
          else if (key === map.volumeDown.toLowerCase()) setMasterVolume(v => Math.max(0.0, v - 0.05));
          else if (key === map.spatialScaleUp.toLowerCase()) setSpatialScale(s => Math.min(2.0, s + 0.05));
          else if (key === map.spatialScaleDown.toLowerCase()) setSpatialScale(s => Math.max(0.0, s - 0.05));
          else if (key === map.bpmUp.toLowerCase()) handleArpBpmChange(settings.arpBpm + 1);
          else if (key === map.bpmDown.toLowerCase()) handleArpBpmChange(settings.arpBpm - 1);
          else if (key === map.toggleSequencer.toLowerCase()) setIsSequencerOpen(prev => !prev);
          else if (key === map.playAllArps.toLowerCase()) handlePlayAll();
          else if (key === map.stopAllArps.toLowerCase()) handleStopAll();
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isSettingsOpen, isSynthOpen, settings.enableKeyboardShortcuts, settings.keyMappings, latchMode, settings.arpBpm, handleArpBpmChange, handlePlayAll, handleStopAll, stopArpAndRecording]);

  const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;
  const getSafeAreas = () => {
      if (typeof document === 'undefined') return { top: 0, right: 0, bottom: 0, left: 0 };
      const div = document.createElement('div');
      div.style.paddingTop = 'env(safe-area-inset-top)';
      div.style.visibility = 'hidden';
      document.body.appendChild(div);
      const computed = getComputedStyle(div);
      const top = parseInt(computed.paddingTop) || 0;
      document.body.removeChild(div);
      return { top, left: 0, right: 0, bottom: 0 };
  };
  const safeArea = getSafeAreas();
  const leftOffset = `calc(${marginPx}px + ${safeArea.left}px)`;
  const rightOffset = `calc(${marginPx}px + ${safeArea.right}px + ${SCROLLBAR_WIDTH}px)`;
  const headerTop = `calc(${marginPx}px + ${safeArea.top}px)`;

  const headerBtnClass = "bg-slate-900/50 hover:bg-slate-800 px-3 py-1 rounded-xl backdrop-blur-sm transition border border-slate-700/50 h-8 flex items-center text-[10px] font-bold text-slate-400 uppercase tracking-widest hover:text-white shadow-lg";

  const arpX = settings.uiPositions.arpeggioBar.x;
  const volX = settings.uiPositions.volume.x;
  const gap = 20 * effectiveScale;
  const availableArpWidth = Math.max(0, volX - arpX - gap);
  const showArpBar = availableArpWidth > 250 * effectiveScale;

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">
      <div className="absolute z-50 pointer-events-none" style={{ top: headerTop, left: leftOffset }}>
        <h1 className="text-sm font-bold tracking-widest text-slate-500 opacity-20 leading-none">PRISMATONAL</h1>
      </div>

      <div className="absolute z-50 flex gap-2 pointer-events-auto" style={{ top: headerTop, right: rightOffset }}>
          <button onClick={() => setIsSettingsOpen(true)} className={headerBtnClass}>Settings</button>
          <button onClick={() => setIsSynthOpen(true)} className={headerBtnClass}>Synth</button>
      </div>

      <TonalityDiamond 
        ref={diamondRef}
        settings={settings}
        updateSettings={updateSettings}
        audioEngine={audioEngine} 
        onLimitInteraction={handleLimitInteraction}
        activeChordIds={activeChordIds}
        uiUnlocked={settings.uiUnlocked}
        latchMode={latchMode}
        isCurrentSustainEnabled={settings.isSustainEnabled} 
        globalScale={effectiveScale}
        viewZoom={viewZoom}
        onNodeTrigger={handleArpRecordNote}
        onSustainStatusChange={handleSustainStatusChange}
      />

      <FloatingControls 
        volume={masterVolume} setVolume={setMasterVolume}
        spatialScale={spatialScale} setSpatialScale={setSpatialScale}
        brightness={brightness} setBrightness={setBrightness}
        viewZoom={viewZoom} setViewZoom={setViewZoom}

        onPanic={handlePanic} onOff={handleOff}
        onLatch={handleDroneSelect} 
        onSust={handleStringSelect} 
        onPluck={handlePluckedSelect}
        onVoice={handleVoiceSelect}
        latchMode={latchMode}
        onBend={handleBendToggle} isBendEnabled={settings.isPitchBendEnabled}
        onSustainToggle={handleSustainToggle} isSustainEnabled={settings.isSustainEnabled}
        onCenter={handleCenter}
        onIncreaseDepth={handleIncreaseDepth} onDecreaseDepth={handleDecreaseDepth}
        onAddChord={handleAddChord} toggleChord={toggleChord}
        onRemoveChord={handleRemoveChord}
        activeChordIds={activeChordIds} savedChords={settings.savedChords}
        chordShortcutSizeScale={settings.chordShortcutSizeScale}
        showIncreaseDepthButton={settings.showIncreaseDepthButton}
        uiUnlocked={settings.uiUnlocked}
        uiPositions={settings.uiPositions} updatePosition={handleUiPositionUpdate}
        uiSizes={settings.uiSizes} updateSize={handleUiSizeUpdate}
        draggingId={draggingId} setDraggingId={setDraggingId}
        uiScale={effectiveScale}

        arpeggios={settings.arpeggios}
        arpBpm={settings.arpBpm}
        onArpToggle={handleArpToggle}
        onArpBpmChange={handleArpBpmChange}
        onArpRowConfigChange={handleArpRowConfigChange}
        onArpPatternUpdate={handleArpPatternUpdate}
        recordingArpId={recordingArpId}
        currentArpStep={currentArpStep}
        recordingFlash={recordingFlash}
        onPlayAll={handlePlayAll}
        onStopAll={handleStopAll}

        activeSustainedModes={activeSustainedModes}
        maxArpWidth={showArpBar ? availableArpWidth : 0}
        onClearSustain={handleClearSustain}

        isShortScreen={isShortScreen}
        isSequencerOpen={isSequencerOpen}
        onToggleSequencer={() => setIsSequencerOpen(p => !p)}

        presets={presets}
        onPresetChange={setPreset}
      />

      <LimitLayerControls 
        settings={settings} 
        updateSettings={updateSettings} 
        draggingId={draggingId} 
        setDraggingId={setDraggingId} 
        uiScale={effectiveScale}
        isShortScreen={isShortScreen}
      />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} updateSettings={updateSettings} />
      <SynthControls isOpen={isSynthOpen} onClose={() => setIsSynthOpen(false)} presets={presets} onChange={setPreset} />

      <RecordingControls />
    </div>
  );
};

export default App;

