    this.mixBufferL.fill(0); this.mixBufferR.fill(0);

    const masterPreset = this.presets.normal; const panSpeed = (masterPreset.stereoPanSpeed !== undefined) ? masterPreset.stereoPanSpeed : 0.0; const panDepth = (masterPreset.stereoPanDepth !== undefined) ? masterPreset.stereoPanDepth : 0.0; const initialPanPhase = this.panPhase;
    let voicesProcessed = 0;
    for (let i = 0; i < this.voices.length; i++) {
        const v = this.voices[i];
        if (v.active) {
            if (v.mode === 'trigger' && v.releaseTime === 0) { if (currentTime - v.startTime >= this.strumDuration) v.release(); }
            const presetToUse = this.presets[v.type] || this.presets.normal;
            v.renderBlock(presetToUse, dt, this.mixBufferL, this.mixBufferR, workingLen, panSpeed, panDepth, initialPanPhase, this.globalBendMultiplier);
            voicesProcessed++;
            if (startTime > 0 && voicesProcessed % 2 === 0) { if (globalThis.performance.now() - startTime > MAX_BUDGET_MS) { break; } }
        }
    }
    this.panPhase += (workingLen * dt * panSpeed); while (this.panPhase > 1.0) this.panPhase -= 1.0;

    if (OVERSAMPLE === 2) {
        for (let s = 0; s < len; s++) {
            const osIdx = s * 2;
            let sl1 = Math.tanh(this.mixBufferL[osIdx] * 0.8); let sr1 = Math.tanh(this.mixBufferR[osIdx] * 0.8);
            let sl2 = Math.tanh(this.mixBufferL[osIdx+1] * 0.8); let sr2 = Math.tanh(this.mixBufferR[osIdx+1] * 0.8);
            const outL = (sl1 + sl2) * 0.5; const outR = (sr1 + sr2) * 0.5;
            const yL = outL - this.xm1L + 0.995 * this.ym1L; this.xm1L = outL; this.ym1L = yL;
            const yR = outR - this.xm1R + 0.995 * this.ym1R; this.xm1R = outR; this.ym1R = yR;
            channelL[s] = yL; if (channelR) channelR[s] = yR;
        }
    } else {
        for (let s = 0; s < len; s++) {
            const sl = Math.tanh(this.mixBufferL[s] * 0.8); const sr = Math.tanh(this.mixBufferR[s] * 0.8);
            const yL = sl - this.xm1L + 0.995 * this.ym1L; this.xm1L = sl; this.ym1L = yL;
            const yR = sr - this.xm1R + 0.995 * this.ym1R; this.xm1R = sr; this.ym1R = yR;
            channelL[s] = yL; if (channelR) channelR[s] = yR;
        }
    }
    return true;
  }
}
registerProcessor('synth-processor', PrismaProcessor);
`;

export const AUDIO_PROCESSOR_CODE = DSP_CONSTANTS + DSP_CLASSES + VOICE_LOGIC + PROCESSOR_LOGIC;

import React from 'react';
import VolumeWheel from '../VolumeWheel';
import { PresetState, PlayMode, SynthPreset } from '../../types';
import { MODE_COLORS } from '../../constants';

interface Props {
    latchMode: 0 | 1 | 2 | 3 | 4 | 5;
    onLatch: () => void;
    onSust?: () => void;
    onPluck?: () => void;
    onVoice?: () => void;
    onKeys?: () => void;
    activeSustainedModes: number[];
    onClearSustain?: (mode: number) => void;

    // Patch / Gain handling
    presets?: PresetState;
    onPresetChange?: (mode: PlayMode, preset: SynthPreset) => void;

    // UI
    uiScale: number;
    position: { x: number, y: number };
    onDragStart: (e: React.PointerEvent) => void;
    uiUnlocked: boolean;
}

const InstrumentCluster: React.FC<Props> = ({
    latchMode, onLatch, onSust, onPluck, onVoice, onKeys, activeSustainedModes, onClearSustain,
    presets, onPresetChange, uiScale, position, onDragStart, uiUnlocked
}) => {

    // Resize to ~75% of original (104 -> 78)
    const instrButtonSize = 78 * uiScale; 
    const wheelWidth = instrButtonSize * 0.45;

    const updatePatchGain = (mode: PlayMode, val: number) => {
        if (presets && onPresetChange) {
            const preset = presets[mode];
            onPresetChange(mode, { ...preset, gain: val });
        }
    };

    const handleButtonPress = (e: React.PointerEvent, action?: () => void) => {
        e.stopPropagation();
        if (uiUnlocked) {
            onDragStart(e);
        } else {
            if (e.button === 0 && action) action();
        }
    };

    const renderInstrument = (
        modeId: number,
        label: string,
        presetKey: PlayMode,
        onSelect: (() => void) | undefined,
        color: string
    ) => {
        const isSelected = latchMode === modeId;
        const isActive = activeSustainedModes.includes(modeId);
        // Show aura if active but not selected (so you know it's playing in background)
        // OR if selected and active (reinforcement)
        const showAura = isActive && !isSelected; 

        // Define styles based on color
        const baseStyle = {
            width: instrButtonSize,
            height: instrButtonSize,
            fontSize: 12 * uiScale, // Scaled down font size
            borderColor: isSelected ? color : 'rgba(148, 163, 184, 0.2)', // slate-400/20
            backgroundColor: isSelected ? `${color}20` : 'rgba(30, 41, 59, 0.6)', // slate-800/60
            color: isSelected ? 'white' : 'rgba(148, 163, 184, 0.8)',
            textShadow: isSelected ? `0 0 10px ${color}` : 'none',
            boxShadow: isSelected ? `0 0 15px ${color}40` : 'none'
        };

        return (
            <div className="flex items-center gap-2 relative group">
                <VolumeWheel 
                    value={presets?.[presetKey].gain || 0.5} 
                    onChange={(v) => updatePatchGain(presetKey, v)} 
                    color={color} 
                    width={wheelWidth} 
                    height={instrButtonSize} 
                    uiScale={uiScale}
                />

                <div className="relative">
                    <button 
                        className={`rounded-xl border-2 transition-all duration-200 transform active:scale-95 flex flex-col items-center justify-center font-bold uppercase tracking-wider backdrop-blur-md overflow-hidden relative ${showAura ? 'animate-pulse' : ''}`}
                        style={baseStyle}
                        onPointerDown={(e) => !uiUnlocked && handleButtonPress(e, onSelect)}
                        onContextMenu={(e) => { e.preventDefault(); if(!uiUnlocked && onClearSustain) onClearSustain(modeId); }}
                    >
                        {/* Internal Glow for Active state */}
                        {isActive && (
                            <div className="absolute inset-0 opacity-20 pointer-events-none" style={{ backgroundColor: color, filter: 'blur(10px)' }} />
                        )}
                        <span className="z-10">{label}</span>
                        {isActive && (
                            <div className="w-1.5 h-1.5 rounded-full mt-1 z-10" style={{ backgroundColor: color, boxShadow: `0 0 5px ${color}` }} />
                        )}
                    </button>

                    {/* Quick Clear Button (Visible if Active) */}
                    {isActive && !uiUnlocked && (
                        <button
                            className="absolute -top-2 -right-2 w-5 h-5 rounded-full bg-slate-900 border border-slate-600 text-slate-400 hover:text-white hover:bg-red-900 hover:border-red-500 flex items-center justify-center shadow-lg transition-colors z-20"
                            onPointerDown={(e) => { e.stopPropagation(); if(onClearSustain) onClearSustain(modeId); }}
                            title="Clear Sustained Notes"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" className="w-2.5 h-2.5" viewBox="0 0 20 20" fill="currentColor">
                                <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
                            </svg>
                        </button>
                    )}
                </div>
            </div>
        );
    };

    return (
        <div 
            className={`absolute flex flex-col gap-3 z-[140] bg-slate-950/80 p-2.5 rounded-2xl backdrop-blur-md border border-slate-700/50 shadow-2xl cursor-move transition-shadow ${uiUnlocked ? 'ring-2 ring-yellow-500/50' : 'hover:shadow-[0_0_20px_rgba(0,0,0,0.5)]'}`}
            style={{ 
                left: position.x, 
                top: position.y,
                touchAction: 'none'
            }}
            onPointerDown={onDragStart}
        >
            <div className="absolute inset-0 bg-gradient-to-b from-white/5 to-transparent rounded-2xl pointer-events-none" />

            {/* Header / Handle */}
            <div className="flex justify-center pb-1 border-b border-white/5 mb-1 opacity-50">
                <div className="w-8 h-1 bg-slate-600 rounded-full" />
            </div>

            {/* Strings (Blue) - Top */}
            {renderInstrument(2, "Strings", 'normal', onSust, MODE_COLORS[2])}

            {/* Brass (Yellow) */}
            {renderInstrument(4, "Brass", 'brass', onVoice, MODE_COLORS[4])}

            {/* Keys (Purple) - New */}
            {renderInstrument(5, "Keys", 'keys', onKeys, MODE_COLORS[5])}

            {/* Plucked (Orange) */}
            {renderInstrument(3, "Plucked", 'strum', onPluck, MODE_COLORS[3])}

            {/* Drone (Green) - Bottom */}
            {renderInstrument(1, "Drone", 'latch', onLatch, MODE_COLORS[1])}
        </div>
    );
};

export default InstrumentCluster;

import React, { useState, useEffect } from 'react';
import { ChordDefinition, XYPos, AppSettings, ArpeggioDefinition, ArpConfig, ArpeggioStep, PresetState, PlayMode, SynthPreset, UISize } from '../types';
import ArpeggiatorBar from './controls/ArpeggiatorBar';
import InstrumentCluster from './controls/InstrumentCluster';
import MasterControls from './controls/MasterControls';
import PerformanceControls from './controls/PerformanceControls';
import ViewControls from './controls/ViewControls';
import ChordBar from './controls/ChordBar';
import { useDragManager } from '../hooks/useDragManager';

interface Props {
  volume: number;
  setVolume: (v: number) => void;
  spatialScale: number;
  setSpatialScale: (v: number) => void;
  brightness: number;
  setBrightness: (v: number) => void;
  viewZoom: number;
  setViewZoom: (v: number) => void;

  onPanic: () => void;
  onOff: () => void;
  onLatch: () => void; 
  onSust?: () => void; 
  onPluck?: () => void; 
  onVoice?: () => void; 
  onKeys?: () => void; // New prop
  latchMode: 0 | 1 | 2 | 3 | 4 | 5; // Updated type
  onBend: () => void;
  isBendEnabled: boolean;
  onSustainToggle?: () => void;
  isSustainEnabled?: boolean;
  onCenter: () => void;
  onIncreaseDepth: () => void;
  onDecreaseDepth: () => void;
  onAddChord: () => void;
  toggleChord: (id: string) => void;
  onRemoveChord?: (id: string) => void;
  activeChordIds: string[];
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number;
  showIncreaseDepthButton: boolean;
  uiUnlocked: boolean;
  uiPositions: AppSettings['uiPositions'];
  updatePosition: (key: keyof AppSettings['uiPositions'], pos: XYPos) => void;
  uiSizes?: AppSettings['uiSizes'];
  updateSize?: (key: keyof AppSettings['uiSizes'], size: UISize) => void;
  draggingId: string | null;
  setDraggingId: (id: string | null) => void;
  uiScale?: number;

  arpeggios?: ArpeggioDefinition[];
  arpBpm?: number;
  onArpToggle?: (id: string) => void;
  onArpBpmChange?: (bpm: number) => void;
  onArpRowConfigChange?: (arpId: string, config: Partial<ArpConfig>) => void;
  onArpPatternUpdate?: (arpId: string, steps: ArpeggioStep[]) => void;
  recordingArpId?: string | null; 
  currentArpStep?: number;
  recordingFlash?: number;
  onPlayAll?: () => void;
  onStopAll?: () => void;

  maxArpWidth?: number; 
  activeSustainedModes?: number[];
  onClearSustain?: (mode: number) => void;

  isSequencerOpen: boolean;
  onToggleSequencer: () => void;

  presets?: PresetState;
  onPresetChange?: (mode: PlayMode, preset: SynthPreset) => void;
}

const FloatingControls: React.FC<Props> = ({ 
  volume, setVolume, spatialScale, setSpatialScale, brightness, setBrightness, viewZoom, setViewZoom,
  onPanic, onOff, onLatch, onSust, onPluck, onVoice, onKeys, latchMode, onBend, isBendEnabled, onSustainToggle, isSustainEnabled, onCenter, onIncreaseDepth, onDecreaseDepth, onAddChord, toggleChord, onRemoveChord,
  activeChordIds, savedChords, chordShortcutSizeScale,
  showIncreaseDepthButton, uiUnlocked, uiPositions, updatePosition,
  uiSizes, updateSize,
  draggingId, setDraggingId, uiScale = 1.0,
  arpeggios = [], arpBpm = 120, onArpToggle, onArpBpmChange, onArpRowConfigChange, onArpPatternUpdate, recordingArpId, currentArpStep, recordingFlash = 0,
  onPlayAll, onStopAll,
  maxArpWidth,
  activeSustainedModes = [],
  onClearSustain,
  isSequencerOpen,
  onToggleSequencer,
  presets,
  onPresetChange
}) => {

  const [isFlashingRed, setIsFlashingRed] = useState(false);

  useEffect(() => {
      if (recordingFlash > 0) {
          setIsFlashingRed(true);
          const t = setTimeout(() => setIsFlashingRed(false), 200);
          return () => clearTimeout(t);
      }
  }, [recordingFlash]);

  const handleDrag = useDragManager(
      uiUnlocked,
      draggingId,
      setDraggingId,
      (id, pos) => updatePosition(id as any, pos),
      uiPositions as any
  );

  const handleResize = (e: React.PointerEvent, key: 'volume' | 'arpeggioBar', axis: 'x' | 'y' | 'xy') => {
      e.stopPropagation();
      e.preventDefault();
      if (!updateSize || !uiSizes) return;

      const el = e.currentTarget as HTMLElement;
      el.setPointerCapture(e.pointerId);

      const startX = e.clientX;
      const startY = e.clientY;

      const initialWidth = uiSizes[key]?.width || (key === 'volume' ? 600 : 760);
      const initialHeight = uiSizes[key]?.height || (key === 'volume' ? 75 : 0); 

      const onMove = (evt: PointerEvent) => {
          const deltaX = (evt.clientX - startX) / uiScale;
          const deltaY = (evt.clientY - startY) / uiScale;

          let newWidth = initialWidth;
          let newHeight = initialHeight;

          if (axis === 'x' || axis === 'xy') {
              const minW = key === 'volume' ? 320 : 300; 
              newWidth = Math.max(minW, initialWidth + deltaX);
          }
          if ((axis === 'y' || axis === 'xy') && key === 'volume') {
              const minH = 60; 
              newHeight = Math.max(minH, initialHeight + deltaY);
          }

          updateSize(key, { width: newWidth, height: newHeight });
      };

      const onUp = () => {
          window.removeEventListener('pointermove', onMove);
          window.removeEventListener('pointerup', onUp);
          window.removeEventListener('pointercancel', onUp);
      };

      window.addEventListener('pointermove', onMove);
      window.addEventListener('pointerup', onUp);
      window.addEventListener('pointercancel', onUp);
  };

  const arpBaseWidth = uiSizes?.arpeggioBar?.width || 760;
  const userArpWidth = arpBaseWidth * uiScale;
  const effectiveArpWidth = maxArpWidth ? Math.min(userArpWidth, maxArpWidth) : userArpWidth;
  const isConstrained = effectiveArpWidth < (760 * uiScale) * 0.95;

  const resizeHandleStyle = "absolute z-50 bg-yellow-500/50 hover:bg-yellow-400 rounded-sm border border-white/50 shadow-sm transition-colors";

  return (
    <>
      <MasterControls 
          volume={volume} setVolume={setVolume}
          spatialScale={spatialScale} setSpatialScale={setSpatialScale}
          brightness={brightness} setBrightness={setBrightness}
          viewZoom={viewZoom} setViewZoom={setViewZoom}
          uiScale={uiScale}
          uiUnlocked={uiUnlocked}
          position={uiPositions.volume}
          size={uiSizes?.volume || { width: 600, height: 75 }}
          onDragStart={(e) => handleDrag(e, 'volume')}
          onResize={(e, axis) => handleResize(e, 'volume', axis)}
      />

      {/* Independent Resize Handle for Arp Bar */}
      <div style={{ position: 'absolute', left: 0, top: 0, width: 0, height: 0 }}>
          {uiUnlocked && (
              <div 
                  className={`${resizeHandleStyle} cursor-ew-resize`}
                  style={{ 
                      left: uiPositions.arpeggioBar.x + effectiveArpWidth - 6, 
                      top: uiPositions.arpeggioBar.y, 
                      height: 52 * uiScale, 
                      width: 12,
                      zIndex: 160 
                  }}
                  onPointerDown={(e) => handleResize(e, 'arpeggioBar', 'x')}
              />
          )}
      </div>

      <ArpeggiatorBar 
          arpeggios={arpeggios}
          arpBpm={arpBpm}
          onArpToggle={onArpToggle}
          onArpBpmChange={onArpBpmChange}
          onArpRowConfigChange={onArpRowConfigChange}
          onArpPatternUpdate={onArpPatternUpdate}
          recordingArpId={recordingArpId}
          currentArpStep={currentArpStep}
          onPlayAll={onPlayAll}
          onStopAll={onStopAll}
          isSequencerOpen={isSequencerOpen}
          onToggleSequencer={onToggleSequencer}
          uiScale={uiScale}
          position={uiPositions.arpeggioBar}
          isConstrained={isConstrained}
          width={effectiveArpWidth}
          onDragStart={(e) => handleDrag(e, 'arpeggioBar')}
          isFlashingRed={isFlashingRed}
          uiUnlocked={uiUnlocked}
      />

      <InstrumentCluster 
          latchMode={latchMode}
          onLatch={onLatch}
          onSust={onSust}
          onPluck={onPluck}
          onVoice={onVoice}
          onKeys={onKeys}
          activeSustainedModes={activeSustainedModes}
          onClearSustain={onClearSustain}
          presets={presets}
          onPresetChange={onPresetChange}
          uiScale={uiScale}
          position={uiPositions.instruments}
          onDragStart={(e) => handleDrag(e, 'instruments')}
          uiUnlocked={uiUnlocked}
      />

      <PerformanceControls 
          isBendEnabled={isBendEnabled}
          latchMode={latchMode}
          isSustainEnabled={isSustainEnabled}
          uiUnlocked={uiUnlocked}
          uiScale={uiScale}
          positions={uiPositions}
          onBend={onBend}
          onSustainToggle={onSustainToggle}
          onOff={onOff}
          onPanic={onPanic}
          onDragStart={handleDrag}
      />

      <ViewControls 
          showIncreaseDepthButton={showIncreaseDepthButton}
          uiUnlocked={uiUnlocked}
          uiScale={uiScale}
          positions={uiPositions}
          onCenter={onCenter}
          onIncreaseDepth={onIncreaseDepth}
          onDecreaseDepth={onDecreaseDepth}
          onDragStart={handleDrag}
      />

      <ChordBar 
          savedChords={savedChords}
          activeChordIds={activeChordIds}
          chordShortcutSizeScale={chordShortcutSizeScale}
          uiUnlocked={uiUnlocked}
          uiScale={uiScale}
          position={uiPositions.chords}
          onAddChord={onAddChord}
          toggleChord={toggleChord}
          onRemoveChord={onRemoveChord}
          onDragStart={handleDrag}
      />
    </>
  );
};

export default FloatingControls;

import React, { useEffect } from 'react';
import { AppSettings } from '../types';

interface Props {
    settings: AppSettings;
    latchMode: number;

    isSettingsOpen: boolean;
    setIsSettingsOpen: React.Dispatch<React.SetStateAction<boolean>>;

    isSynthOpen: boolean;
    setIsSynthOpen: React.Dispatch<React.SetStateAction<boolean>>;

    setMasterVolume: React.Dispatch<React.SetStateAction<number>>;
    setSpatialScale: React.Dispatch<React.SetStateAction<number>>;
    setIsSequencerOpen: React.Dispatch<React.SetStateAction<boolean>>;

    handleDroneSelect: () => void;
    handleStringSelect: () => void;
    handlePluckedSelect: () => void;
    handleVoiceSelect: () => void;
    handleKeysSelect?: () => void; // New handler
    handleSustainToggle: () => void;
    handleBendToggle: () => void;
    handlePanic: () => void;
    handleCenter: () => void;
    handleOff: () => void;
    handleAddChord: () => void;
    handleIncreaseDepth: () => void;
    handleDecreaseDepth: () => void;
    handleArpBpmChange: (bpm: number) => void;
    handlePlayAll: () => void;
    handleStopAll: () => void;
}

export const useKeyboardControls = ({
    settings, latchMode, isSettingsOpen, setIsSettingsOpen, isSynthOpen, setIsSynthOpen,
    setMasterVolume, setSpatialScale, setIsSequencerOpen,
    handleDroneSelect, handleStringSelect, handlePluckedSelect, handleVoiceSelect, handleKeysSelect,
    handleSustainToggle, handleBendToggle, handlePanic, handleCenter, handleOff,
    handleAddChord, handleIncreaseDepth, handleDecreaseDepth, handleArpBpmChange,
    handlePlayAll, handleStopAll
}: Props) => {

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape' && (isSettingsOpen || isSynthOpen)) {
                setIsSettingsOpen(false); 
                setIsSynthOpen(false); 
                return;
            }

            const target = e.target as HTMLElement;
            if (target.tagName === 'INPUT' || target.tagName === 'SELECT' || target.tagName === 'TEXTAREA') return;
            if (!settings.enableKeyboardShortcuts) return;

            const key = e.key.toLowerCase();
            const map = settings.keyMappings;

            // Prevent default scrolling/browser actions for specific mapped keys
            if ([map.latch, map.volumeUp, map.volumeDown, map.spatialScaleUp, map.spatialScaleDown].map(k => k.toLowerCase()).includes(key)) {
                e.preventDefault();
            }

            if (key === map.latch.toLowerCase()) { if (latchMode === 1) handleStringSelect(); else handleDroneSelect(); }
            else if (key === map.modeDrone.toLowerCase()) handleDroneSelect();
            else if (key === map.modeStrings.toLowerCase()) handleStringSelect();
            else if (key === map.modePlucked.toLowerCase()) handlePluckedSelect();
            else if (key === map.modeBrass.toLowerCase()) handleVoiceSelect(); 
            else if (key === (map.modeKeys || '5').toLowerCase() && handleKeysSelect) handleKeysSelect(); // New mapping
            else if (key === map.sustain.toLowerCase()) handleSustainToggle();
            else if (key === map.bend.toLowerCase()) handleBendToggle();
            else if (key === map.panic.toLowerCase()) handlePanic();
            else if (key === map.center.toLowerCase()) handleCenter();
            else if (key === map.settings.toLowerCase()) { setIsSettingsOpen(prev => !prev); if(isSynthOpen) setIsSettingsOpen(false); }
            else if (key === map.synth.toLowerCase()) { setIsSynthOpen(prev => !prev); if(isSettingsOpen) setIsSettingsOpen(false); }
            else if (key === map.off.toLowerCase()) handleOff();
            else if (key === map.addChord.toLowerCase()) handleAddChord();
            else if (key === map.increaseDepth.toLowerCase()) handleIncreaseDepth();
            else if (key === map.decreaseDepth.toLowerCase()) handleDecreaseDepth();
            else if (key === map.volumeUp.toLowerCase()) setMasterVolume(v => Math.min(1.0, v + 0.05));
            else if (key === map.volumeDown.toLowerCase()) setMasterVolume(v => Math.max(0.0, v - 0.05));
            else if (key === map.spatialScaleUp.toLowerCase()) setSpatialScale(s => Math.min(2.0, s + 0.05));
            else if (key === map.spatialScaleDown.toLowerCase()) setSpatialScale(s => Math.max(0.0, s - 0.05));
            else if (key === map.bpmUp.toLowerCase()) handleArpBpmChange(settings.arpBpm + 1);
            else if (key === map.bpmDown.toLowerCase()) handleArpBpmChange(settings.arpBpm - 1);
            else if (key === map.toggleSequencer.toLowerCase()) setIsSequencerOpen(prev => !prev);
            else if (key === map.playAllArps.toLowerCase()) handlePlayAll();
            else if (key === map.stopAllArps.toLowerCase()) handleStopAll();
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [
        settings.enableKeyboardShortcuts, 
        settings.keyMappings, 
        settings.arpBpm,
        latchMode, 
        isSettingsOpen, 
        isSynthOpen,
        handleDroneSelect, handleStringSelect, handlePluckedSelect, handleVoiceSelect, handleKeysSelect,
        handleSustainToggle, handleBendToggle, handlePanic, handleCenter, handleOff,
        handleAddChord, handleIncreaseDepth, handleDecreaseDepth, handleArpBpmChange,
        handlePlayAll, handleStopAll, setIsSettingsOpen, setIsSynthOpen, setMasterVolume, setSpatialScale, setIsSequencerOpen
    ]);
};

import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import RecordingControls from './components/RecordingControls';
import { audioEngine } from './services/AudioEngine';
import { midiService } from './services/MidiService';
import { useStore } from './services/Store';
import { AppSettings, XYPos, UISize, SynthPreset } from './types';
import { PIXELS_PER_MM, SCROLLBAR_WIDTH } from './constants';
import { arpeggiatorService } from './services/ArpeggiatorService';
import { useAppLayout } from './hooks/useAppLayout';
import { useArpeggiatorLogic } from './hooks/useArpeggiatorLogic';
import { useKeyboardControls } from './hooks/useKeyboardControls';

const App: React.FC = () => {
  const { settings, presets, updateSettings, setPreset } = useStore();

  const [masterVolume, setMasterVolume] = useState(0.8);
  const [spatialScale, setSpatialScale] = useState(1.0); 
  const [brightness, setBrightness] = useState(1.0); // Tone control
  const [viewZoom, setViewZoom] = useState(1.0);

  const [activeChordIds, setActiveChordIds] = useState<string[]>([]);
  const [draggingId, setDraggingId] = useState<string | null>(null);

  // Latch Modes: 0=Off, 1=Drone, 2=Strings, 3=Plucked, 4=Brass, 5=Keys
  const [latchMode, setLatchMode] = useState<0 | 1 | 2 | 3 | 4 | 5>(2);

  // Track sustain ON/OFF preference per instrument mode
  // 5 (Keys) defaults to True (Sustain)
  const [sustainStates, setSustainStates] = useState<{ [key: number]: boolean }>({ 1: true, 2: true, 3: false, 4: false, 5: true });

  // Track which modes currently have active voices sustained
  const [activeSustainedModes, setActiveSustainedModes] = useState<number[]>([]);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);
  const [isSequencerOpen, setIsSequencerOpen] = useState(false);

  const diamondRef = useRef<TonalityDiamondHandle>(null);

  // Use custom hooks
  const { autoScaleFactor, isShortScreen } = useAppLayout(settings, updateSettings);
  const effectiveScale = autoScaleFactor * (settings.uiScale || 1.0);

  const {
      recordingArpId,
      setRecordingArpId,
      currentArpStep,
      recordingFlash,
      handleArpToggle,
      handleArpRecordNote,
      handleArpPatternUpdate,
      handleArpBpmChange,
      handleArpRowConfigChange,
      handlePlayAll,
      handleStopAll,
      stopArpAndRecording
  } = useArpeggiatorLogic(settings, updateSettings, diamondRef, latchMode);

  // --- AUDIO ENGINE SYNC ---
  useEffect(() => {
      audioEngine.updatePresets(presets);
  }, [presets]);

  useEffect(() => {
      audioEngine.updateSettings(settings);
  }, [settings]);

  // --- MIDI INPUT SYNC (SUSTAIN & BEND) ---
  useEffect(() => {
      // Subscribe to external MIDI sustain events
      const unsubscribeSustain = midiService.onSustain((isActive) => {
          setSustainStates(prev => ({ ...prev, [latchMode]: isActive }));
          updateSettings(prev => ({ ...prev, isSustainEnabled: isActive }));
      });

      // Subscribe to external MIDI Pitch Bend (Global)
      const unsubscribeBend = midiService.onGlobalBend((semitones) => {
          audioEngine.setGlobalBend(semitones);
      });

      return () => {
          unsubscribeSustain();
          unsubscribeBend();
      };
  }, [latchMode, updateSettings]);

  useEffect(() => {
    const warmup = (e: Event) => {
        audioEngine.resume().then(() => {});
        if (settings.midiEnabled) midiService.init(); 

        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };

    window.addEventListener('pointerdown', warmup);
    window.addEventListener('keydown', warmup);
    window.addEventListener('touchstart', warmup);
    window.addEventListener('touchend', warmup);
    window.addEventListener('click', warmup);

    return () => {
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };
  }, [settings.midiEnabled]);

  useEffect(() => {
      document.documentElement.style.setProperty('--ui-scale', effectiveScale.toString());
  }, [effectiveScale]);

  useEffect(() => {
    audioEngine.setMasterVolume(masterVolume);
  }, [masterVolume]);

  useEffect(() => {
    audioEngine.setGlobalSpatialScale(spatialScale);
  }, [spatialScale]);

  useEffect(() => {
    audioEngine.setGlobalBrightness(brightness);
  }, [brightness]);

  const handleLimitInteraction = (limit: number) => {
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      updateSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = () => {
    audioEngine.stopAll(); 
    stopArpAndRecording();
    midiService.panic();
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]); 
    setIsSettingsOpen(false);
    setIsSynthOpen(false);
  };

  const handleOff = () => {
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]);
    setRecordingArpId(null);
  };

  const switchInstrument = (newMode: 0 | 1 | 2 | 3 | 4 | 5) => {
      setSustainStates(prev => ({ ...prev, [latchMode]: settings.isSustainEnabled }));
      setLatchMode(newMode);
      let nextSustainState = sustainStates[newMode] ?? false;
      updateSettings(prev => ({ ...prev, isSustainEnabled: nextSustainState }));
  };

  const handleDroneSelect = () => switchInstrument(1);
  const handleStringSelect = () => switchInstrument(2);
  const handlePluckedSelect = () => switchInstrument(3);
  const handleVoiceSelect = () => switchInstrument(4);
  const handleKeysSelect = () => switchInstrument(5);

  const handleSustainToggle = () => {
      const willEnable = !settings.isSustainEnabled;
      setSustainStates(prev => ({ ...prev, [latchMode]: willEnable }));
      updateSettings(prev => ({ ...prev, isSustainEnabled: willEnable }));
      if (settings.midiEnabled) {
          midiService.sendSustain(willEnable);
      }
  };

  const handleBendToggle = () => {
      updateSettings(prev => ({ ...prev, isPitchBendEnabled: !prev.isPitchBendEnabled }));
  };

  const handleSustainStatusChange = (modes: number[]) => {
      setActiveSustainedModes(modes);
  };

  const handleClearSustain = (mode: number) => {
      diamondRef.current?.clearLatches(mode);
  };

  const handleCenter = () => diamondRef.current?.centerView();
  const handleIncreaseDepth = () => diamondRef.current?.increaseDepth();
  const handleDecreaseDepth = () => diamondRef.current?.decreaseDepth();

  const handleAddChord = () => {
      if (diamondRef.current) {
          const latchedData = diamondRef.current.getLatchedNodes();
          if (latchedData.length === 0) return;

          let slotIndex = settings.savedChords.findIndex(c => c.nodes.length === 0);
          if (slotIndex === -1) slotIndex = settings.savedChords.findIndex(c => !c.visible);

          if (slotIndex !== -1) {
              const newChords = [...settings.savedChords];
              const uniqueTimestamp = Date.now();
              const soundConfigs: Partial<Record<import('./types').PlayMode, SynthPreset>> = {};
              const usedModes = new Set<import('./types').PlayMode>();

              const simplifiedNodes = latchedData.map(({ node, mode }) => {
                  let modeStr: import('./types').PlayMode = 'normal';
                  if (mode === 1) modeStr = 'latch';
                  else if (mode === 2) modeStr = 'normal';
                  else if (mode === 3) modeStr = 'strum';
                  else if (mode === 4) modeStr = 'brass'; 
                  else if (mode === 5) modeStr = 'keys';
                  usedModes.add(modeStr);

                  return { id: node.id, n: node.n, d: node.d, voiceMode: modeStr };
              });

              usedModes.forEach(m => {
                  soundConfigs[m] = JSON.parse(JSON.stringify(presets[m]));
                  if (soundConfigs[m]) {
                      soundConfigs[m]!.id = `chord-${newChords[slotIndex].id}-${m}-${uniqueTimestamp}`;
                  }
              });

              newChords[slotIndex] = {
                  ...newChords[slotIndex],
                  nodes: simplifiedNodes,
                  visible: true,
                  position: { x: 0, y: 0 },
                  soundConfigs: soundConfigs,
                  soundConfig: undefined 
              };
              updateSettings(prev => ({ ...prev, savedChords: newChords }));
          }
      }
  };

  const toggleChord = (id: string) => {
      if (settings.isSustainEnabled) {
          setActiveChordIds(prev => prev.includes(id) ? prev.filter(c => c !== id) : [...prev, id]);
      } else {
          setActiveChordIds(prev => prev.includes(id) ? [] : [id]);
      }
  };

  const handleRemoveChord = (id: string) => {
      const newChords = settings.savedChords.map(c => {
          if (c.id === id) {
              return { ...c, nodes: [], visible: false, soundConfig: undefined, soundConfigs: undefined };
          }
          return c;
      });
      updateSettings(prev => ({ ...prev, savedChords: newChords }));

      if (activeChordIds.includes(id)) {
          setActiveChordIds(prev => prev.filter(cid => cid !== id));
      }
  };

  const handleUiPositionUpdate = (key: keyof AppSettings['uiPositions'], pos: XYPos) => {
      updateSettings(prev => ({ ...prev, uiPositions: { ...prev.uiPositions, [key]: pos } }));
  };

  const handleUiSizeUpdate = (key: keyof AppSettings['uiSizes'], size: UISize) => {
      updateSettings(prev => ({ ...prev, uiSizes: { ...prev.uiSizes, [key]: size } }));
  };

  useKeyboardControls({
      settings, latchMode,
      isSettingsOpen, setIsSettingsOpen,
      isSynthOpen, setIsSynthOpen,
      setMasterVolume, setSpatialScale, setIsSequencerOpen,
      handleDroneSelect, handleStringSelect, handlePluckedSelect, handleVoiceSelect, handleKeysSelect,
      handleSustainToggle, handleBendToggle, handlePanic, handleCenter, handleOff,
      handleAddChord, handleIncreaseDepth, handleDecreaseDepth, handleArpBpmChange,
      handlePlayAll, handleStopAll
  });

  const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;
  const getSafeAreas = () => {
      if (typeof document === 'undefined') return { top: 0, right: 0, bottom: 0, left: 0 };
      const div = document.createElement('div');
      div.style.paddingTop = 'env(safe-area-inset-top)';
      div.style.visibility = 'hidden';
      document.body.appendChild(div);
      const computed = getComputedStyle(div);
      const top = parseInt(computed.paddingTop) || 0;
      document.body.removeChild(div);
      return { top, left: 0, right: 0, bottom: 0 };
  };
  const safeArea = getSafeAreas();
  const leftOffset = `calc(${marginPx}px + ${safeArea.left}px)`;
  const rightOffset = `calc(${marginPx}px + ${safeArea.right}px + ${SCROLLBAR_WIDTH}px)`;
  const headerTop = `calc(${marginPx}px + ${safeArea.top}px)`;

  const headerBtnClass = "bg-slate-900/50 hover:bg-slate-800 px-3 py-1 rounded-xl backdrop-blur-sm transition border border-slate-700/50 h-8 flex items-center text-[10px] font-bold text-slate-400 uppercase tracking-widest hover:text-white shadow-lg";

  const arpX = settings.uiPositions.arpeggioBar.x;
  const volX = settings.uiPositions.volume.x;
  const gap = 20 * effectiveScale;
  const availableArpWidth = Math.max(0, volX - arpX - gap);
  const showArpBar = availableArpWidth > 250 * effectiveScale;

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">
      <div className="absolute z-50 pointer-events-none" style={{ top: headerTop, left: leftOffset }}>
        <h1 className="text-sm font-bold tracking-widest text-slate-500 opacity-20 leading-none">PRISMATONAL</h1>
      </div>

      <div className="absolute z-50 flex gap-2 pointer-events-auto" style={{ top: headerTop, right: rightOffset }}>
          <button onClick={() => setIsSettingsOpen(true)} className={headerBtnClass}>Settings</button>
          <button onClick={() => setIsSynthOpen(true)} className={headerBtnClass}>Synth</button>
      </div>

      <TonalityDiamond 
        ref={diamondRef}
        settings={settings}
        updateSettings={updateSettings}
        audioEngine={audioEngine} 
        onLimitInteraction={handleLimitInteraction}
        activeChordIds={activeChordIds}
        uiUnlocked={settings.uiUnlocked}
        latchMode={latchMode}
        isCurrentSustainEnabled={settings.isSustainEnabled} 
        globalScale={effectiveScale}
        viewZoom={viewZoom}
        onNodeTrigger={handleArpRecordNote}
        onSustainStatusChange={handleSustainStatusChange}
      />

      <FloatingControls 
        volume={masterVolume} setVolume={setMasterVolume}
        spatialScale={spatialScale} setSpatialScale={setSpatialScale}
        brightness={brightness} setBrightness={setBrightness}
        viewZoom={viewZoom} setViewZoom={setViewZoom}

        onPanic={handlePanic} onOff={handleOff}
        onLatch={handleDroneSelect} 
        onSust={handleStringSelect} 
        onPluck={handlePluckedSelect}
        onVoice={handleVoiceSelect}
        onKeys={handleKeysSelect}
        latchMode={latchMode}
        onBend={handleBendToggle} isBendEnabled={settings.isPitchBendEnabled}
        onSustainToggle={handleSustainToggle} isSustainEnabled={settings.isSustainEnabled}
        onCenter={handleCenter}
        onIncreaseDepth={handleIncreaseDepth} onDecreaseDepth={handleDecreaseDepth}
        onAddChord={handleAddChord} toggleChord={toggleChord}
        onRemoveChord={handleRemoveChord}
        activeChordIds={activeChordIds} savedChords={settings.savedChords}
        chordShortcutSizeScale={settings.chordShortcutSizeScale}
        showIncreaseDepthButton={settings.showIncreaseDepthButton}
        uiUnlocked={settings.uiUnlocked}
        uiPositions={settings.uiPositions} updatePosition={handleUiPositionUpdate}
        uiSizes={settings.uiSizes} updateSize={handleUiSizeUpdate}
        draggingId={draggingId} setDraggingId={setDraggingId}
        uiScale={effectiveScale}

        arpeggios={settings.arpeggios}
        arpBpm={settings.arpBpm}
        onArpToggle={handleArpToggle}
        onArpBpmChange={handleArpBpmChange}
        onArpRowConfigChange={handleArpRowConfigChange}
        onArpPatternUpdate={handleArpPatternUpdate}
        recordingArpId={recordingArpId}
        currentArpStep={currentArpStep}
        recordingFlash={recordingFlash}
        onPlayAll={handlePlayAll}
        onStopAll={handleStopAll}

        activeSustainedModes={activeSustainedModes}
        maxArpWidth={showArpBar ? availableArpWidth : 0}
        onClearSustain={handleClearSustain}

        isSequencerOpen={isSequencerOpen}
        onToggleSequencer={() => setIsSequencerOpen(p => !p)}

        presets={presets}
        onPresetChange={setPreset}
      />

      <LimitLayerControls 
        settings={settings} 
        updateSettings={updateSettings} 
        draggingId={draggingId} 
        setDraggingId={setDraggingId} 
        uiScale={effectiveScale}
        isShortScreen={isShortScreen}
      />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} updateSettings={updateSettings} />
      <SynthControls isOpen={isSynthOpen} onClose={() => setIsSynthOpen(false)} presets={presets} onChange={setPreset} />

      <RecordingControls />
    </div>
  );
};

export default App;

import { useState, useEffect, useRef } from 'react';
import { AppSettings } from '../types';
import { PIXELS_PER_MM, SCROLLBAR_WIDTH } from '../constants';

const REFERENCE_SHORT_EDGE = 1080;

const getSafeAreas = () => {
    if (typeof document === 'undefined') return { top: 0, right: 0, bottom: 0, left: 0 };
    const div = document.createElement('div');
    div.style.paddingTop = 'env(safe-area-inset-top)';
    div.style.paddingRight = 'env(safe-area-inset-right)';
    div.style.paddingBottom = 'env(safe-area-inset-bottom)';
    div.style.paddingLeft = 'env(safe-area-inset-left)';
    div.style.position = 'absolute';
    div.style.visibility = 'hidden';
    document.body.appendChild(div);
    const computed = getComputedStyle(div);
    const safe = {
        top: parseInt(computed.paddingTop) || 0,
        right: parseInt(computed.paddingRight) || 0,
        bottom: parseInt(computed.paddingBottom) || 0,
        left: parseInt(computed.paddingLeft) || 0
    };
    document.body.removeChild(div);
    return safe;
};

const calculateLayout = (w: number, h: number, scale: number, settings: AppSettings) => {
    const safeArea = getSafeAreas();
    const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;

    const marginLeft = marginPx + safeArea.left;
    const marginTop = marginPx + safeArea.top;
    const marginRight = marginPx + safeArea.right + SCROLLBAR_WIDTH;
    const marginBottom = marginPx + safeArea.bottom + SCROLLBAR_WIDTH;

    const internalBlockGap = 24 * scale; 
    const baseGap = Math.max(marginPx, 32 * scale); 

    const volumeBarWidth = (settings.uiSizes?.volume?.width || 600) * scale;

    const settingsGroupHeight = 40; 
    const largeBtn = 80 * scale; 
    const perfBtn = 92 * scale; 

    const colWidth = 136 * scale; 

    const verticalStackGap = 12 * PIXELS_PER_MM * scale; 

    const headerGap = 8 * scale; 
    const settingsGroupWidth = 170;

    const newPos = { ...settings.uiPositions };

    newPos.arpeggioBar = { x: marginLeft, y: marginTop };

    const volX = w - marginRight - settingsGroupWidth - headerGap - volumeBarWidth;
    newPos.volume = { x: volX, y: marginTop };

    // Bottom Bar Y Calculation
    const bottomY = h - marginBottom - largeBtn; 

    if (w < 600) {
        newPos.layers = { x: -9999, y: -9999 };
        newPos.instruments = { x: -9999, y: -9999 };
    } else {
        const extraLimitMargin = 12 * scale;
        const limitBarX = w - marginRight - colWidth - extraLimitMargin;
        const layersY = marginTop + settingsGroupHeight + verticalStackGap;
        newPos.layers = { x: limitBarX, y: layersY };

        // Center Instruments Cluster vertically between Arp Bar and Bottom Controls
        // Arp Bar Height approx 50px scaled. Bottom starts at bottomY.
        const topSpace = marginTop + (50 * scale);
        const availableHeight = bottomY - topSpace;
        const clusterHeight = 400 * scale; // Approx height of 5 buttons + gaps

        const centeredY = topSpace + (availableHeight / 2) - (clusterHeight / 2);

        // Ensure it doesn't overlap top or bottom
        const clampedY = Math.max(topSpace + 10, Math.min(centeredY, bottomY - clusterHeight - 10));

        newPos.instruments = { x: marginLeft, y: clampedY };
    }

    newPos.space = { x: -9999, y: -9999 };

    let currentX = marginLeft;

    newPos.center = { x: currentX, y: bottomY };
    currentX += (largeBtn + internalBlockGap); 

    if (settings.showIncreaseDepthButton) {
        newPos.depth = { x: currentX, y: bottomY };
        currentX += (largeBtn + internalBlockGap);
        newPos.decreaseDepth = { x: currentX, y: bottomY };
        currentX += (largeBtn + internalBlockGap);
    }

    currentX += baseGap; 
    newPos.chords = { x: currentX, y: bottomY };

    const perfY = h - marginBottom - perfBtn;

    let rightX = w - marginRight - perfBtn; 
    newPos.panic = { x: rightX, y: perfY };

    rightX -= (perfBtn + internalBlockGap); 
    newPos.off = { x: rightX, y: perfY };

    rightX -= (perfBtn + internalBlockGap); 
    newPos.sust = { x: rightX, y: perfY };

    rightX -= (perfBtn + internalBlockGap); 
    newPos.bend = { x: rightX, y: perfY };

    newPos.latch = { x: -9999, y: -9999 };

    return newPos;
};

export const useAppLayout = (
    settings: AppSettings,
    updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void
) => {
    const [autoScaleFactor, setAutoScaleFactor] = useState(1.0);
    const [isShortScreen, setIsShortScreen] = useState(false);

    const settingsRef = useRef(settings);
    settingsRef.current = settings;

    useEffect(() => {
        const handleResize = () => {
            const w = document.documentElement.clientWidth;
            const h = document.documentElement.clientHeight;

            setIsShortScreen(h < 800);

            const shortEdge = Math.min(w, h);
            const newAutoScale = shortEdge / REFERENCE_SHORT_EDGE;
            setAutoScaleFactor(newAutoScale);

            const currentSettings = settingsRef.current;
            const newEffectiveScale = newAutoScale * (currentSettings.uiScale || 1.0);

            const newPositions = calculateLayout(w, h, newEffectiveScale, currentSettings);

            updateSettings(prev => ({
                ...prev,
                uiPositions: newPositions
            }));
        };

        handleResize();
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, [
        settings.uiScale, 
        settings.uiEdgeMargin, 
        settings.showIncreaseDepthButton, 
        settings.uiSizes
    ]);

    return { autoScaleFactor, isShortScreen };
};

import { ArpeggioStep, ArpConfig, PlayMode } from '../types';
import { audioEngine } from './AudioEngine';
import { midiService } from './MidiService';
import { store } from './Store';

type OnStepCallback = (stepIndex: number) => void;
type OnNoteCallback = (nodeId: string, active: boolean) => void;

class ArpeggiatorService {
    private isRunning: boolean = false;
    private currentStepIndex: number = 0;

    // Lookahead Scheduler State
    private nextNoteTime: number = 0;
    private timerId: number | null = null;

    // The "source" steps from the recording
    private baseSteps: ArpeggioStep[] = [];
    private currentConfig: ArpConfig | null = null;

    // The "effective" steps after processing Direction and Octave Range
    private playbackQueue: { nodeId: string, ratio: number, originalIndex: number, muted?: boolean, mode?: number }[] = [];

    private onStepCallback: OnStepCallback | null = null;
    private onNoteCallback: OnNoteCallback | null = null; 

    // Track active visual nodes to ensure they are cleared on stop
    private activeVisualNodeIds: Set<string> = new Set();

    // Schedule ahead time (seconds)
    private readonly scheduleAheadTime = 0.1; // 100ms
    // Check interval (ms)
    private readonly lookaheadInterval = 25; // 25ms

    public start(steps: ArpeggioStep[], config: ArpConfig, bpm: number, onStep?: OnStepCallback, onNote?: OnNoteCallback) {
        this.stop();
        if (steps.length === 0) return;

        this.baseSteps = steps;
        this.currentConfig = config;
        this.onStepCallback = onStep || null;
        this.onNoteCallback = onNote || null;
        this.isRunning = true;
        this.currentStepIndex = 0;
        this.activeVisualNodeIds.clear();

        const ctx = audioEngine.getContext();
        if (ctx) {
            this.nextNoteTime = ctx.currentTime + 0.05; // Start slightly in future
            this.recalculateQueue();
            this.schedulerLoop();
        } else {
            // Fallback retry if context not ready
            audioEngine.init().then(() => {
                const ctx = audioEngine.getContext();
                if (ctx) {
                    this.nextNoteTime = ctx.currentTime + 0.05;
                    this.recalculateQueue();
                    this.schedulerLoop();
                }
            });
        }
    }

    public stop() {
        this.isRunning = false;
        if (this.timerId) {
            window.clearTimeout(this.timerId);
            this.timerId = null;
        }

        // Use stopGroup to clear future scheduled Arp events and trigger release for current ones
        // This ensures sound tails off naturally (doesn't hard cut like stopAll)
        audioEngine.stopGroup('arp-'); 

        // Explicitly clear any active visual feedback
        if (this.onNoteCallback) {
            this.activeVisualNodeIds.forEach(id => {
                this.onNoteCallback!(id, false);
            });
        }
        this.activeVisualNodeIds.clear();

        this.currentStepIndex = 0;
    }

    public updateBpm(newBpm: number) {
        // Scheduler picks up new BPM on next cycle automatically from store (accessed in advanceNoteTime)
    }

    private schedulerLoop() {
        if (!this.isRunning) return;

        const ctx = audioEngine.getContext();
        if (!ctx) return;

        const currentTime = ctx.currentTime;

        // Schedule notes falling within the lookahead window
        while (this.nextNoteTime < currentTime + this.scheduleAheadTime) {
            this.scheduleNote(this.nextNoteTime);
            this.advanceNoteTime();
        }

        this.timerId = window.setTimeout(() => this.schedulerLoop(), this.lookaheadInterval);
    }

    private advanceNoteTime() {
        const state = store.getSnapshot();
        const bpm = state.settings.arpBpm || 120;
        const config = this.currentConfig;
        if (!config) return;

        const beatMs = 60000 / bpm; 
        let div = 0.5; // default 1/8

        switch(config.division) {
            case '1/1': div = 4.0; break;
            case '1/2': div = 2.0; break;
            case '1/4': div = 1.0; break;
            case '1/8': div = 0.5; break;
            case '1/16': div = 0.25; break;
            case '1/32': div = 0.125; break;
            case '1/4T': div = 1.0 * (2/3); break;
            case '1/8T': div = 0.5 * (2/3); break;
            case '1/16T': div = 0.25 * (2/3); break;
        }

        let stepDurationSeconds = (beatMs * div) / 1000;

        // Swing Logic
        if (config.swing > 0) {
            const isEvenStep = (this.currentStepIndex % 2) === 0;
            const swingAmount = (config.swing / 100) * 0.33; 
            if (isEvenStep) stepDurationSeconds *= (1.0 + swingAmount); 
            else stepDurationSeconds *= (1.0 - swingAmount);
        }

        // Humanize Logic
        if (config.humanize && config.humanize > 0) {
            const jitterSeconds = (Math.random() - 0.5) * (config.humanize / 1000);
            stepDurationSeconds += jitterSeconds;
        }

        this.nextNoteTime += Math.max(0.01, stepDurationSeconds);
        this.currentStepIndex++;
    }

    private scheduleNote(time: number) {
        if (!this.playbackQueue.length || !this.currentConfig) return;

        const config = this.currentConfig;
        const patternLength = Math.max(1, config.length || 8);
        const effectiveLoopLength = Math.min(this.playbackQueue.length, patternLength);

        const wrappedIndex = this.currentStepIndex % effectiveLoopLength;
        const step = this.playbackQueue[wrappedIndex];

        const probability = (config.probability !== undefined) ? config.probability : 1.0;
        const shouldPlay = !step.muted && Math.random() < probability;

        if (shouldPlay) {
            const voiceId = `arp-${step.nodeId}-${Date.now()}-${Math.random()}`;
            const state = store.getSnapshot();

            // Calculate Gate Duration
            const beatMs = 60000 / (state.settings.arpBpm || 120);
            // Re-derive division scale for gate calculation
            let divBase = 0.5;
             switch(config.division) {
                case '1/1': divBase = 4.0; break;
                case '1/2': divBase = 2.0; break;
                case '1/4': divBase = 1.0; break;
                case '1/8': divBase = 0.5; break;
                case '1/16': divBase = 0.25; break;
                case '1/32': divBase = 0.125; break;
                case '1/4T': divBase = 1.0 * (2/3); break;
                case '1/8T': divBase = 0.5 * (2/3); break;
                case '1/16T': divBase = 0.25 * (2/3); break;
            }
            const durationSec = (beatMs * divBase / 1000) * Math.min(1.0, Math.max(0.1, config.gate));
            const stopTime = time + durationSec;

            // Determine Voice Slot based on recorded mode
            // Fallback to 'keys' if mode is missing or invalid
            let voiceSlot: PlayMode = 'keys';
            if (step.mode === 1) voiceSlot = 'latch'; // Drone
            else if (step.mode === 2) voiceSlot = 'normal'; // Strings
            else if (step.mode === 3) voiceSlot = 'strum'; // Plucked
            else if (step.mode === 4) voiceSlot = 'brass'; // Brass
            else if (step.mode === 5) voiceSlot = 'keys'; // Keys

            // Trigger Audio with precise time
            audioEngine.startVoice(voiceId, step.ratio, state.settings.baseFrequency, voiceSlot, 'gate', time);

            // Schedule Stop
            audioEngine.stopVoice(voiceId, stopTime);

            const ctx = audioEngine.getContext();
            const delayMs = Math.max(0, (time - (ctx?.currentTime || 0)) * 1000);

            // Schedule Visuals and MIDI (Best Effort)
            // Visuals are synced to occur roughly when the sound starts
            setTimeout(() => {
                if (!this.isRunning) return;

                // Visual ON
                this.activeVisualNodeIds.add(step.nodeId);
                if (this.onNoteCallback) this.onNoteCallback(step.nodeId, true);

                // MIDI ON
                if (state.settings.midiEnabled) {
                    midiService.noteOn(voiceId, step.ratio, state.settings.baseFrequency, state.settings.midiPitchBendRange);
                }

                // Schedule OFF
                setTimeout(() => {
                    if (!this.isRunning) return;

                    if (this.onNoteCallback) this.onNoteCallback(step.nodeId, false);
                    this.activeVisualNodeIds.delete(step.nodeId);

                    if (state.settings.midiEnabled) midiService.noteOff(voiceId);
                }, durationSec * 1000);

            }, delayMs);
        }

        // Step Callback (Visual Playhead)
        const visualDelay = Math.max(0, (time - (audioEngine.getContext()?.currentTime || 0)) * 1000);
        setTimeout(() => {
            if (this.isRunning && this.onStepCallback) {
                this.onStepCallback(step.originalIndex);
            }
        }, visualDelay);
    }

    private recalculateQueue() {
        if (!this.currentConfig) return;
        const config = this.currentConfig;

        let pool = this.baseSteps.map((s, i) => ({ ...s, originalIndex: i }));
        let final: { nodeId: string, ratio: number, originalIndex: number, muted?: boolean, mode?: number }[] = [];

        // 1. Octave Expansion
        const octaves = Math.max(1, Math.min(4, config.octaves));
        let expandedPool = [];
        for (let oct = 0; oct < octaves; oct++) {
            const mult = Math.pow(2, oct);
            for (const step of pool) {
                expandedPool.push({
                    nodeId: step.nodeId, 
                    ratio: step.ratio * mult,
                    originalIndex: step.originalIndex,
                    sortRatio: step.ratio * mult,
                    muted: step.muted,
                    mode: step.mode
                });
            }
        }

        // 2. Direction
        switch (config.direction) {
            case 'up':
                expandedPool.sort((a, b) => a.sortRatio - b.sortRatio);
                final = expandedPool;
                break;
            case 'down':
                expandedPool.sort((a, b) => b.sortRatio - a.sortRatio);
                final = expandedPool;
                break;
            case 'updown':
                {
                    const up = [...expandedPool].sort((a, b) => a.sortRatio - b.sortRatio);
                    const down = [...expandedPool].sort((a, b) => b.sortRatio - a.sortRatio);
                    final = [...up, ...down];
                }
                break;
            case 'random':
                // Shuffle
                for (let i = expandedPool.length - 1; i > 0; i--) {
                    const j = Math.floor(Math.random() * (i + 1));
                    [expandedPool[i], expandedPool[j]] = [expandedPool[j], expandedPool[i]];
                }
                final = expandedPool;
                break;
            case 'order':
            default:
                final = expandedPool; 
                break;
        }

        this.playbackQueue = final;
    }
}

export const arpeggiatorService = new ArpeggiatorService();

import { LatticeNode, LatticeLine, AppSettings, ButtonShape } from '../types';
import { MODE_COLORS } from '../constants';

interface NodeActivation {
    mode: number | string;
    timestamp: number;
    presetId: string;
}

interface ViewPort {
    x: number;
    y: number;
    w: number;
    h: number;
}

export interface RenderState {
    data: { nodes: LatticeNode[], lines: LatticeLine[] };
    settings: AppSettings;
    visualLatchedNodes: Map<string, NodeActivation[]>;
    activeLines: LatticeLine[];
    brightenedLines: LatticeLine[];
    harmonicNeighbors: Map<string, number>; // Maps NodeID -> Lowest Limit connecting to it
    activeCursors: Map<number, any>; 
    cursorPositions: Map<number, {x: number, y: number}>;
    nodeTriggerHistory: Map<string, number>;
    globalBend: number;
    effectiveScale: number;
    centerOffset: number; 
    view: ViewPort;
    time: number;
    latchMode: number;
}

// Render Order Priority (Highest = Topmost/Outer Ring)
const MODE_PRIORITY: Record<string | number, number> = {
    0: 0, // Cursor
    3: 1, // Strum
    2: 2, // Strings
    4: 3, // Brass
    5: 4, // Keys
    'arp': 5, // Arp
    1: 6  // Drone (Top)
};

interface SkinColors {
    bg: string;
    line: string;
    lineDim: string;
    nodeText: string;
    nodeStroke: string;
    nodeFill: (limit: number, colorMap: Record<number, string>) => string | CanvasGradient;
    shadow: string;
}

export class LatticeRenderer {
    private prevStaticDeps: string = "";
    private cachedDataNodes: LatticeNode[] | null = null;
    private cachedNodeMap: Map<string, LatticeNode> = new Map();

    render(
        bgCanvas: HTMLCanvasElement,
        staticCanvas: HTMLCanvasElement,
        activeCanvas: HTMLCanvasElement,
        state: RenderState
    ) {
        this.renderStatic(staticCanvas, state);
        this.renderDynamic(bgCanvas, activeCanvas, state);
    }

    private getSkinConfig(skin: string, ctx: CanvasRenderingContext2D): SkinColors {
        switch (skin) {
            case 'paper':
                return {
                    bg: '#f8fafc', // Slate-50
                    line: '#94a3b8', // Slate-400
                    lineDim: 'rgba(148, 163, 184, 0.2)',
                    nodeText: '#334155', // Slate-700
                    nodeStroke: '#334155',
                    nodeFill: () => '#ffffff',
                    shadow: 'rgba(0,0,0,0.1)'
                };
            case 'blueprint':
                return {
                    bg: '#1e3a8a', // Blue-900
                    line: 'rgba(147, 197, 253, 0.4)', // Blue-300
                    lineDim: 'rgba(147, 197, 253, 0.1)',
                    nodeText: '#dbeafe', // Blue-100
                    nodeStroke: '#93c5fd',
                    nodeFill: () => '#172554', // Blue-950
                    shadow: 'rgba(0,0,0,0.3)'
                };
            case 'cyber':
                return {
                    bg: '#000000',
                    line: '#333333',
                    lineDim: '#111111',
                    nodeText: '#ffffff',
                    nodeStroke: '#444444',
                    nodeFill: () => '#000000',
                    shadow: '#00ff00'
                };
            case 'default':
            default:
                return {
                    bg: 'transparent',
                    line: '#666',
                    lineDim: 'rgba(255,255,255,0.1)',
                    nodeText: '#ffffff',
                    nodeStroke: 'transparent',
                    nodeFill: (limit, map) => map[limit] || '#666',
                    shadow: 'black'
                };
        }
    }

    private renderStatic(canvas: HTMLCanvasElement, state: RenderState) {
        const { data, settings, effectiveScale, centerOffset, view } = state;

        const deps = JSON.stringify({
            tuning: settings.tuningSystem,
            layout: settings.layoutApproach,
            skin: settings.activeSkin,
            size: settings.buttonSizeScale,
            spacing: settings.buttonSpacingScale,
            colors: settings.colors,
            visuals: settings.limitVisuals,
            shape: settings.buttonShape,
            textScale: settings.nodeTextSizeScale,
            fractionBar: settings.showFractionBar,
            scale: effectiveScale,
            nodesLen: data.nodes.length,
            linesLen: data.lines.length,
            vx: view.x, vy: view.y, vw: view.w, vh: view.h 
        });

        if (deps === this.prevStaticDeps) return;
        this.prevStaticDeps = deps;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        if (canvas.width !== view.w * dpr || canvas.height !== view.h * dpr) {
            canvas.width = view.w * dpr;
            canvas.height = view.h * dpr;
        }

        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.scale(dpr, dpr);

        ctx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        const skin = this.getSkinConfig(settings.activeSkin, ctx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const cullPad = 200;
        const cullLeft = view.x - cullPad;
        const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad;
        const cullBottom = view.y + view.h + cullPad;

        // Draw Lines with Consonance Weighting
        const linesByLimit: Record<number, number[]> = {};
        for (const line of data.lines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

            if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
            linesByLimit[line.limit].push(x1, y1, x2, y2);
        }

        ctx.lineCap = 'round';
        for (const limitStr in linesByLimit) {
            const limit = parseInt(limitStr);
            const coords = linesByLimit[limit];

            let color = settings.colors[limit] || '#666';
            if (isFlatSkin) {
                color = limit === 1 ? skin.line : skin.lineDim;
            }

            const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

            // Consonance Weighting Logic
            let weight = 1.0;
            let baseAlpha = 0.3;

            if (limit === 1) { weight = 3.0; baseAlpha = 0.5; } // Octave
            else if (limit === 3) { weight = 2.5; baseAlpha = 0.45; } // P5 (Strong)
            else if (limit === 5) { weight = 1.8; baseAlpha = 0.35; } // M3 (Medium)
            else { weight = 0.8; baseAlpha = 0.2; } // 7, 11, 13 etc (Weak)

            ctx.beginPath();
            for(let i=0; i<coords.length; i+=4) {
                ctx.moveTo(coords[i], coords[i+1]);
                ctx.lineTo(coords[i+2], coords[i+3]);
            }

            ctx.lineWidth = weight * visualSettings.size * effectiveScale;
            ctx.strokeStyle = color;
            ctx.globalAlpha = isFlatSkin ? 1.0 : baseAlpha * visualSettings.opacity;

            if (limit === 1) ctx.setLineDash([5 * effectiveScale, 5 * effectiveScale]);
            else ctx.setLineDash([]);
            ctx.stroke();
        }
        ctx.setLineDash([]); 

        // Draw Nodes
        for (const node of data.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

            const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
            const limitScale = topVis.size;
            const limitOpacity = topVis.opacity;
            const radius = Math.max(0, baseRadius * limitScale);

            ctx.globalAlpha = 1.0 * limitOpacity;

            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }
            ctx.closePath();

            if (isFlatSkin) {
                ctx.fillStyle = skin.nodeFill(node.limitTop, settings.colors) as string;
                ctx.fill();
                ctx.lineWidth = 2 * effectiveScale;
                ctx.strokeStyle = skin.nodeStroke;
                ctx.stroke();
            } else {
                // Default Gradient
                const cTop = settings.colors[node.limitTop] || '#666';
                const cBottom = settings.colors[node.limitBottom] || '#666';
                const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
                grad.addColorStop(0.45, cTop);
                grad.addColorStop(0.55, cBottom);
                ctx.fillStyle = grad;
                ctx.fill();
            }

            const combinedScale = settings.buttonSizeScale * limitScale;
            if (combinedScale > 0.4) {
                ctx.fillStyle = skin.nodeText;
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale * effectiveScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 

                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (settings.showFractionBar) {
                    ctx.beginPath();
                    ctx.moveTo(x - (radius * 0.4), y);
                    ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1 * effectiveScale;
                    ctx.strokeStyle = isFlatSkin ? 'rgba(0,0,0,0.2)' : `rgba(255,255,255,${0.8 * limitOpacity})`;
                    if (settings.activeSkin === 'cyber') ctx.strokeStyle = '#fff';
                    ctx.stroke();
                }
                ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
            }
        }
    }

    private renderDynamic(bgCanvas: HTMLCanvasElement, activeCanvas: HTMLCanvasElement, state: RenderState) {
        const { 
            data, settings, visualLatchedNodes, activeLines, brightenedLines, harmonicNeighbors,
            activeCursors, cursorPositions, effectiveScale, centerOffset, view, time, latchMode 
        } = state;

        if (this.cachedDataNodes !== data.nodes) {
            this.cachedNodeMap = new Map(data.nodes.map(n => [n.id, n]));
            this.cachedDataNodes = data.nodes;
        }

        const bgCtx = bgCanvas.getContext('2d', { alpha: true });
        const activeCtx = activeCanvas.getContext('2d', { alpha: true });
        if (!bgCtx || !activeCtx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        if (bgCanvas.width !== view.w * dpr || bgCanvas.height !== view.h * dpr) {
            bgCanvas.width = view.w * dpr;
            bgCanvas.height = view.h * dpr;
            activeCanvas.width = view.w * dpr;
            activeCanvas.height = view.h * dpr;
        }

        bgCtx.setTransform(1, 0, 0, 1, 0, 0);
        activeCtx.setTransform(1, 0, 0, 1, 0, 0);

        // Clear only viewport
        bgCtx.clearRect(0, 0, bgCanvas.width, bgCanvas.height);
        activeCtx.clearRect(0, 0, activeCanvas.width, activeCanvas.height);

        // Transform
        bgCtx.scale(dpr, dpr);
        activeCtx.scale(dpr, dpr);
        bgCtx.translate(-view.x, -view.y);
        activeCtx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        const skin = this.getSkinConfig(settings.activeSkin, activeCtx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const animationSpeed = (settings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = settings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        const cullPad = 200;
        const cullLeft = view.x - cullPad;
        const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad;
        const cullBottom = view.y + view.h + cullPad;

        bgCtx.lineCap = 'round';
        activeCtx.lineCap = 'round';

        // 0. Draw Harmonic Neighbor Hints
        // Drawn on activeCtx but behind active nodes (since active nodes are drawn later in this function)
        // These will overlay the static nodes (z-index 20 vs 10), effectively tinting them
        if (harmonicNeighbors.size > 0) {
            for (const [id, limit] of harmonicNeighbors.entries()) {
                const node = this.cachedNodeMap.get(id);
                if (!node) continue;

                const x = node.x * spacing + centerOffset;
                const y = node.y * spacing + centerOffset;

                if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

                // Determine highlight color based on limit
                const color = settings.colors[limit] || '#ffffff';
                const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                const limitScale = vis.size;
                const radius = Math.max(0, baseRadius * limitScale * 1.3); // Slight halo

                activeCtx.beginPath();
                if (isDiamond) {
                    activeCtx.moveTo(x, y - radius);
                    activeCtx.lineTo(x + radius, y);
                    activeCtx.lineTo(x, y + radius);
                    activeCtx.lineTo(x - radius, y);
                } else {
                    activeCtx.arc(x, y, radius, 0, Math.PI * 2);
                }
                activeCtx.closePath();

                // Draw a stroke ring
                activeCtx.lineWidth = 3 * effectiveScale;
                activeCtx.strokeStyle = color;
                activeCtx.globalAlpha = 0.6;
                activeCtx.stroke();

                // Draw a fill tint
                activeCtx.fillStyle = color;
                activeCtx.globalAlpha = 0.15;
                activeCtx.fill();
            }
        }

        // 1. Draw Brightened Lines
        if (brightenedLines.length > 0) {
            bgCtx.setLineDash([]);
            for (const line of brightenedLines) {
                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset;

                if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

                let limitColor = settings.colors[line.limit] || '#666';
                if (isFlatSkin) limitColor = skin.line;

                bgCtx.beginPath();
                bgCtx.moveTo(x1, y1);
                bgCtx.lineTo(x2, y2);
                bgCtx.lineWidth = (settings.lineBrighteningWidth || 1.0) * effectiveScale;
                bgCtx.strokeStyle = limitColor;
                bgCtx.globalAlpha = isFlatSkin ? 0.6 : 0.8; 
                bgCtx.stroke();
            }
        }

        // 2. Draw Active Lines
        bgCtx.setLineDash([]); 
        for (const line of activeLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;
            if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

            let limitColor = settings.colors[line.limit] || '#666';
            if (isFlatSkin) limitColor = skin.nodeStroke;

            bgCtx.beginPath();
            bgCtx.moveTo(x1, y1);
            bgCtx.lineTo(x2, y2);
            bgCtx.lineWidth = (isFlatSkin ? 2 : 4) * effectiveScale;
            bgCtx.strokeStyle = limitColor;
            bgCtx.globalAlpha = 1.0;
            bgCtx.stroke();

            if (settings.isVoiceLeadingAnimationEnabled) {
                const grad = bgCtx.createLinearGradient(x1, y1, x2, y2);
                const p = flowPhase;
                const bright = isFlatSkin ? 'rgba(0,0,0,0.5)' : 'rgba(255,255,255,0.7)';
                const clear = 'rgba(255,255,255,0)';

                grad.addColorStop(0, clear);
                const pulseWidth = 0.2;
                const start = Math.max(0, p - pulseWidth);
                const end = Math.min(1, p + pulseWidth);
                if (start > 0) grad.addColorStop(start, clear);
                grad.addColorStop(p, bright); 
                if (end < 1) grad.addColorStop(end, clear);
                grad.addColorStop(1, clear);

                bgCtx.strokeStyle = grad;
                bgCtx.lineWidth = 10 * (0.5 + settings.voiceLeadingGlowAmount) * effectiveScale;
                bgCtx.globalAlpha = 0.3; 
                bgCtx.stroke();

                bgCtx.lineWidth = 4 * effectiveScale;
                bgCtx.globalAlpha = 1.0;
                bgCtx.stroke();
            }
        }

        // 3. Draw Active Nodes
        for (const [id, activations] of visualLatchedNodes.entries()) {
             const node = this.cachedNodeMap.get(id);
             if (!node) continue;

             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset;

             if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

             const cTop = settings.colors[node.limitTop] || '#666';
             const cBottom = settings.colors[node.limitBottom] || '#666';
             const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
             const limitScale = vis.size;
             const zoomScale = settings.latchedZoomScale;
             const baseRad = Math.max(0, baseRadius * limitScale * zoomScale);

             activeCtx.globalAlpha = 1.0; 
             activeCtx.beginPath();
             if (isDiamond) {
                activeCtx.moveTo(x, y - baseRad);
                activeCtx.lineTo(x + baseRad, y);
                activeCtx.lineTo(x, y + baseRad);
                activeCtx.lineTo(x - baseRad, y);
             } else {
                activeCtx.arc(x, y, baseRad, 0, Math.PI * 2);
             }
             activeCtx.closePath();

             if (isFlatSkin) {
                 activeCtx.fillStyle = '#ffffff'; 
                 if (settings.activeSkin === 'cyber') activeCtx.fillStyle = '#000000';
                 if (settings.activeSkin === 'blueprint') activeCtx.fillStyle = '#dbeafe';
             } else {
                 const grad = activeCtx.createLinearGradient(x, y - baseRad, x, y + baseRad);
                 grad.addColorStop(0.45, cTop);
                 grad.addColorStop(0.55, cBottom);
                 activeCtx.fillStyle = grad;
             }
             activeCtx.fill();

             const uniqueModes = new Set<number | string>();
             activations.forEach(a => uniqueModes.add(a.mode));

             // Sort using explicit priority
             const sortedModes = Array.from(uniqueModes).sort((a, b) => {
                 return (MODE_PRIORITY[a] ?? 99) - (MODE_PRIORITY[b] ?? 99);
             });

             const ringWidth = 4 * effectiveScale;
             const ringGap = 2 * effectiveScale;

             sortedModes.forEach((mode, index) => {
                 const color = MODE_COLORS[mode as keyof typeof MODE_COLORS] || '#ffffff';

                 // Special FX for Strum (3) and Arp
                 // Strum Ripple: If mode is 3, find the activation time and draw an expanding ring
                 if (mode === 3 || mode === 'arp') {
                     const activation = activations.find(a => a.mode === mode);
                     if (activation) {
                         const age = time - activation.timestamp;
                         if (age < 500) { // 500ms ripple
                             const rippleProgress = age / 500;
                             const rippleRadius = Math.max(0, baseRad + (rippleProgress * 40 * effectiveScale));
                             const rippleAlpha = 1.0 - rippleProgress;

                             activeCtx.beginPath();
                             activeCtx.arc(x, y, rippleRadius, 0, Math.PI * 2);
                             activeCtx.strokeStyle = color;
                             activeCtx.lineWidth = 2 * effectiveScale;
                             activeCtx.globalAlpha = rippleAlpha;
                             activeCtx.stroke();
                         }
                     }
                 }

                 const currentRadius = Math.max(0, baseRad + ringGap + (index * (ringWidth + ringGap)));

                 activeCtx.beginPath();
                 if (isDiamond) {
                    activeCtx.moveTo(x, y - currentRadius);
                    activeCtx.lineTo(x + currentRadius, y);
                    activeCtx.lineTo(x, y + currentRadius);
                    activeCtx.lineTo(x - currentRadius, y);
                 } else {
                    activeCtx.arc(x, y, currentRadius, 0, Math.PI * 2);
                 }
                 activeCtx.closePath();

                 activeCtx.strokeStyle = color;
                 activeCtx.lineWidth = ringWidth;
                 activeCtx.globalAlpha = 0.8;

                 activeCtx.shadowBlur = 8 * effectiveScale;
                 activeCtx.shadowColor = color;
                 activeCtx.stroke();
                 activeCtx.shadowBlur = 0;
             });

             const combinedScale = settings.buttonSizeScale * limitScale * zoomScale;
             if (combinedScale > 0.4) {
                activeCtx.fillStyle = isFlatSkin ? skin.nodeStroke : 'white';
                if (settings.activeSkin === 'cyber') activeCtx.fillStyle = '#00ff00';

                activeCtx.textAlign = 'center';
                activeCtx.textBaseline = 'middle';
                let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * settings.nodeTextSizeScale * effectiveScale;
                activeCtx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                activeCtx.fillText(node.n.toString(), x, y - (baseRad * spacingY));
                if (settings.showFractionBar) {
                    activeCtx.beginPath();
                    activeCtx.moveTo(x - (baseRad * 0.4), y);
                    activeCtx.lineTo(x + (baseRad * 0.4), y);
                    activeCtx.lineWidth = 1 * effectiveScale;
                    activeCtx.strokeStyle = isFlatSkin ? 'rgba(0,0,0,0.5)' : 'white';
                    activeCtx.stroke();
                }
                activeCtx.fillText(node.d.toString(), x, y + (baseRad * spacingY));
             }
        }

        // 4. Draw Cursors
        if (settings.isPitchBendEnabled && latchMode !== 3) {
            activeCursors.forEach(c => {
                if (c.originNodeId) { 
                    const node = this.cachedNodeMap.get(c.originNodeId);
                    if(node) {
                         const nx = node.x * spacing + centerOffset;
                         const ny = node.y * spacing + centerOffset;
                         const pos = cursorPositions.get(c.pointerId);
                         if (!pos) return;

                         const cx = pos.x;
                         const cy = pos.y;

                         activeCtx.beginPath();
                         activeCtx.moveTo(nx, ny);
                         activeCtx.lineTo(cx, cy);
                         activeCtx.strokeStyle = isFlatSkin ? skin.nodeStroke : 'white';
                         activeCtx.lineWidth = 2 * effectiveScale;
                         activeCtx.globalAlpha = 0.5;
                         activeCtx.stroke();
                         activeCtx.globalAlpha = 1.0;
                    }
                }
            });
        }
    }
}

const DSP_CONSTANTS = `
// --- 1. DSP UTILS & CONSTANTS ---
const TWO_PI = 2 * Math.PI;
const WAVETABLE_SIZE = 65536; 
const SINE_TABLE = new Float32Array(WAVETABLE_SIZE + 1);
const GLOTTAL_TABLE = new Float32Array(WAVETABLE_SIZE + 1); 

// Precompute Sine Table
for (let i = 0; i <= WAVETABLE_SIZE; i++) {
    const phase = i / WAVETABLE_SIZE;
    SINE_TABLE[i] = Math.sin(phase * TWO_PI);
}

// Precompute Glottal Table
{
    const numHarmonics = 64;
    for (let i = 0; i <= WAVETABLE_SIZE; i++) {
        let sample = 0;
        const phase = i / WAVETABLE_SIZE;
        for (let k = 1; k <= numHarmonics; k++) {
            const amp = 1.0 / Math.pow(k, 1.6);
            sample += amp * Math.cos(k * phase * TWO_PI);
        }
        GLOTTAL_TABLE[i] = sample;
    }
    let maxVal = 0;
    for (let i = 0; i <= WAVETABLE_SIZE; i++) maxVal = Math.max(maxVal, Math.abs(GLOTTAL_TABLE[i]));
    for (let i = 0; i <= WAVETABLE_SIZE; i++) GLOTTAL_TABLE[i] /= maxVal;
}

