                if (osc2ModPitch) { const cents = osc2.coarseDetune + osc2.fineDetune + hardPitch + (modP2 * 1200); freq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0); } else { freq = osc2StaticFreq; }
