const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  // Cache the bounding rect to avoid reflows
  const canvasRectRef = useRef<DOMRect | null>(null);

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  // Unified Scale Calculation
  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  const nodeMap = useMemo(() => {
      return new Map(data.nodes.map(n => [n.id, n]));
  }, [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const spacing = settings.buttonSpacingScale * effectiveScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + CENTER_OFFSET;
          const y = node.y * spacing + CENTER_OFFSET;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, effectiveScale]);

  // Create an adjacency map for fast neighbor lookup
  const adjacencyMap = useMemo(() => {
      const map = new Map<string, { target: string, limit: number }[]>();
      data.lines.forEach(line => {
          if (!map.has(line.sourceId)) map.set(line.sourceId, []);
          if (!map.has(line.targetId)) map.set(line.targetId, []);
          map.get(line.sourceId)!.push({ target: line.targetId, limit: line.limit });
          map.get(line.targetId)!.push({ target: line.sourceId, limit: line.limit });
      });
      return map;
  }, [data.lines]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); // nodeId -> timestamp
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              else if (mode === 5) pId = 'keys';
              else if (mode === 6) pId = 'percussion';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode >= 1; 
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;

          const isHybridMode = isSustainingInstrument && isSustainActive && isBendEnabled;
          if (isHybridMode) return; 

          const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
          if (isMelodic && cursor.hoverNodeId) {
              const nodeId = cursor.hoverNodeId;
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              // Mode derived from current LatchMode for immediate feedback
              const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
              list.push(activation);
              list.sort((a, b) => a.timestamp - b.timestamp);
          }
      });

      // Add External Triggers (Arp)
      externalTriggers.forEach((timestamp, nodeId) => {
          if (!visual.has(nodeId)) visual.set(nodeId, []);
          const list = visual.get(nodeId)!;
          // 'arp' mode renders Red
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled, externalTriggers]);

  // Calculate Harmonic Neighbors for Highlighting
  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  // Filter for consonance (Limit 3 and 5)
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; }, [harmonicNeighbors]);
  useEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useEffect(() => { latchModeRef.current = latchMode; }, [latchMode]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => {
      if (scrollContainerRef.current) {
          canvasRectRef.current = scrollContainerRef.current.getBoundingClientRect();
      }
  };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.removeEventListener('scroll', updateRect);
      };
  }, []);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id);
            if (n) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = CENTER_OFFSET - viewportW / 2;
        scrollContainerRef.current.scrollTop = CENTER_OFFSET - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          requestAnimationFrame(centerScroll);
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - CENTER_OFFSET;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - CENTER_OFFSET;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + CENTER_OFFSET) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + CENTER_OFFSET) - viewH / 2;

          requestAnimationFrame(updateRect);
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);

  const generationDeps = useMemo(() => {
      return JSON.stringify({
          tuning: settings.tuningSystem,
          layout: settings.layoutApproach,
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio,
          skin: settings.activeSkin
      });
  }, [settings.tuningSystem, settings.layoutApproach, settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, settings.activeSkin]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const effectiveSettings: AppSettings = JSON.parse(JSON.stringify(settings));
        const hiddenLimits = effectiveSettings.hiddenLimits || [];
        hiddenLimits.forEach((limit: number) => {
            // @ts-ignore
            if (effectiveSettings.limitDepths[limit] !== undefined) effectiveSettings.limitDepths[limit] = 0;
        });

        const result = generateLattice(effectiveSettings);
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => {
            if (hiddenLimits.includes(l.limit)) return false;
            if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
            return true;
        });

        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   const node = nodes.get(nodeId); 
                   if (node) {
                       // Only audio triggering for persistent nodes. Arp handles its own audio triggers.
                       audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                       if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();

      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + CENTER_OFFSET;
                  const ny = node.y * spacing + CENTER_OFFSET;

                  const isLatched = latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;
                  const activeRadius = baseRadius * activeZoom;

                  if (x < nx - activeRadius || x > nx + activeRadius || y < ny - activeRadius || y > ny + activeRadius) continue;

                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      updateRect();

      let canvasPos = { x: e.clientX, y: e.clientY };
      cursorPositionsRef.current.set(e.pointerId, canvasPos);

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      if (hitNode) {
        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        if (isSustainingInstrument && isSustainActive) {
             setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                 const next = new Map(prev);
                 const nodeModes = next.get(hitNode.id) || new Map<number, number>();

                 if (nodeModes.has(latchMode)) {
                     nodeModes.delete(latchMode);
                 } else {
                     nodeModes.set(latchMode, Date.now());
                 }

                 if (nodeModes.size > 0) next.set(hitNode.id, nodeModes);
                 else next.delete(hitNode.id);
                 return next;
             });
        }

        if (isBendEnabled || !isSustainActive) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
            const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

            audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
            if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        const bend = globalBendRef.current;
        const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
        worldY = (e.clientY - r.top) - pixelOffset + scrollContainerRef.current.scrollTop;
    }

    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        cursorPositionsRef.current.set(e.pointerId, { 
            x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
            y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
        });
    }

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isCurrentSustainEnabled;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 

    const isBending = isBendEnabled && !!cursor.originNodeId;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (originNode.y * spacing) + CENTER_OFFSET;
             const currentDeltaY = worldY - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);
             const finalRatio = originNode.ratio * bentRatio;

             const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         if (isSustainingInstrument && isSustainActive && isBendEnabled) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        if (!shouldSustainBend && cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(oldVoiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
             }
        }

        if (hitNode) {
             const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
             if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

             if (isSustainingInstrument && isSustainActive && !isBendEnabled) {
                const isDifferentNode = hitNode.id !== cursor.originNodeId;
                if (hasMoved || isDifferentNode) {
                    const currentModes = persistentLatchesRef.current.get(hitNode.id);
                    const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                    if (!isAlreadyLatched) { 
                        setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                            const next = new Map(prev);
                            const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                            nodeModes.set(latchMode, Date.now());
                            next.set(hitNode.id, nodeModes);
                            return next;
                        });
                        nodeTriggerHistory.current.set(hitNode.id, Date.now());
                    }
                }
             } 
             else if (!isBending) {
                 nodeTriggerHistory.current.set(hitNode.id, Date.now());

                 const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                 const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                 audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                 if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 

        if (cursor.originNodeId && isBendEnabled) {
            const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
            audioEngine.stopVoice(voiceId);
            if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
        }
        else if (cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(voiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
             }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const wrapper = wrapperRef.current;
      const scroller = scrollContainerRef.current;

      const currentScale = effectiveScaleRef.current; 

      if (wrapper) {
          const bend = globalBendRef.current;
          const pixelOffset = -bend * (PITCH_SCALE / 12) * currentScale;
          const transform = `translate3d(0px, ${pixelOffset}px, 0px)`;
          wrapper.style.transform = transform;
      }

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              visualLatchedNodes: visualLatchedRef.current, 
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              harmonicNeighbors: harmonicNeighborsRef.current, // Pass the harmonic neighbors map
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              centerOffset: CENTER_OFFSET,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time,
              latchMode: latchModeRef.current
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  const getBackgroundStyles = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

      const baseStyle: React.CSSProperties = {
          position: 'absolute', top: 0, left: 0,
          width: '100%', height: '100%', 
          pointerEvents: 'none',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', 
          backgroundSize: 'cover',
          backgroundColor: 'black' 
      };

      if (isJIOverride) {
          return { base: baseStyle };
      }

      switch (mode) {
          case 'gradient': {
              const type = settings.gradientType === 'radial' ? 'radial-gradient' : 'linear-gradient';
              const direction = settings.gradientType === 'linear' ? `${settings.gradientAngle}deg,` : 'circle at center,';
              const start = settings.gradientColorStart || '#000000';
              const end = settings.gradientColorEnd || '#000000';
              baseStyle.backgroundImage = `${type}(${direction} ${start}, ${end})`;
              baseStyle.backgroundColor = 'transparent'; 
              break;
          }
          case 'image': {
              if (settings.backgroundImageData) {
                  const tint = settings.bgImageTint || '#000000';
                  const strength = settings.bgImageTintStrength || 0;

                  const hexToRgba = (hex: string, alpha: number) => {
                      const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
                      return result ? `rgba(${parseInt(result[1], 16)},${parseInt(result[2], 16)},${parseInt(result[3], 16)},${alpha})` : 'rgba(0,0,0,0)';
                  };

                  const tintRgba = hexToRgba(tint, strength);
                  baseStyle.backgroundImage = `linear-gradient(${tintRgba}, ${tintRgba}), url("${settings.backgroundImageData}")`;
                  baseStyle.backgroundColor = 'transparent'; 

                  baseStyle.backgroundRepeat = settings.backgroundTiling ? 'repeat' : 'no-repeat';
                  baseStyle.backgroundSize = settings.backgroundTiling ? 'auto' : 'cover'; 

                  if (settings.bgImageGamma !== 1.0) {
                      baseStyle.filter = `brightness(${settings.bgImageGamma})`;
                  }
              }
              break;
          }
          case 'solid':
          default: {
              baseStyle.backgroundColor = settings.solidColor || '#ffffff';
              baseStyle.backgroundImage = 'none';
              break;
          }
      }

      return { base: baseStyle };
  };

  const bgStyles = getBackgroundStyles();

  return (
    <div 
        ref={scrollContainerRef} 
        className="w-full h-full overflow-auto relative bg-black" 
        style={{ touchAction: 'none' }} 
        onPointerDown={handlePointerDown} 
        onPointerMove={handlePointerMove} 
        onPointerUp={handlePointerUp} 
        onPointerLeave={handlePointerUp} 
        onPointerCancel={handlePointerUp}
    >
        <div className="sticky top-0 left-0 w-full h-full z-0 overflow-hidden pointer-events-none">
             <div style={bgStyles.base} className="absolute inset-0 w-full h-full z-0" />

             <div ref={wrapperRef} className="relative w-full h-full z-10">
                <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5]" style={{ width: '100%', height: '100%' }} />
                <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10]" style={{ width: '100%', height: '100%' }} />
                <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20]" style={{ width: '100%', height: '100%' }} />
                {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
             </div>
        </div>

        <div style={{ width: VIRTUAL_SIZE, height: VIRTUAL_SIZE }} className="relative z-[-1]" />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useState, useEffect } from 'react';
import { ChordDefinition, XYPos, AppSettings, ArpeggioDefinition, ArpConfig, ArpeggioStep, PresetState, PlayMode, SynthPreset, UISize } from '../types';
import ArpeggiatorBar from './controls/ArpeggiatorBar';
import InstrumentCluster from './controls/InstrumentCluster';
import MasterControls from './controls/MasterControls';
import PerformanceControls from './controls/PerformanceControls';
import ViewControls from './controls/ViewControls';
import ChordBar from './controls/ChordBar';
import { useDragManager } from '../hooks/useDragManager';

interface Props {
  volume: number;
  setVolume: (v: number) => void;
  spatialScale: number;
  setSpatialScale: (v: number) => void;
  brightness: number;
  setBrightness: (v: number) => void;
  viewZoom: number;
  setViewZoom: (v: number) => void;

  onPanic: () => void;
  onOff: () => void;
  onLatch: () => void; 
  onSust?: () => void; 
  onPluck?: () => void; 
  onVoice?: () => void; 
  onKeys?: () => void;
  onPercussion?: () => void; // New prop
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6; // Updated type
  onBend: () => void;
  isBendEnabled: boolean;
  onSustainToggle?: () => void;
  isSustainEnabled?: boolean;
  onCenter: () => void;
  onIncreaseDepth: () => void;
  onDecreaseDepth: () => void;
  onAddChord: () => void;
  toggleChord: (id: string) => void;
  onRemoveChord?: (id: string) => void;
  activeChordIds: string[];
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number;
  showIncreaseDepthButton: boolean;
  uiUnlocked: boolean;
  uiPositions: AppSettings['uiPositions'];
  updatePosition: (key: keyof AppSettings['uiPositions'], pos: XYPos) => void;
  uiSizes?: AppSettings['uiSizes'];
  updateSize?: (key: keyof AppSettings['uiSizes'], size: UISize) => void;
  draggingId: string | null;
  setDraggingId: (id: string | null) => void;
  uiScale?: number;

  arpeggios?: ArpeggioDefinition[];
  arpBpm?: number;
  onArpToggle?: (id: string) => void;
  onArpBpmChange?: (bpm: number) => void;
  onArpRowConfigChange?: (arpId: string, config: Partial<ArpConfig>) => void;
  onArpPatternUpdate?: (arpId: string, steps: ArpeggioStep[]) => void;
  recordingArpId?: string | null; 
  currentArpStep?: number;
  recordingFlash?: number;
  onPlayAll?: () => void;
  onStopAll?: () => void;

  maxArpWidth?: number; 
  activeSustainedModes?: number[];
  onClearSustain?: (mode: number) => void;

  isSequencerOpen: boolean;
  onToggleSequencer: () => void;

  presets?: PresetState;
  onPresetChange?: (mode: PlayMode, preset: SynthPreset) => void;
}

const FloatingControls: React.FC<Props> = ({ 
  volume, setVolume, spatialScale, setSpatialScale, brightness, setBrightness, viewZoom, setViewZoom,
  onPanic, onOff, onLatch, onSust, onPluck, onVoice, onKeys, onPercussion, latchMode, onBend, isBendEnabled, onSustainToggle, isSustainEnabled, onCenter, onIncreaseDepth, onDecreaseDepth, onAddChord, toggleChord, onRemoveChord,
  activeChordIds, savedChords, chordShortcutSizeScale,
  showIncreaseDepthButton, uiUnlocked, uiPositions, updatePosition,
  uiSizes, updateSize,
  draggingId, setDraggingId, uiScale = 1.0,
  arpeggios = [], arpBpm = 120, onArpToggle, onArpBpmChange, onArpRowConfigChange, onArpPatternUpdate, recordingArpId, currentArpStep, recordingFlash = 0,
  onPlayAll, onStopAll,
  maxArpWidth,
  activeSustainedModes = [],
  onClearSustain,
  isSequencerOpen,
  onToggleSequencer,
  presets,
  onPresetChange
}) => {

  const [isFlashingRed, setIsFlashingRed] = useState(false);

  useEffect(() => {
      if (recordingFlash > 0) {
          setIsFlashingRed(true);
          const t = setTimeout(() => setIsFlashingRed(false), 200);
          return () => clearTimeout(t);
      }
  }, [recordingFlash]);

  const handleDrag = useDragManager(
      uiUnlocked,
      draggingId,
      setDraggingId,
      (id, pos) => updatePosition(id as any, pos),
      uiPositions as any
  );

  const handleResize = (e: React.PointerEvent, key: 'volume' | 'arpeggioBar', axis: 'x' | 'y' | 'xy') => {
      e.stopPropagation();
      e.preventDefault();
      if (!updateSize || !uiSizes) return;

      const el = e.currentTarget as HTMLElement;
      el.setPointerCapture(e.pointerId);

      const startX = e.clientX;
      const startY = e.clientY;

      const initialWidth = uiSizes[key]?.width || (key === 'volume' ? 600 : 760);
      const initialHeight = uiSizes[key]?.height || (key === 'volume' ? 75 : 0); 

      const onMove = (evt: PointerEvent) => {
          const deltaX = (evt.clientX - startX) / uiScale;
          const deltaY = (evt.clientY - startY) / uiScale;

          let newWidth = initialWidth;
          let newHeight = initialHeight;

          if (axis === 'x' || axis === 'xy') {
              const minW = key === 'volume' ? 320 : 300; 
              newWidth = Math.max(minW, initialWidth + deltaX);
          }
          if ((axis === 'y' || axis === 'xy') && key === 'volume') {
              const minH = 60; 
              newHeight = Math.max(minH, initialHeight + deltaY);
          }

          updateSize(key, { width: newWidth, height: newHeight });
      };

      const onUp = () => {
          window.removeEventListener('pointermove', onMove);
          window.removeEventListener('pointerup', onUp);
          window.removeEventListener('pointercancel', onUp);
      };

      window.addEventListener('pointermove', onMove);
      window.addEventListener('pointerup', onUp);
      window.addEventListener('pointercancel', onUp);
  };

  const arpBaseWidth = uiSizes?.arpeggioBar?.width || 760;
  const userArpWidth = arpBaseWidth * uiScale;
  const effectiveArpWidth = maxArpWidth ? Math.min(userArpWidth, maxArpWidth) : userArpWidth;
  const isConstrained = effectiveArpWidth < (760 * uiScale) * 0.95;

  const resizeHandleStyle = "absolute z-50 bg-yellow-500/50 hover:bg-yellow-400 rounded-sm border border-white/50 shadow-sm transition-colors";

  return (
    <>
      <MasterControls 
          volume={volume} setVolume={setVolume}
          spatialScale={spatialScale} setSpatialScale={setSpatialScale}
          brightness={brightness} setBrightness={setBrightness}
          viewZoom={viewZoom} setViewZoom={setViewZoom}
          uiScale={uiScale}
          uiUnlocked={uiUnlocked}
          position={uiPositions.volume}
          size={uiSizes?.volume || { width: 600, height: 75 }}
          onDragStart={(e) => handleDrag(e, 'volume')}
          onResize={(e, axis) => handleResize(e, 'volume', axis)}
      />

      {/* Independent Resize Handle for Arp Bar */}
      <div style={{ position: 'absolute', left: 0, top: 0, width: 0, height: 0 }}>
          {uiUnlocked && (
              <div 
                  className={`${resizeHandleStyle} cursor-ew-resize`}
                  style={{ 
                      left: uiPositions.arpeggioBar.x + effectiveArpWidth - 6, 
                      top: uiPositions.arpeggioBar.y, 
                      height: 52 * uiScale, 
                      width: 12,
                      zIndex: 160 
                  }}
                  onPointerDown={(e) => handleResize(e, 'arpeggioBar', 'x')}
              />
          )}
      </div>

      <ArpeggiatorBar 
          arpeggios={arpeggios}
          arpBpm={arpBpm}
          onArpToggle={onArpToggle}
          onArpBpmChange={onArpBpmChange}
          onArpRowConfigChange={onArpRowConfigChange}
          onArpPatternUpdate={onArpPatternUpdate}
          recordingArpId={recordingArpId}
          currentArpStep={currentArpStep}
          onPlayAll={onPlayAll}
          onStopAll={onStopAll}
          isSequencerOpen={isSequencerOpen}
          onToggleSequencer={onToggleSequencer}
          uiScale={uiScale}
          position={uiPositions.arpeggioBar}
          isConstrained={isConstrained}
          width={effectiveArpWidth}
          onDragStart={(e) => handleDrag(e, 'arpeggioBar')}
          isFlashingRed={isFlashingRed}
          uiUnlocked={uiUnlocked}
      />

      <InstrumentCluster 
          latchMode={latchMode}
          onLatch={onLatch}
          onSust={onSust}
          onPluck={onPluck}
          onVoice={onVoice}
          onKeys={onKeys}
          onPercussion={onPercussion}
          activeSustainedModes={activeSustainedModes}
          onClearSustain={onClearSustain}
          presets={presets}
          onPresetChange={onPresetChange}
          uiScale={uiScale}
          position={uiPositions.instruments}
          onDragStart={(e) => handleDrag(e, 'instruments')}
          uiUnlocked={uiUnlocked}
      />

      <PerformanceControls 
          isBendEnabled={isBendEnabled}
          latchMode={latchMode as any} // Cast safe due to component flexibility
          isSustainEnabled={isSustainEnabled}
          uiUnlocked={uiUnlocked}
          uiScale={uiScale}
          positions={uiPositions}
          onBend={onBend}
          onSustainToggle={onSustainToggle}
          onOff={onOff}
          onPanic={onPanic}
          onDragStart={handleDrag}
      />

      <ViewControls 
          showIncreaseDepthButton={showIncreaseDepthButton}
          uiUnlocked={uiUnlocked}
          uiScale={uiScale}
          positions={uiPositions}
          onCenter={onCenter}
          onIncreaseDepth={onIncreaseDepth}
          onDecreaseDepth={onDecreaseDepth}
          onDragStart={handleDrag}
      />

      <ChordBar 
          savedChords={savedChords}
          activeChordIds={activeChordIds}
          chordShortcutSizeScale={chordShortcutSizeScale}
          uiUnlocked={uiUnlocked}
          uiScale={uiScale}
          position={uiPositions.chords}
          onAddChord={onAddChord}
          toggleChord={toggleChord}
          onRemoveChord={onRemoveChord}
          onDragStart={handleDrag}
      />
    </>
  );
};

export default FloatingControls;

import React from 'react';
import VolumeWheel from '../VolumeWheel';
import { PresetState, PlayMode, SynthPreset } from '../../types';
import { MODE_COLORS } from '../../constants';

interface Props {
    latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6;
    onLatch: () => void;
    onSust?: () => void;
    onPluck?: () => void;
    onVoice?: () => void;
    onKeys?: () => void;
    onPercussion?: () => void; // New prop
    activeSustainedModes: number[];
    onClearSustain?: (mode: number) => void;

    // Patch / Gain handling
    presets?: PresetState;
    onPresetChange?: (mode: PlayMode, preset: SynthPreset) => void;

    // UI
    uiScale: number;
    position: { x: number, y: number };
    onDragStart: (e: React.PointerEvent) => void;
    uiUnlocked: boolean;
}

const InstrumentCluster: React.FC<Props> = ({
    latchMode, onLatch, onSust, onPluck, onVoice, onKeys, onPercussion, activeSustainedModes, onClearSustain,
    presets, onPresetChange, uiScale, position, onDragStart, uiUnlocked
}) => {

    // Resize to ~75% of original (104 -> 78)
    const instrButtonSize = 78 * uiScale; 
    const wheelWidth = instrButtonSize * 0.45;

    const updatePatchGain = (mode: PlayMode, val: number) => {
        if (presets && onPresetChange) {
            const preset = presets[mode];
            onPresetChange(mode, { ...preset, gain: val });
        }
    };

    const handleButtonPress = (e: React.PointerEvent, action?: () => void) => {
        e.stopPropagation();
        if (uiUnlocked) {
            onDragStart(e);
        } else {
            if (e.button === 0 && action) action();
        }
    };

    const renderInstrument = (
        modeId: number,
        label: string,
        presetKey: PlayMode,
        onSelect: (() => void) | undefined,
        color: string
    ) => {
        const isSelected = latchMode === modeId;
        const isActive = activeSustainedModes.includes(modeId);
        // Show aura if active but not selected (so you know it's playing in background)
        // OR if selected and active (reinforcement)
        const showAura = isActive && !isSelected; 

        // Define styles based on color
        const baseStyle = {
            width: instrButtonSize,
            height: instrButtonSize,
            fontSize: 12 * uiScale, // Scaled down font size
            borderColor: isSelected ? color : 'rgba(148, 163, 184, 0.2)', // slate-400/20
            backgroundColor: isSelected ? `${color}20` : 'rgba(30, 41, 59, 0.6)', // slate-800/60
            color: isSelected ? 'white' : 'rgba(148, 163, 184, 0.8)',
            textShadow: isSelected ? `0 0 10px ${color}` : 'none',
            boxShadow: isSelected ? `0 0 15px ${color}40` : 'none'
        };

        return (
            <div className="flex items-center gap-2 relative group">
                <VolumeWheel 
                    value={presets?.[presetKey].gain || 0.5} 
                    onChange={(v) => updatePatchGain(presetKey, v)} 
                    color={color} 
                    width={wheelWidth} 
                    height={instrButtonSize} 
                    uiScale={uiScale}
                />

                <div className="relative">
                    <button 
                        className={`rounded-xl border-2 transition-all duration-200 transform active:scale-95 flex flex-col items-center justify-center font-bold uppercase tracking-wider backdrop-blur-md overflow-hidden relative ${showAura ? 'animate-pulse' : ''}`}
                        style={baseStyle}
                        onPointerDown={(e) => !uiUnlocked && handleButtonPress(e, onSelect)}
                        onContextMenu={(e) => { e.preventDefault(); if(!uiUnlocked && onClearSustain) onClearSustain(modeId); }}
                    >
                        {/* Internal Glow for Active state */}
                        {isActive && (
                            <div className="absolute inset-0 opacity-20 pointer-events-none" style={{ backgroundColor: color, filter: 'blur(10px)' }} />
                        )}
                        <span className="z-10">{label}</span>
                        {isActive && (
                            <div className="w-1.5 h-1.5 rounded-full mt-1 z-10" style={{ backgroundColor: color, boxShadow: `0 0 5px ${color}` }} />
                        )}
                    </button>

                    {/* Quick Clear Button (Visible if Active) */}
                    {isActive && !uiUnlocked && (
                        <button
                            className="absolute -top-2 -right-2 w-5 h-5 rounded-full bg-slate-900 border border-slate-600 text-slate-400 hover:text-white hover:bg-red-900 hover:border-red-500 flex items-center justify-center shadow-lg transition-colors z-20"
                            onPointerDown={(e) => { e.stopPropagation(); if(onClearSustain) onClearSustain(modeId); }}
                            title="Clear Sustained Notes"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" className="w-2.5 h-2.5" viewBox="0 0 20 20" fill="currentColor">
                                <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
                            </svg>
                        </button>
                    )}
                </div>
            </div>
        );
    };

    return (
        <div 
            className={`absolute flex flex-col gap-3 z-[140] bg-slate-950/80 p-2.5 rounded-2xl backdrop-blur-md border border-slate-700/50 shadow-2xl cursor-move transition-shadow ${uiUnlocked ? 'ring-2 ring-yellow-500/50' : 'hover:shadow-[0_0_20px_rgba(0,0,0,0.5)]'}`}
            style={{ 
                left: position.x, 
                top: position.y,
                touchAction: 'none'
            }}
            onPointerDown={onDragStart}
        >
            <div className="absolute inset-0 bg-gradient-to-b from-white/5 to-transparent rounded-2xl pointer-events-none" />

            {/* Header / Handle */}
            <div className="flex justify-center pb-1 border-b border-white/5 mb-1 opacity-50">
                <div className="w-8 h-1 bg-slate-600 rounded-full" />
            </div>

            {/* Strings (Blue) - Top */}
            {renderInstrument(2, "Strings", 'normal', onSust, MODE_COLORS[2])}

            {/* Brass (Yellow) */}
            {renderInstrument(4, "Brass", 'brass', onVoice, MODE_COLORS[4])}

            {/* Keys (Purple) */}
            {renderInstrument(5, "Keys", 'keys', onKeys, MODE_COLORS[5])}

            {/* Percussion (Pink) - New */}
            {renderInstrument(6, "Perc", 'percussion', onPercussion, MODE_COLORS[6])}

            {/* Plucked (Orange) */}
            {renderInstrument(3, "Plucked", 'strum', onPluck, MODE_COLORS[3])}

            {/* Drone (Green) - Bottom */}
            {renderInstrument(1, "Drone", 'latch', onLatch, MODE_COLORS[1])}
        </div>
    );
};

export default InstrumentCluster;

import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import RecordingControls from './components/RecordingControls';
import { audioEngine } from './services/AudioEngine';
import { midiService } from './services/MidiService';
import { useStore } from './services/Store';
import { AppSettings, XYPos, UISize, SynthPreset } from './types';
import { PIXELS_PER_MM, SCROLLBAR_WIDTH } from './constants';
import { arpeggiatorService } from './services/ArpeggiatorService';
import { useAppLayout } from './hooks/useAppLayout';
import { useArpeggiatorLogic } from './hooks/useArpeggiatorLogic';
import { useKeyboardControls } from './hooks/useKeyboardControls';

const App: React.FC = () => {
  const { settings, presets, updateSettings, setPreset } = useStore();

  const [masterVolume, setMasterVolume] = useState(0.8);
  const [spatialScale, setSpatialScale] = useState(1.0); 
  const [brightness, setBrightness] = useState(1.0); // Tone control
  const [viewZoom, setViewZoom] = useState(1.0);

  const [activeChordIds, setActiveChordIds] = useState<string[]>([]);
  const [draggingId, setDraggingId] = useState<string | null>(null);

  // Latch Modes: 0=Off, 1=Drone, 2=Strings, 3=Plucked, 4=Brass, 5=Keys, 6=Percussion
  const [latchMode, setLatchMode] = useState<0 | 1 | 2 | 3 | 4 | 5 | 6>(2);

  // Track sustain ON/OFF preference per instrument mode
  // 5 (Keys) defaults to True (Sustain)
  const [sustainStates, setSustainStates] = useState<{ [key: number]: boolean }>({ 
      1: true, 
      2: true, 
      3: false, 
      4: false, 
      5: true,
      6: false // Percussion defaults to non-sustaining (Gate/Trigger)
  });

  // Track which modes currently have active voices sustained
  const [activeSustainedModes, setActiveSustainedModes] = useState<number[]>([]);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);
  const [isSequencerOpen, setIsSequencerOpen] = useState(false);

  const diamondRef = useRef<TonalityDiamondHandle>(null);

  // Use custom hooks
  const { autoScaleFactor, isShortScreen } = useAppLayout(settings, updateSettings);
  const effectiveScale = autoScaleFactor * (settings.uiScale || 1.0);

  const {
      recordingArpId,
      setRecordingArpId,
      currentArpStep,
      recordingFlash,
      handleArpToggle,
      handleArpRecordNote,
      handleArpPatternUpdate,
      handleArpBpmChange,
      handleArpRowConfigChange,
      handlePlayAll,
      handleStopAll,
      stopArpAndRecording
  } = useArpeggiatorLogic(settings, updateSettings, diamondRef, latchMode);

  // --- AUDIO ENGINE SYNC ---
  useEffect(() => {
      audioEngine.updatePresets(presets);
  }, [presets]);

  useEffect(() => {
      audioEngine.updateSettings(settings);
  }, [settings]);

  // --- MIDI INPUT SYNC (SUSTAIN & BEND) ---
  useEffect(() => {
      // Subscribe to external MIDI sustain events
      const unsubscribeSustain = midiService.onSustain((isActive) => {
          setSustainStates(prev => ({ ...prev, [latchMode]: isActive }));
          updateSettings(prev => ({ ...prev, isSustainEnabled: isActive }));
      });

      // Subscribe to external MIDI Pitch Bend (Global)
      const unsubscribeBend = midiService.onGlobalBend((semitones) => {
          audioEngine.setGlobalBend(semitones);
      });

      return () => {
          unsubscribeSustain();
          unsubscribeBend();
      };
  }, [latchMode, updateSettings]);

  useEffect(() => {
    const warmup = (e: Event) => {
        audioEngine.resume().then(() => {});
        if (settings.midiEnabled) midiService.init(); 

        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };

    window.addEventListener('pointerdown', warmup);
    window.addEventListener('keydown', warmup);
    window.addEventListener('touchstart', warmup);
    window.addEventListener('touchend', warmup);
    window.addEventListener('click', warmup);

    return () => {
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };
  }, [settings.midiEnabled]);

  useEffect(() => {
      document.documentElement.style.setProperty('--ui-scale', effectiveScale.toString());
  }, [effectiveScale]);

  useEffect(() => {
    audioEngine.setMasterVolume(masterVolume);
  }, [masterVolume]);

  useEffect(() => {
    audioEngine.setGlobalSpatialScale(spatialScale);
  }, [spatialScale]);

  useEffect(() => {
    audioEngine.setGlobalBrightness(brightness);
  }, [brightness]);

  const handleLimitInteraction = (limit: number) => {
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      updateSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = () => {
    audioEngine.stopAll(); 
    stopArpAndRecording();
    midiService.panic();
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]); 
    setIsSettingsOpen(false);
    setIsSynthOpen(false);
  };

  const handleOff = () => {
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]);
    setRecordingArpId(null);
  };

  const switchInstrument = (newMode: 0 | 1 | 2 | 3 | 4 | 5 | 6) => {
      setSustainStates(prev => ({ ...prev, [latchMode]: settings.isSustainEnabled }));
      setLatchMode(newMode);
      let nextSustainState = sustainStates[newMode] ?? false;
      updateSettings(prev => ({ ...prev, isSustainEnabled: nextSustainState }));
  };

  const handleDroneSelect = () => switchInstrument(1);
  const handleStringSelect = () => switchInstrument(2);
  const handlePluckedSelect = () => switchInstrument(3);
  const handleVoiceSelect = () => switchInstrument(4);
  const handleKeysSelect = () => switchInstrument(5);
  const handlePercussionSelect = () => switchInstrument(6);

  const handleSustainToggle = () => {
      const willEnable = !settings.isSustainEnabled;
      setSustainStates(prev => ({ ...prev, [latchMode]: willEnable }));
      updateSettings(prev => ({ ...prev, isSustainEnabled: willEnable }));
      if (settings.midiEnabled) {
          midiService.sendSustain(willEnable);
      }
  };

  const handleBendToggle = () => {
      updateSettings(prev => ({ ...prev, isPitchBendEnabled: !prev.isPitchBendEnabled }));
  };

  const handleSustainStatusChange = (modes: number[]) => {
      setActiveSustainedModes(modes);
  };

  const handleClearSustain = (mode: number) => {
      diamondRef.current?.clearLatches(mode);
  };

  const handleCenter = () => diamondRef.current?.centerView();
  const handleIncreaseDepth = () => diamondRef.current?.increaseDepth();
  const handleDecreaseDepth = () => diamondRef.current?.decreaseDepth();

  const handleAddChord = () => {
      if (diamondRef.current) {
          const latchedData = diamondRef.current.getLatchedNodes();
          if (latchedData.length === 0) return;

          let slotIndex = settings.savedChords.findIndex(c => c.nodes.length === 0);
          if (slotIndex === -1) slotIndex = settings.savedChords.findIndex(c => !c.visible);

          if (slotIndex !== -1) {
              const newChords = [...settings.savedChords];
              const uniqueTimestamp = Date.now();
              const soundConfigs: Partial<Record<import('./types').PlayMode, SynthPreset>> = {};
              const usedModes = new Set<import('./types').PlayMode>();

              const simplifiedNodes = latchedData.map(({ node, mode }) => {
                  let modeStr: import('./types').PlayMode = 'normal';
                  if (mode === 1) modeStr = 'latch';
                  else if (mode === 2) modeStr = 'normal';
                  else if (mode === 3) modeStr = 'strum';
                  else if (mode === 4) modeStr = 'brass'; 
                  else if (mode === 5) modeStr = 'keys';
                  else if (mode === 6) modeStr = 'percussion';
                  usedModes.add(modeStr);

                  return { id: node.id, n: node.n, d: node.d, voiceMode: modeStr };
              });

              usedModes.forEach(m => {
                  soundConfigs[m] = JSON.parse(JSON.stringify(presets[m]));
                  if (soundConfigs[m]) {
                      soundConfigs[m]!.id = `chord-${newChords[slotIndex].id}-${m}-${uniqueTimestamp}`;
                  }
              });

              newChords[slotIndex] = {
                  ...newChords[slotIndex],
                  nodes: simplifiedNodes,
                  visible: true,
                  position: { x: 0, y: 0 },
                  soundConfigs: soundConfigs,
                  soundConfig: undefined 
              };
              updateSettings(prev => ({ ...prev, savedChords: newChords }));
          }
      }
  };

  const toggleChord = (id: string) => {
      if (settings.isSustainEnabled) {
          setActiveChordIds(prev => prev.includes(id) ? prev.filter(c => c !== id) : [...prev, id]);
      } else {
          setActiveChordIds(prev => prev.includes(id) ? [] : [id]);
      }
  };

  const handleRemoveChord = (id: string) => {
      const newChords = settings.savedChords.map(c => {
          if (c.id === id) {
              return { ...c, nodes: [], visible: false, soundConfig: undefined, soundConfigs: undefined };
          }
          return c;
      });
      updateSettings(prev => ({ ...prev, savedChords: newChords }));

      if (activeChordIds.includes(id)) {
          setActiveChordIds(prev => prev.filter(cid => cid !== id));
      }
  };

  const handleUiPositionUpdate = (key: keyof AppSettings['uiPositions'], pos: XYPos) => {
      updateSettings(prev => ({ ...prev, uiPositions: { ...prev.uiPositions, [key]: pos } }));
  };

  const handleUiSizeUpdate = (key: keyof AppSettings['uiSizes'], size: UISize) => {
      updateSettings(prev => ({ ...prev, uiSizes: { ...prev.uiSizes, [key]: size } }));
  };

  useKeyboardControls({
      settings, latchMode,
      isSettingsOpen, setIsSettingsOpen,
      isSynthOpen, setIsSynthOpen,
      setMasterVolume, setSpatialScale, setIsSequencerOpen,
      handleDroneSelect, handleStringSelect, handlePluckedSelect, handleVoiceSelect, handleKeysSelect, handlePercussionSelect,
      handleSustainToggle, handleBendToggle, handlePanic, handleCenter, handleOff,
      handleAddChord, handleIncreaseDepth, handleDecreaseDepth, handleArpBpmChange,
      handlePlayAll, handleStopAll
  });

  const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;
  const getSafeAreas = () => {
      if (typeof document === 'undefined') return { top: 0, right: 0, bottom: 0, left: 0 };
      const div = document.createElement('div');
      div.style.paddingTop = 'env(safe-area-inset-top)';
      div.style.visibility = 'hidden';
      document.body.appendChild(div);
      const computed = getComputedStyle(div);
      const top = parseInt(computed.paddingTop) || 0;
      document.body.removeChild(div);
      return { top, left: 0, right: 0, bottom: 0 };
  };
  const safeArea = getSafeAreas();
  const leftOffset = `calc(${marginPx}px + ${safeArea.left}px)`;
  const rightOffset = `calc(${marginPx}px + ${safeArea.right}px + ${SCROLLBAR_WIDTH}px)`;
  const headerTop = `calc(${marginPx}px + ${safeArea.top}px)`;

  const headerBtnClass = "bg-slate-900/50 hover:bg-slate-800 px-3 py-1 rounded-xl backdrop-blur-sm transition border border-slate-700/50 h-8 flex items-center text-[10px] font-bold text-slate-400 uppercase tracking-widest hover:text-white shadow-lg";

  const arpX = settings.uiPositions.arpeggioBar.x;
  const volX = settings.uiPositions.volume.x;
  const gap = 20 * effectiveScale;
  const availableArpWidth = Math.max(0, volX - arpX - gap);
  const showArpBar = availableArpWidth > 250 * effectiveScale;

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">
      <div className="absolute z-50 pointer-events-none" style={{ top: headerTop, left: leftOffset }}>
        <h1 className="text-sm font-bold tracking-widest text-slate-500 opacity-20 leading-none">PRISMATONAL</h1>
      </div>

      <div className="absolute z-50 flex gap-2 pointer-events-auto" style={{ top: headerTop, right: rightOffset }}>
          <button onClick={() => setIsSettingsOpen(true)} className={headerBtnClass}>Settings</button>
          <button onClick={() => setIsSynthOpen(true)} className={headerBtnClass}>Synth</button>
      </div>

      <TonalityDiamond 
        ref={diamondRef}
        settings={settings}
        updateSettings={updateSettings}
        audioEngine={audioEngine} 
        onLimitInteraction={handleLimitInteraction}
        activeChordIds={activeChordIds}
        uiUnlocked={settings.uiUnlocked}
        latchMode={latchMode}
        isCurrentSustainEnabled={settings.isSustainEnabled} 
        globalScale={effectiveScale}
        viewZoom={viewZoom}
        onNodeTrigger={handleArpRecordNote}
        onSustainStatusChange={handleSustainStatusChange}
      />

      <FloatingControls 
        volume={masterVolume} setVolume={setMasterVolume}
        spatialScale={spatialScale} setSpatialScale={setSpatialScale}
        brightness={brightness} setBrightness={setBrightness}
        viewZoom={viewZoom} setViewZoom={setViewZoom}

        onPanic={handlePanic} onOff={handleOff}
        onLatch={handleDroneSelect} 
        onSust={handleStringSelect} 
        onPluck={handlePluckedSelect}
        onVoice={handleVoiceSelect}
        onKeys={handleKeysSelect}
        onPercussion={handlePercussionSelect}
        latchMode={latchMode}
        onBend={handleBendToggle} isBendEnabled={settings.isPitchBendEnabled}
        onSustainToggle={handleSustainToggle} isSustainEnabled={settings.isSustainEnabled}
        onCenter={handleCenter}
        onIncreaseDepth={handleIncreaseDepth} onDecreaseDepth={handleDecreaseDepth}
        onAddChord={handleAddChord} toggleChord={toggleChord}
        onRemoveChord={handleRemoveChord}
        activeChordIds={activeChordIds} savedChords={settings.savedChords}
        chordShortcutSizeScale={settings.chordShortcutSizeScale}
        showIncreaseDepthButton={settings.showIncreaseDepthButton}
        uiUnlocked={settings.uiUnlocked}
        uiPositions={settings.uiPositions} updatePosition={handleUiPositionUpdate}
        uiSizes={settings.uiSizes} updateSize={handleUiSizeUpdate}
        draggingId={draggingId} setDraggingId={setDraggingId}
        uiScale={effectiveScale}

        arpeggios={settings.arpeggios}
        arpBpm={settings.arpBpm}
        onArpToggle={handleArpToggle}
        onArpBpmChange={handleArpBpmChange}
        onArpRowConfigChange={handleArpRowConfigChange}
        onArpPatternUpdate={handleArpPatternUpdate}
        recordingArpId={recordingArpId}
        currentArpStep={currentArpStep}
        recordingFlash={recordingFlash}
        onPlayAll={handlePlayAll}
        onStopAll={handleStopAll}

        activeSustainedModes={activeSustainedModes}
        maxArpWidth={showArpBar ? availableArpWidth : 0}
        onClearSustain={handleClearSustain}

        isSequencerOpen={isSequencerOpen}
        onToggleSequencer={() => setIsSequencerOpen(p => !p)}

        presets={presets}
        onPresetChange={setPreset}
      />

      <LimitLayerControls 
        settings={settings} 
        updateSettings={updateSettings} 
        draggingId={draggingId} 
        setDraggingId={setDraggingId} 
        uiScale={effectiveScale}
        isShortScreen={isShortScreen}
      />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} updateSettings={updateSettings} />
      <SynthControls isOpen={isSynthOpen} onClose={() => setIsSynthOpen(false)} presets={presets} onChange={setPreset} />

      <RecordingControls />
    </div>
  );
};

export default App;

import React, { useEffect } from 'react';
import { AppSettings } from '../types';

interface Props {
    settings: AppSettings;
    latchMode: number;

    isSettingsOpen: boolean;
    setIsSettingsOpen: React.Dispatch<React.SetStateAction<boolean>>;

    isSynthOpen: boolean;
    setIsSynthOpen: React.Dispatch<React.SetStateAction<boolean>>;

    setMasterVolume: React.Dispatch<React.SetStateAction<number>>;
    setSpatialScale: React.Dispatch<React.SetStateAction<number>>;
    setIsSequencerOpen: React.Dispatch<React.SetStateAction<boolean>>;

    handleDroneSelect: () => void;
    handleStringSelect: () => void;
    handlePluckedSelect: () => void;
    handleVoiceSelect: () => void;
    handleKeysSelect?: () => void;
    handlePercussionSelect?: () => void; // New handler
    handleSustainToggle: () => void;
    handleBendToggle: () => void;
    handlePanic: () => void;
    handleCenter: () => void;
    handleOff: () => void;
    handleAddChord: () => void;
    handleIncreaseDepth: () => void;
    handleDecreaseDepth: () => void;
    handleArpBpmChange: (bpm: number) => void;
    handlePlayAll: () => void;
    handleStopAll: () => void;
}

export const useKeyboardControls = ({
    settings, latchMode, isSettingsOpen, setIsSettingsOpen, isSynthOpen, setIsSynthOpen,
    setMasterVolume, setSpatialScale, setIsSequencerOpen,
    handleDroneSelect, handleStringSelect, handlePluckedSelect, handleVoiceSelect, handleKeysSelect, handlePercussionSelect,
    handleSustainToggle, handleBendToggle, handlePanic, handleCenter, handleOff,
    handleAddChord, handleIncreaseDepth, handleDecreaseDepth, handleArpBpmChange,
    handlePlayAll, handleStopAll
}: Props) => {

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape' && (isSettingsOpen || isSynthOpen)) {
                setIsSettingsOpen(false); 
                setIsSynthOpen(false); 
                return;
            }

            const target = e.target as HTMLElement;
            if (target.tagName === 'INPUT' || target.tagName === 'SELECT' || target.tagName === 'TEXTAREA') return;
            if (!settings.enableKeyboardShortcuts) return;

            const key = e.key.toLowerCase();
            const map = settings.keyMappings;

            // Prevent default scrolling/browser actions for specific mapped keys
            if ([map.latch, map.volumeUp, map.volumeDown, map.spatialScaleUp, map.spatialScaleDown].map(k => k.toLowerCase()).includes(key)) {
                e.preventDefault();
            }

            if (key === map.latch.toLowerCase()) { if (latchMode === 1) handleStringSelect(); else handleDroneSelect(); }
            else if (key === map.modeDrone.toLowerCase()) handleDroneSelect();
            else if (key === map.modeStrings.toLowerCase()) handleStringSelect();
            else if (key === map.modePlucked.toLowerCase()) handlePluckedSelect();
            else if (key === map.modeBrass.toLowerCase()) handleVoiceSelect(); 
            else if (key === (map.modeKeys || '5').toLowerCase() && handleKeysSelect) handleKeysSelect(); 
            else if (key === (map.modePercussion || '6').toLowerCase() && handlePercussionSelect) handlePercussionSelect();
            else if (key === map.sustain.toLowerCase()) handleSustainToggle();
            else if (key === map.bend.toLowerCase()) handleBendToggle();
            else if (key === map.panic.toLowerCase()) handlePanic();
            else if (key === map.center.toLowerCase()) handleCenter();
            else if (key === map.settings.toLowerCase()) { setIsSettingsOpen(prev => !prev); if(isSynthOpen) setIsSettingsOpen(false); }
            else if (key === map.synth.toLowerCase()) { setIsSynthOpen(prev => !prev); if(isSettingsOpen) setIsSettingsOpen(false); }
            else if (key === map.off.toLowerCase()) handleOff();
            else if (key === map.addChord.toLowerCase()) handleAddChord();
            else if (key === map.increaseDepth.toLowerCase()) handleIncreaseDepth();
            else if (key === map.decreaseDepth.toLowerCase()) handleDecreaseDepth();
            else if (key === map.volumeUp.toLowerCase()) setMasterVolume(v => Math.min(1.0, v + 0.05));
            else if (key === map.volumeDown.toLowerCase()) setMasterVolume(v => Math.max(0.0, v - 0.05));
            else if (key === map.spatialScaleUp.toLowerCase()) setSpatialScale(s => Math.min(2.0, s + 0.05));
            else if (key === map.spatialScaleDown.toLowerCase()) setSpatialScale(s => Math.max(0.0, s - 0.05));
            else if (key === map.bpmUp.toLowerCase()) handleArpBpmChange(settings.arpBpm + 1);
            else if (key === map.bpmDown.toLowerCase()) handleArpBpmChange(settings.arpBpm - 1);
            else if (key === map.toggleSequencer.toLowerCase()) setIsSequencerOpen(prev => !prev);
            else if (key === map.playAllArps.toLowerCase()) handlePlayAll();
            else if (key === map.stopAllArps.toLowerCase()) handleStopAll();
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [
        settings.enableKeyboardShortcuts, 
        settings.keyMappings, 
        settings.arpBpm,
        latchMode, 
        isSettingsOpen, 
        isSynthOpen,
        handleDroneSelect, handleStringSelect, handlePluckedSelect, handleVoiceSelect, handleKeysSelect, handlePercussionSelect,
        handleSustainToggle, handleBendToggle, handlePanic, handleCenter, handleOff,
        handleAddChord, handleIncreaseDepth, handleDecreaseDepth, handleArpBpmChange,
        handlePlayAll, handleStopAll, setIsSettingsOpen, setIsSynthOpen, setMasterVolume, setSpatialScale, setIsSequencerOpen
    ]);
};

import React, { useState, useMemo } from 'react';
import { SynthPreset, OscillatorConfig, ModulationRow, ReverbType, PresetState, PlayMode, ArpDirection } from '../types';
import { PRESETS, REVERB_DEFAULTS } from '../constants';
import { useStore } from '../services/Store';
import OscillatorPanel from './synth/OscillatorPanel';
import ModMatrixPanel from './synth/ModMatrixPanel';
import EffectsPanel from './synth/EffectsPanel';

interface Props {
  presets: PresetState;
  onChange: (mode: PlayMode, p: SynthPreset) => void;
  isOpen: boolean;
  onClose: () => void;
}

const SynthControls: React.FC<Props> = ({ presets, onChange, isOpen, onClose }) => {
  const [activeVoiceMode, setActiveVoiceMode] = useState<PlayMode>('normal');
  const [activeTab, setActiveTab] = useState<'osc1' | 'osc2' | 'osc3' | 'matrix' | 'fx' | 'arp'>('osc1');
  const { userBank, saveUserPatch } = useStore();

  const [isSaveMode, setIsSaveMode] = useState(false);
  const [saveSlotIndex, setSaveSlotIndex] = useState(0);
  const [saveName, setSaveName] = useState("");

  const categorizedPresets = useMemo(() => {
      const groups: Record<string, SynthPreset[]> = {};
      PRESETS.forEach(p => {
          const cat = p.category || 'Uncategorized';
          if (!groups[cat]) groups[cat] = [];
          groups[cat].push(p);
      });
      return groups;
  }, []);

  if (!isOpen) return null;

  const currentPreset = presets[activeVoiceMode];

  // --- Handlers for Child Components ---

  const handleGlobalUpdate = (key: keyof SynthPreset, val: any) => {
    onChange(activeVoiceMode, { ...currentPreset, [key]: val });
  };

  const handleArpUpdate = (key: keyof import('../types').ArpConfig, val: any) => {
      const currentArp = currentPreset.arpConfig || { direction: 'order', division: '1/8', octaves: 1, gate: 0.8, swing: 0, length: 8, probability: 1.0, humanize: 0 };
      const newArp = { ...currentArp, [key]: val };
      onChange(activeVoiceMode, { ...currentPreset, arpConfig: newArp });
  };

  const handleOscUpdate = (oscKey: 'osc1' | 'osc2' | 'osc3', key: keyof OscillatorConfig, val: any) => {
      const newOsc = { ...currentPreset[oscKey], [key]: val };
      onChange(activeVoiceMode, { ...currentPreset, [oscKey]: newOsc });
  };

  const handleMatrixUpdate = (newMatrix: ModulationRow[]) => {
      onChange(activeVoiceMode, { ...currentPreset, modMatrix: newMatrix });
  };

  const handleReverbTypeChange = (type: ReverbType) => {
      const defaults = REVERB_DEFAULTS[type];
      onChange(activeVoiceMode, {
          ...currentPreset,
          reverbType: type,
          reverbSize: defaults.size,
          reverbDamping: defaults.damping,
          reverbDiffusion: defaults.diffusion
      });
  };

  // --- Preset Management ---

  const loadPreset = (p: SynthPreset) => {
      const cloned = JSON.parse(JSON.stringify(p));
      onChange(activeVoiceMode, cloned);
  };

  const handleResetToDefault = () => {
      const factory = PRESETS.find(p => p.name === currentPreset.name);
      if (factory) {
          loadPreset(factory);
      } else {
          const userP = userBank.find(p => p.name === currentPreset.name);
          if (userP) loadPreset(userP);
      }
  };

  const handleSaveToSlot = () => {
      if (saveName.trim() === "") return;
      const presetToSave = { ...currentPreset, name: saveName, id: `user-${Date.now()}` };
      saveUserPatch(saveSlotIndex, presetToSave);
      setIsSaveMode(false);
  };

  const arpConfig = currentPreset.arpConfig || { direction: 'order', division: '1/8', octaves: 1, gate: 0.8, swing: 0, length: 8, probability: 1.0, humanize: 0 };

  const getModeLabel = (mode: PlayMode): string => {
      switch(mode) {
          case 'normal': return 'STRINGS';
          case 'latch': return 'DRONE';
          case 'strum': return 'PLUCKED';
          case 'brass': return 'BRASS';
          case 'keys': return 'KEYS';
          case 'percussion': return 'PERC';
          default: return mode;
      }
  };

  return (
    <div className="fixed top-0 right-0 h-full w-[450px] bg-slate-800/95 backdrop-blur shadow-2xl z-[200] transform transition-transform p-0 overflow-hidden border-l border-slate-700 flex flex-col">
        {/* Header */}
        <div className="flex justify-between items-center p-6 pb-2">
            <h2 className="text-xl font-bold">Synth Engine</h2>
            <button onClick={onClose} className="text-slate-400 hover:text-white">Close</button>
        </div>

        {/* Mode Selector */}
        <div className="flex border-b border-slate-700 bg-slate-900/80 mx-4 mt-2 rounded-t-lg overflow-hidden">
            {(['latch', 'normal', 'strum', 'brass', 'keys', 'percussion'] as PlayMode[]).map(mode => (
                <button
                    key={mode}
                    onClick={() => setActiveVoiceMode(mode)}
                    className={`flex-1 py-3 text-[10px] font-bold uppercase transition border-b-2 ${activeVoiceMode === mode ? 'border-indigo-500 text-indigo-400 bg-slate-800' : 'border-transparent text-slate-500 hover:bg-slate-800/50'}`}
                >
                    {getModeLabel(mode)}
                </button>
            ))}
        </div>

        {/* Preset Bar */}
        {!isSaveMode ? (
            <div className="px-6 py-4 bg-slate-800 border-b border-slate-700 space-y-3">
                <div>
                    <label className="block text-[10px] text-slate-400 mb-1 uppercase font-bold tracking-wider">Active Patch</label>
                    <div className="relative">
                        <select 
                            value={currentPreset.name}
                            onChange={(e) => {
                                let p = PRESETS.find(pr => pr.name === e.target.value);
                                if (!p) p = userBank.find(pr => pr.name === e.target.value);
                                if (p) loadPreset(p);
                            }}
                            className="w-full bg-slate-900 border border-slate-600 rounded p-2 text-sm text-white appearance-none focus:border-indigo-500 focus:outline-none"
                        >
                            {Object.keys(categorizedPresets).map(cat => (
                                <optgroup key={cat} label={cat}>{categorizedPresets[cat].map(p => (<option key={p.id} value={p.name}>{p.name}</option>))}</optgroup>
                            ))}
                            <optgroup label="User Bank">{userBank.map((p, idx) => (<option key={`user-${idx}`} value={p.name}>{p.name}</option>))}</optgroup>
                        </select>
                    </div>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => { setSaveName(currentPreset.name); setIsSaveMode(true); }} className="flex-1 py-1.5 bg-indigo-700 hover:bg-indigo-600 text-indigo-100 text-xs font-bold rounded transition border border-indigo-500">Save to Slot</button>
                    <button onClick={handleResetToDefault} className="flex-1 py-1.5 bg-yellow-700 hover:bg-yellow-600 text-yellow-100 text-xs font-bold rounded transition border border-yellow-500">Reset to Default</button>
                </div>
            </div>
        ) : (
            <div className="px-6 py-4 bg-indigo-900/20 border-b border-indigo-500/30">
                <div className="flex justify-between items-center mb-2">
                    <label className="text-[10px] text-indigo-300 font-bold uppercase">Save Current Patch</label>
                    <button onClick={() => setIsSaveMode(false)} className="text-xs text-slate-400 hover:text-white">Cancel</button>
                </div>
                <input type="text" value={saveName} onChange={(e) => setSaveName(e.target.value)} placeholder="Patch Name" className="w-full bg-slate-900 border border-indigo-500 rounded p-2 text-sm mb-2 text-white" />
                <select value={saveSlotIndex} onChange={(e) => setSaveSlotIndex(parseInt(e.target.value))} className="w-full bg-slate-900 border border-slate-600 rounded p-2 text-sm text-white mb-3">
                    {userBank.map((p, idx) => (<option key={idx} value={idx}>Slot {idx+1}: {p.name}</option>))}
                </select>
                <button onClick={handleSaveToSlot} className="w-full py-2 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded text-xs transition">Confirm Save</button>
            </div>
        )}

        {/* Navigation Tabs */}
        <div className="flex border-b border-slate-700 bg-slate-900/50">
            {(['osc1', 'osc2', 'osc3'] as const).map(osc => (
                 <button key={osc} onClick={() => setActiveTab(osc)} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === osc ? 'text-indigo-400 border-b-2 border-indigo-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                    <span>{osc.replace('osc', 'Osc ')}</span>
                    <span className={`w-1.5 h-1.5 rounded-full ${currentPreset[osc].enabled ? 'bg-green-500 shadow-[0_0_5px_rgba(34,197,94,0.8)]' : 'bg-slate-700'}`}></span>
                </button>
            ))}
             <button onClick={() => setActiveTab('matrix')} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === 'matrix' ? 'text-purple-400 border-b-2 border-purple-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                <span>Mods</span>
                <span className={`w-1.5 h-1.5 rounded-full ${(currentPreset.modMatrix?.length || 0) > 0 ? 'bg-purple-500 shadow-[0_0_5px_rgba(168,85,247,0.8)]' : 'bg-slate-700'}`}></span>
            </button>
             <button onClick={() => setActiveTab('fx')} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === 'fx' ? 'text-green-400 border-b-2 border-green-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                <span>FX</span>
                <span className="w-1.5 h-1.5 rounded-full bg-green-500 shadow-[0_0_5px_rgba(34,197,94,0.8)]"></span>
            </button>
             <button onClick={() => setActiveTab('arp')} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === 'arp' ? 'text-red-400 border-b-2 border-red-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                <span>Arp</span>
                <span className={`w-1.5 h-1.5 rounded-full bg-red-500 shadow-[0_0_5px_rgba(239,68,68,0.8)]`}></span>
            </button>
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto p-6 scrollbar-thin scrollbar-thumb-slate-700">
            {activeTab === 'osc1' && (
                <OscillatorPanel 
                    label="Oscillator 1" 
                    config={currentPreset.osc1} 
                    isPrimary={true} 
                    onUpdate={(k, v) => handleOscUpdate('osc1', k, v)} 
                />
            )}

            {activeTab === 'osc2' && (
                <OscillatorPanel 
                    label="Oscillator 2" 
                    config={currentPreset.osc2} 
                    onUpdate={(k, v) => handleOscUpdate('osc2', k, v)} 
                />
            )}

            {activeTab === 'osc3' && (
                <OscillatorPanel 
                    label="Oscillator 3" 
                    config={currentPreset.osc3} 
                    onUpdate={(k, v) => handleOscUpdate('osc3', k, v)} 
                />
            )}

            {activeTab === 'matrix' && (
                <ModMatrixPanel 
                    modMatrix={currentPreset.modMatrix || []} 
                    onChange={handleMatrixUpdate} 
                />
            )}

            {activeTab === 'fx' && (
                <EffectsPanel 
                    preset={currentPreset} 
                    isReverbEditable={activeVoiceMode === 'normal'} 
                    onUpdate={handleGlobalUpdate} 
                    onReverbTypeChange={handleReverbTypeChange} 
                />
            )}

            {activeTab === 'arp' && (
                <div className="space-y-6 animate-in fade-in duration-300">
                    <h3 className="text-sm font-bold text-slate-300 uppercase mb-2">Granular Arp Settings ({getModeLabel(activeVoiceMode)})</h3>
                    <div className="p-4 bg-slate-900/50 rounded border border-slate-700 space-y-4">

                        <div>
                            <label className="block text-xs font-bold text-slate-400 mb-1">Direction</label>
                            <div className="flex bg-slate-800 rounded border border-slate-600 overflow-hidden">
                                {(['order', 'up', 'down', 'updown', 'random'] as ArpDirection[]).map(dir => (
                                    <button 
                                        key={dir} 
                                        onClick={() => handleArpUpdate('direction', dir)}
                                        className={`flex-1 py-1 text-[10px] uppercase font-bold ${arpConfig.direction === dir ? 'bg-red-600 text-white' : 'text-slate-400 hover:bg-slate-700'}`}
                                    >
                                        {dir}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Probability</span> <span className="font-bold text-white">{(arpConfig.probability !== undefined ? arpConfig.probability * 100 : 100).toFixed(0)}%</span></label>
                            <input type="range" min="0" max="1" step="0.05" value={arpConfig.probability !== undefined ? arpConfig.probability : 1.0} onChange={(e) => handleArpUpdate('probability', parseFloat(e.target.value))} className="w-full h-1 bg-red-500 rounded appearance-none cursor-pointer" />
                            <p className="text-[9px] text-slate-500 mt-1">Chance of each step playing.</p>
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Humanize</span> <span className="font-bold text-white">{arpConfig.humanize || 0} ms</span></label>
                            <input type="range" min="0" max="100" step="5" value={arpConfig.humanize || 0} onChange={(e) => handleArpUpdate('humanize', parseInt(e.target.value))} className="w-full h-1 bg-red-500 rounded appearance-none cursor-pointer" />
                            <p className="text-[9px] text-slate-500 mt-1">Random timing offset per step.</p>
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Octave Range</span> <span className="font-bold text-white">{arpConfig.octaves}</span></label>
                            <input type="range" min="1" max="4" step="1" value={arpConfig.octaves} onChange={(e) => handleArpUpdate('octaves', parseInt(e.target.value))} className="w-full h-1 bg-red-600 rounded appearance-none cursor-pointer" />
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Swing</span> <span className="font-bold text-white">{arpConfig.swing}%</span></label>
                            <input type="range" min="0" max="100" step="1" value={arpConfig.swing} onChange={(e) => handleArpUpdate('swing', parseInt(e.target.value))} className="w-full h-1 bg-red-600 rounded appearance-none cursor-pointer" />
                        </div>

                    </div>
                    <p className="text-[10px] text-slate-500 text-center italic">Sequence Length and Division are now controlled per-pattern in the matrix view.</p>
                </div>
            )}

            <div className="pt-4 border-t border-slate-700 mt-4">
                <p className="text-[10px] text-slate-500 text-center">Changes applied immediately</p>
            </div>
        </div>
    </div>
  );
};

export default SynthControls;

export enum LimitType {
  LIMIT_2 = 2,
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_9 = 9,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
  LIMIT_15 = 15,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
  NOISE = 'noise',
  GLOTTAL = 'glottal',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export type TuningSystem = 'ji' | 'et' | 'indian' | 'pythagorean';

export type LayoutApproach = 
  | 'lattice' | 'diamond' | 'row' | 'honeycomb' // JI specific
  | 'et_wheel' | 'et_grid' | 'et_row'           // ET specific
  | 'indian_circle' | 'indian_thaat'           // Indian specific
  | 'pyth_spiral' | 'pyth_row';                // Pythagorean specific

export type BackgroundMode = 'solid' | 'gradient' | 'image';

export interface LimitColorMap {
  [key: number]: string;
}

export interface Particle {
    id: number;
    x: number;
    y: number;
    vx: number;
    vy: number;
    life: number; // 0.0 to 1.0
    color: string;
    size: number;
}

export interface ChordNode {
  id: string; // Coordinate key
  n: number;
  d: number;
  voiceMode?: PlayMode; // The mode/patch used when this note was saved
}

export interface ChordDefinition {
  id: string; // "A", "B", etc.
  label: string;
  color: string;
  nodes: ChordNode[];
  visible: boolean; // Is shortcut on screen?
  position: { x: number; y: number }; // Relative position or legacy absolute
  soundConfig?: SynthPreset; // Legacy single patch
  soundConfigs?: Partial<Record<PlayMode, SynthPreset>>; // New multi-patch storage
}

export interface ArpeggioStep {
    nodeId: string;
    ratio: number;
    n?: number;
    d?: number;
    muted?: boolean;
    limit?: number; // For quality indication (maxPrime)
    mode?: number; // The instrument mode (1=Drone, 2=Strings, 3=Plucked, 4=Brass, 5=Keys, 6=Percussion) active during recording
}

export type ArpDirection = 'order' | 'up' | 'down' | 'updown' | 'random';
export type ArpDivision = '1/1' | '1/2' | '1/4' | '1/8' | '1/16' | '1/32' | '1/4T' | '1/8T' | '1/16T';

export interface ArpConfig {
    direction: ArpDirection;
    division: ArpDivision;
    octaves: number; // 1 to 4
    gate: number; // 0.1 to 1.0
    swing: number; // 0 to 100
    length: number; // 1 to 32 (Pattern Length)
    probability: number; // 0.0 to 1.0 (Chance to play)
    humanize: number; // 0 to 100 (ms of jitter)
}

export interface ArpeggioDefinition {
    id: string; // "A" - "G"
    steps: ArpeggioStep[];
    isPlaying: boolean;
    config: ArpConfig;
}

export interface XYPos {
  x: number;
  y: number;
}

export interface UISize {
  width: number;
  height?: number;
}

export interface KeyMappings {
    // Navigation & View
    center: string;
    increaseDepth: string;
    decreaseDepth: string;
    settings: string;

    // Global & Panic
    volumeUp: string;
    volumeDown: string;
    panic: string;
    off: string;

    // Patch & Mode Controls (Bottom Right Priority)
    latch: string; // Toggle Drone/Strings mode
    sustain: string; // Toggles Sustain (SUST)
    bend: string; // Toggles Pitch Bend
    modeDrone: string; // Switch to Drone Mode
    modeStrings: string; // Switch to Strings Mode
    modePlucked: string; // Switch to Plucked Mode
    modeBrass: string; // Switch to Brass Mode
    modeKeys: string; // Switch to Keys Mode
    modePercussion: string; // Switch to Percussion Mode (New)
    synth: string; // Toggle Synth Panel

    // Chords & Performance
    addChord: string;

    // Tempo
    bpmUp: string;
    bpmDown: string;

    // Arpeggiator
    toggleSequencer: string;
    playAllArps: string;
    stopAllArps: string;

    // Legacy / View scaling (kept for compatibility)
    spatialScaleUp: string;
    spatialScaleDown: string;
}

export interface BackgroundPreset {
  id: string;
  name: string;
  data: string | null; // Base64 or null if empty
}

export interface AppSettings {
  // Global Tuning
  tuningSystem: TuningSystem;
  layoutApproach: LayoutApproach;
  activeSkin: string; // Dynamic skin ID for visual presentation

  // Individual depths (Steps from center)
  limitDepths: {
    3: number;
    5: number;
    7: number;
    9: number;
    11: number;
    13: number;
    15: number;
  };

  // Replaces limitComplexities with toggleable Odd Identities (1, 3, 5, 7, 9, 11, 13, 15)
  // Stores simple array of enabled identities (e.g. [1, 3, 5])
  enabledIdentities: number[]; 

  // Increase Depth Settings
  showIncreaseDepthButton: boolean;
  centerResetsDepth: boolean;

  // Chords
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number; // 0.33 to 1.0 relative to main buttons

  // Arpeggios
  arpeggios: ArpeggioDefinition[];
  arpBpm: number;

  // Visible toggle for lower limits (View only)
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  // Audio Settings
  baseFrequency: number; // Hz for 1/1
  audioLatencyHint: 'interactive' | 'balanced' | 'playback'; // Buffer size control
  enableOversampling: boolean; // New: Performance vs Quality toggle
  wavetableSize: 2048 | 8192 | 65536; // Wavetable resolution
  interpolationType: 'linear' | 'cubic'; // Wavetable interpolation method

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Voice Leading Visuals
  isVoiceLeadingAnimationEnabled: boolean;
  voiceLeadingAnimationSpeed: number; // seconds
  voiceLeadingReverseDir: boolean; // Reverse the direction of the flow animation
  voiceLeadingGlowAmount: number; // 0.0 to 1.0 (Controls width/intensity of the lobe)
  voiceLeadingSteps: number; // 1 or 2 (Reach for active voice leading lines)

  // Line Appearance
  baseLineWidth: number; // 0.5 to 3.0 (Static lines)
  lineBrighteningEnabled: boolean;
  lineBrighteningSteps: number; // 1 or 2
  lineBrighteningWidth: number; // 1.0 to 4.0

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  latchedZoomScale: number; // Scale factor for active nodes (1.0 to 2.0)

  // Appearance
  buttonSizeScale: number; // Global Scalar 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  latticeAspectRatio: number; // 0.5 (Stretched X) to 2.0 (Squished X)
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;
  limitVisuals?: { [key: number]: { size: number; opacity: number } };

  // Text Appearance
  nodeTextSizeScale: number; // 0.5 to 2.0
  showFractionBar: boolean;

  isPitchBendEnabled: boolean;
  isSustainEnabled: boolean; // Global Sustain Modifier (Gate vs Latch)
  isStrumEnabled: boolean; // Global Strum Modifier (Trigger vs Gate)
  chordsAlwaysRelatch: boolean; // New: Whether selecting a chord always retriggers/relatches its notes
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;

  // --- Visuals - Background ---
  backgroundMode: BackgroundMode;
  backgroundPresets: BackgroundPreset[];

  // Solid
  solidColor: string; // Hex color for solid background

  // Gradient
  gradientColorStart: string;
  gradientColorEnd: string;
  gradientType: 'linear' | 'radial';
  gradientAngle: number; // Degrees (0-360)

  // Image
  backgroundImageData: string | null; // Base64
  backgroundYOffset: number; // Vertical offset
  backgroundTiling: boolean; // Tile the background image
  bgImageGamma: number; // 0.5 to 1.5 (Brightness control)
  bgImageTint: string; // Tint Color
  bgImageTintStrength: number; // 0.0 to 1.0

  // Overlay
  isOverlayEnabled: boolean;
  overlayBlendMode: 'normal' | 'multiply' | 'screen' | 'overlay';
  overlayOpacity: number;
  overlayType: 'solid' | 'gradient';
  overlayColorStart: string;
  overlayColorEnd: string;
  overlayGradientType: 'linear' | 'radial';
  overlayGradientAngle: number;

  // Rainbow Settings
  rainbowSaturation: number;
  rainbowBrightness: number;
  rainbowOffset: number;
  isColoredIlluminationEnabled: boolean;
  isRainbowModeEnabled: boolean;

  // MIDI Settings
  midiEnabled: boolean;
  midiOutputId: string | null;
  midiPitchBendRange: number; // Semitones (typically 2, 12, 24, or 48)

  // Behavior
  enableKeyboardShortcuts: boolean;
  keyMappings: KeyMappings;
  strumDuration: number; // seconds, 0.1 to 2.0
  enableAudioRecording: boolean; // Renamed from recordScreenActivity

  // UI Relocation & Scaling
  uiUnlocked: boolean;
  uiScale: number; // 0.5 (Tiny) to 1.5 (Huge)
  uiEdgeMargin: number; // in Millimeters (1-10)
  uiPositions: {
    volume: XYPos;
    space: XYPos;
    panic: XYPos;
    off: XYPos;
    latch: XYPos; // Legacy key, kept for data compatibility, now usually unused or re-mapped
    sust: XYPos;
    bend: XYPos;
    center: XYPos;
    depth: XYPos;
    decreaseDepth: XYPos;
    chords: XYPos;
    layers: XYPos;
    arpeggioBar: XYPos;
    instruments: XYPos; // New cluster for Drone/String
    complexity: XYPos; // New: Complexity Controls
  };
  uiSizes: {
    volume: UISize;
    arpeggioBar: UISize;
  };
}

export type FilterType = 'lowpass' | 'highpass' | 'bandpass' | 'notch' | 'peak' | 'lowshelf' | 'highshelf';

export interface OscillatorConfig {
  enabled: boolean;
  waveform: WaveformType;
  coarseDetune: number; // Cents -1200 to 1200
  fineDetune: number; // Cents -50 to 50
  gain: number; // 0 to 1 (Mix)

  // Envelope
  attack: number;
  decay: number;
  sustain: number; // Level 0.0 to 1.0
  release: number;

  // Extended Envelope (Finite Sustain)
  holdDecay?: number; // Time to decay from Sustain Level to 0 while Key Held (0 or undefined = Infinite)
  pedalDecay?: number; // Time to decay from Current Level to 0 while Sustain Pedal Active (0 or undefined = Infinite)

  // Filter
  filterCutoff: number; // Hz
  filterResonance: number; // Q factor
  filterType: FilterType;

  // LFO
  lfoRate: number; // Hz
  lfoDepth: number; // Amount 0-100
  lfoWaveform: 'sine' | 'triangle' | 'square' | 'sawtooth' | 'noise'; // New LFO Shape
  lfoTarget: 'none' | 'pitch' | 'filter' | 'tremolo';
  lfoDelay: number; // Fade in time (seconds)
}

export type ModSource = 'lfo1' | 'lfo2' | 'lfo3' | 'env1' | 'env2' | 'env3';
export type ModTarget = 
    'osc1_pitch' | 'osc1_gain' | 'osc1_cutoff' | 'osc1_res' |
    'osc2_pitch' | 'osc2_gain' | 'osc2_cutoff' | 'osc2_res' |
    'osc3_pitch' | 'osc3_gain' | 'osc3_cutoff' | 'osc3_res';

export interface ModulationRow {
    id: string;
    enabled: boolean;
    source: ModSource;
    target: ModTarget;
    amount: number; // -100 to 100
}

export type ReverbType = 'room' | 'hall' | 'cathedral' | 'plate' | 'shimmer';

export interface SynthPreset {
  id: number | string;
  name: string;
  category?: string; // New field for categorization
  isHeader?: boolean; // New field for UI headers in lists

  osc1: OscillatorConfig;
  osc2: OscillatorConfig;
  osc3: OscillatorConfig;

  // Modulation Matrix
  modMatrix: ModulationRow[];

  // Master Gain for the preset
  gain: number; 

  // Resonator / Body (Formerly Formant/Vocal)
  resonatorMix?: number; // 0 to 1 (0 = Bypass)
  resonatorSweep?: number; // 0.0 to 1.0 (Timbre sweep)

  // Noise / Air (Formerly Aspiration)
  noiseGain?: number; // 0 to 1 (Noise level)
  noiseCutoff?: number; // Hz (Highpass filter on noise)

  // Expression / Performance
  portamento?: number; // 0 to 1 (Glide time)
  acousticSustain?: boolean; // Legacy: Maps to pedalDecay in logic if needed, but pedalDecay takes precedence

  // Stereo & Pan
  spread?: number; // 0 to 1 (Voice Stereo Width)
  stereoPanSpeed?: number; // Hz
  stereoPanDepth?: number; // 0 to 1 (Auto-Pan amount)

  // Reverb Unit
  reverbType?: ReverbType; // Convolution Preset (Logic base)
  reverbMix: number; // 0 to 1
  reverbSize: number; // Duration in seconds (0.1 to 10.0)
  reverbDamping: number; // 0 (Bright) to 1 (Dark)
  reverbDiffusion?: number; // 0 (Grainy) to 1 (Smooth)

  // Delay Unit
  delayMix: number; // 0 to 1
  delayTime: number; // Seconds
  delayFeedback: number; // 0 to 0.95

  // Dynamics (Compressor/Limiter) (Global)
  compressorThreshold: number; // dB (-60 to 0)
  compressorRatio: number; // 1 to 20
  compressorRelease: number; // seconds

  // Arp Settings
  arpConfig?: ArpConfig;

  // Vocal/Formant legacy fields (optional for migration)
  formantStrength?: number;
  vowel?: number;
  aspirationGain?: number;
  aspirationCutoff?: number;
}

// Slot Types
export type PresetSlot = 'normal' | 'latch' | 'strum' | 'brass' | 'keys' | 'percussion';
export type PlayMode = PresetSlot; // Alias for backward compatibility
export type PlaybackMode = 'gate' | 'trigger' | 'latch'; // Behavior type

export interface PresetState {
    normal: SynthPreset;
    latch: SynthPreset;
    strum: SynthPreset;
    brass: SynthPreset; // Renamed from voice
    keys: SynthPreset; // Renamed from arpeggio
    percussion: SynthPreset; // New Mode
}

export interface StoreState {
    settings: AppSettings;
    presets: PresetState;
    userBank: SynthPreset[]; // 20 Save Slots
}

export interface LatticeNode {
  id: string; // Coordinate key "0,0,0,0,0:oct"
  ratio: number; // Absolute Frequency multiplier (including octave)
  n: number; // Numerator (adjusted for octave)
  d: number; // Denominator (adjusted for octave)
  label: string; 
  x: number; // Screen X
  y: number; // Screen Y
  limitTop: number; 
  limitBottom: number;
  maxPrime: number; // For Z-sorting
  coords: number[]; // [p3, p5, p7, p9, p11, p13, p15]
  octave: number; // -2, -1, 0, 1, 2
}

export interface LatticeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  limit: number;
  sourceId: string;
  targetId: string;
}

export interface ActiveVoice {
  id: string; // Pointer ID or Node ID
  nodeId?: string;
  stop: () => void;
  setDetune: (cents: number) => void;
}

export interface GenerationOrigin {
  coords: number[];
  octave: number;
}

import React, { useState, useMemo } from 'react';
import { SynthPreset, OscillatorConfig, ModulationRow, ReverbType, PresetState, PlayMode, ArpDirection } from '../types';
import { PRESETS, REVERB_DEFAULTS } from '../constants';
import { useStore } from '../services/Store';
import OscillatorPanel from './synth/OscillatorPanel';
import ModMatrixPanel from './synth/ModMatrixPanel';
import EffectsPanel from './synth/EffectsPanel';

interface Props {
  presets: PresetState;
  onChange: (mode: PlayMode, p: SynthPreset) => void;
  isOpen: boolean;
  onClose: () => void;
}

const SynthControls: React.FC<Props> = ({ presets, onChange, isOpen, onClose }) => {
  const [activeVoiceMode, setActiveVoiceMode] = useState<PlayMode>('normal');
  const [activeTab, setActiveTab] = useState<'osc1' | 'osc2' | 'osc3' | 'matrix' | 'fx' | 'arp'>('osc1');
  const { userBank, saveUserPatch } = useStore();

  const [isSaveMode, setIsSaveMode] = useState(false);
  const [saveSlotIndex, setSaveSlotIndex] = useState(0);
  const [saveName, setSaveName] = useState("");

  const categorizedPresets = useMemo(() => {
      const groups: Record<string, SynthPreset[]> = {};
      PRESETS.forEach(p => {
          const cat = p.category || 'Uncategorized';
          if (!groups[cat]) groups[cat] = [];
          groups[cat].push(p);
      });
      return groups;
  }, []);

  if (!isOpen) return null;

  const currentPreset = presets[activeVoiceMode];

  // --- Handlers for Child Components ---

  const handleGlobalUpdate = (key: keyof SynthPreset, val: any) => {
    onChange(activeVoiceMode, { ...currentPreset, [key]: val });
  };

  const handleArpUpdate = (key: keyof import('../types').ArpConfig, val: any) => {
      const currentArp = currentPreset.arpConfig || { direction: 'order', division: '1/8', octaves: 1, gate: 0.8, swing: 0, length: 8, probability: 1.0, humanize: 0 };
      const newArp = { ...currentArp, [key]: val };
      onChange(activeVoiceMode, { ...currentPreset, arpConfig: newArp });
  };

  const handleOscUpdate = (oscKey: 'osc1' | 'osc2' | 'osc3', key: keyof OscillatorConfig, val: any) => {
      const newOsc = { ...currentPreset[oscKey], [key]: val };
      onChange(activeVoiceMode, { ...currentPreset, [oscKey]: newOsc });
  };

  const handleMatrixUpdate = (newMatrix: ModulationRow[]) => {
      onChange(activeVoiceMode, { ...currentPreset, modMatrix: newMatrix });
  };

  const handleReverbTypeChange = (type: ReverbType) => {
      const defaults = REVERB_DEFAULTS[type];
      onChange(activeVoiceMode, {
          ...currentPreset,
          reverbType: type,
          reverbSize: defaults.size,
          reverbDamping: defaults.damping,
          reverbDiffusion: defaults.diffusion
      });
  };

  // --- Preset Management ---

  const loadPreset = (p: SynthPreset) => {
      if (p.isHeader) return;
      const cloned = JSON.parse(JSON.stringify(p));
      onChange(activeVoiceMode, cloned);
  };

  const handleResetToDefault = () => {
      const factory = PRESETS.find(p => p.name === currentPreset.name);
      if (factory) {
          loadPreset(factory);
      } else {
          const userP = userBank.find(p => p.name === currentPreset.name);
          if (userP) loadPreset(userP);
      }
  };

  const handleSaveToSlot = () => {
      if (saveName.trim() === "") return;
      const presetToSave = { ...currentPreset, name: saveName, id: `user-${Date.now()}` };
      saveUserPatch(saveSlotIndex, presetToSave);
      setIsSaveMode(false);
  };

  const arpConfig = currentPreset.arpConfig || { direction: 'order', division: '1/8', octaves: 1, gate: 0.8, swing: 0, length: 8, probability: 1.0, humanize: 0 };

  const getModeLabel = (mode: PlayMode): string => {
      switch(mode) {
          case 'normal': return 'STRINGS';
          case 'latch': return 'DRONE';
          case 'strum': return 'PLUCKED';
          case 'brass': return 'BRASS';
          case 'keys': return 'KEYS';
          case 'percussion': return 'PERC';
          default: return mode;
      }
  };

  return (
    <div className="fixed top-0 right-0 h-full w-[450px] bg-slate-800/95 backdrop-blur shadow-2xl z-[200] transform transition-transform p-0 overflow-hidden border-l border-slate-700 flex flex-col">
        {/* Header */}
        <div className="flex justify-between items-center p-6 pb-2">
            <h2 className="text-xl font-bold">Synth Engine</h2>
            <button onClick={onClose} className="text-slate-400 hover:text-white">Close</button>
        </div>

        {/* Mode Selector */}
        <div className="flex border-b border-slate-700 bg-slate-900/80 mx-4 mt-2 rounded-t-lg overflow-hidden">
            {(['latch', 'normal', 'strum', 'brass', 'keys', 'percussion'] as PlayMode[]).map(mode => (
                <button
                    key={mode}
                    onClick={() => setActiveVoiceMode(mode)}
                    className={`flex-1 py-3 text-[10px] font-bold uppercase transition border-b-2 ${activeVoiceMode === mode ? 'border-indigo-500 text-indigo-400 bg-slate-800' : 'border-transparent text-slate-500 hover:bg-slate-800/50'}`}
                >
                    {getModeLabel(mode)}
                </button>
            ))}
        </div>

        {/* Preset Bar */}
        {!isSaveMode ? (
            <div className="px-6 py-4 bg-slate-800 border-b border-slate-700 space-y-3">
                <div>
                    <label className="block text-[10px] text-slate-400 mb-1 uppercase font-bold tracking-wider">Active Patch</label>
                    <div className="relative">
                        <select 
                            value={currentPreset.name}
                            onChange={(e) => {
                                let p = PRESETS.find(pr => pr.name === e.target.value);
                                if (!p) p = userBank.find(pr => pr.name === e.target.value);
                                if (p) loadPreset(p);
                            }}
                            className="w-full bg-slate-900 border border-slate-600 rounded p-2 text-sm text-white appearance-none focus:border-indigo-500 focus:outline-none"
                        >
                            {Object.keys(categorizedPresets).map(cat => (
                                <optgroup key={cat} label={cat}>
                                    {categorizedPresets[cat].map(p => {
                                        if (p.isHeader) {
                                            return (
                                                <option key={p.id} disabled style={{ fontWeight: 'bold', color: '#a5b4fc', backgroundColor: '#1e293b' }}>
                                                    {p.name}
                                                </option>
                                            );
                                        }
                                        return <option key={p.id} value={p.name}>{p.name}</option>;
                                    })}
                                </optgroup>
                            ))}
                            <optgroup label="User Bank">{userBank.map((p, idx) => (<option key={`user-${idx}`} value={p.name}>{p.name}</option>))}</optgroup>
                        </select>
                    </div>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => { setSaveName(currentPreset.name); setIsSaveMode(true); }} className="flex-1 py-1.5 bg-indigo-700 hover:bg-indigo-600 text-indigo-100 text-xs font-bold rounded transition border border-indigo-500">Save to Slot</button>
                    <button onClick={handleResetToDefault} className="flex-1 py-1.5 bg-yellow-700 hover:bg-yellow-600 text-yellow-100 text-xs font-bold rounded transition border border-yellow-500">Reset to Default</button>
                </div>
            </div>
        ) : (
            <div className="px-6 py-4 bg-indigo-900/20 border-b border-indigo-500/30">
                <div className="flex justify-between items-center mb-2">
                    <label className="text-[10px] text-indigo-300 font-bold uppercase">Save Current Patch</label>
                    <button onClick={() => setIsSaveMode(false)} className="text-xs text-slate-400 hover:text-white">Cancel</button>
                </div>
                <input type="text" value={saveName} onChange={(e) => setSaveName(e.target.value)} placeholder="Patch Name" className="w-full bg-slate-900 border border-indigo-500 rounded p-2 text-sm mb-2 text-white" />
                <select value={saveSlotIndex} onChange={(e) => setSaveSlotIndex(parseInt(e.target.value))} className="w-full bg-slate-900 border border-slate-600 rounded p-2 text-sm text-white mb-3">
                    {userBank.map((p, idx) => (<option key={idx} value={idx}>Slot {idx+1}: {p.name}</option>))}
                </select>
                <button onClick={handleSaveToSlot} className="w-full py-2 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded text-xs transition">Confirm Save</button>
            </div>
        )}

        {/* Navigation Tabs */}
        <div className="flex border-b border-slate-700 bg-slate-900/50">
            {(['osc1', 'osc2', 'osc3'] as const).map(osc => (
                 <button key={osc} onClick={() => setActiveTab(osc)} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === osc ? 'text-indigo-400 border-b-2 border-indigo-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                    <span>{osc.replace('osc', 'Osc ')}</span>
                    <span className={`w-1.5 h-1.5 rounded-full ${currentPreset[osc].enabled ? 'bg-green-500 shadow-[0_0_5px_rgba(34,197,94,0.8)]' : 'bg-slate-700'}`}></span>
                </button>
            ))}
             <button onClick={() => setActiveTab('matrix')} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === 'matrix' ? 'text-purple-400 border-b-2 border-purple-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                <span>Mods</span>
                <span className={`w-1.5 h-1.5 rounded-full ${(currentPreset.modMatrix?.length || 0) > 0 ? 'bg-purple-500 shadow-[0_0_5px_rgba(168,85,247,0.8)]' : 'bg-slate-700'}`}></span>
            </button>
             <button onClick={() => setActiveTab('fx')} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === 'fx' ? 'text-green-400 border-b-2 border-green-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                <span>FX</span>
                <span className="w-1.5 h-1.5 rounded-full bg-green-500 shadow-[0_0_5px_rgba(34,197,94,0.8)]"></span>
            </button>
             <button onClick={() => setActiveTab('arp')} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === 'arp' ? 'text-red-400 border-b-2 border-red-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                <span>Arp</span>
                <span className={`w-1.5 h-1.5 rounded-full bg-red-500 shadow-[0_0_5px_rgba(239,68,68,0.8)]`}></span>
            </button>
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto p-6 scrollbar-thin scrollbar-thumb-slate-700">
            {activeTab === 'osc1' && (
                <OscillatorPanel 
                    label="Oscillator 1" 
                    config={currentPreset.osc1} 
                    isPrimary={true} 
                    onUpdate={(k, v) => handleOscUpdate('osc1', k, v)} 
                />
            )}

            {activeTab === 'osc2' && (
                <OscillatorPanel 
                    label="Oscillator 2" 
                    config={currentPreset.osc2} 
                    onUpdate={(k, v) => handleOscUpdate('osc2', k, v)} 
                />
            )}

            {activeTab === 'osc3' && (
                <OscillatorPanel 
                    label="Oscillator 3" 
                    config={currentPreset.osc3} 
                    onUpdate={(k, v) => handleOscUpdate('osc3', k, v)} 
                />
            )}

            {activeTab === 'matrix' && (
                <ModMatrixPanel 
                    modMatrix={currentPreset.modMatrix || []} 
                    onChange={handleMatrixUpdate} 
                />
            )}

            {activeTab === 'fx' && (
                <EffectsPanel 
                    preset={currentPreset} 
                    isReverbEditable={activeVoiceMode === 'normal'} 
                    onUpdate={handleGlobalUpdate} 
                    onReverbTypeChange={handleReverbTypeChange} 
                />
            )}

            {activeTab === 'arp' && (
                <div className="space-y-6 animate-in fade-in duration-300">
                    <h3 className="text-sm font-bold text-slate-300 uppercase mb-2">Granular Arp Settings ({getModeLabel(activeVoiceMode)})</h3>
                    <div className="p-4 bg-slate-900/50 rounded border border-slate-700 space-y-4">

                        <div>
                            <label className="block text-xs font-bold text-slate-400 mb-1">Direction</label>
                            <div className="flex bg-slate-800 rounded border border-slate-600 overflow-hidden">
                                {(['order', 'up', 'down', 'updown', 'random'] as ArpDirection[]).map(dir => (
                                    <button 
                                        key={dir} 
                                        onClick={() => handleArpUpdate('direction', dir)}
                                        className={`flex-1 py-1 text-[10px] uppercase font-bold ${arpConfig.direction === dir ? 'bg-red-600 text-white' : 'text-slate-400 hover:bg-slate-700'}`}
                                    >
                                        {dir}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Probability</span> <span className="font-bold text-white">{(arpConfig.probability !== undefined ? arpConfig.probability * 100 : 100).toFixed(0)}%</span></label>
                            <input type="range" min="0" max="1" step="0.05" value={arpConfig.probability !== undefined ? arpConfig.probability : 1.0} onChange={(e) => handleArpUpdate('probability', parseFloat(e.target.value))} className="w-full h-1 bg-red-500 rounded appearance-none cursor-pointer" />
                            <p className="text-[9px] text-slate-500 mt-1">Chance of each step playing.</p>
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Humanize</span> <span className="font-bold text-white">{arpConfig.humanize || 0} ms</span></label>
                            <input type="range" min="0" max="100" step="5" value={arpConfig.humanize || 0} onChange={(e) => handleArpUpdate('humanize', parseInt(e.target.value))} className="w-full h-1 bg-red-500 rounded appearance-none cursor-pointer" />
                            <p className="text-[9px] text-slate-500 mt-1">Random timing offset per step.</p>
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Octave Range</span> <span className="font-bold text-white">{arpConfig.octaves}</span></label>
                            <input type="range" min="1" max="4" step="1" value={arpConfig.octaves} onChange={(e) => handleArpUpdate('octaves', parseInt(e.target.value))} className="w-full h-1 bg-red-600 rounded appearance-none cursor-pointer" />
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Swing</span> <span className="font-bold text-white">{arpConfig.swing}%</span></label>
                            <input type="range" min="0" max="100" step="1" value={arpConfig.swing} onChange={(e) => handleArpUpdate('swing', parseInt(e.target.value))} className="w-full h-1 bg-red-600 rounded appearance-none cursor-pointer" />
                        </div>

                    </div>
                    <p className="text-[10px] text-slate-500 text-center italic">Sequence Length and Division are now controlled per-pattern in the matrix view.</p>
                </div>
            )}

            <div className="pt-4 border-t border-slate-700 mt-4">
                <p className="text-[10px] text-slate-500 text-center">Changes applied immediately</p>
            </div>
        </div>
    </div>
  );
};

export default SynthControls;

import { AppSettings, ButtonShape, ChordDefinition, LimitColorMap, ArpeggioDefinition, KeyMappings, BackgroundPreset, SynthPreset } from './types';
import { generateInitPatch } from './patchHelpers';
import { preservedAnalogStrings, STRINGS_PATCHES, PLUCKED_PATCHES } from './bank_strings';
import { ETHEREAL_KEYS, ETHEREAL_MALLETS } from './bank_keys';
import { ATMOSPHERE_PATCHES, BRASS_PATCHES, preservedNoiseWash, preservedDeepOcean } from './bank_winds';
import { ETHEREAL_PADS, ETHEREAL_LEADS, ETHEREAL_BASS, DIAGNOSTIC_PATCHES } from './bank_synth';
import { PERCUSSION_PATCHES } from './bank_percussion';

// Re-export Reverb Defaults from helpers for other consumers
export { REVERB_DEFAULTS } from './patchHelpers';

export const DEFAULT_COLORS: LimitColorMap = {
  1: '#EF4444', // Red (Unity)
  2: '#EF4444', // Red (Octave)
  3: '#EAB308', // Yellow (3-Limit)
